window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0053", [{"word":"generalized","ipa_uk":"/ˈdʒenrəlaɪzd/","ipa_us":"/ˈdʒenrəlaɪzd/","definition_zh":"泛化的；普遍化的；概括性的；（疾病）全身性的","definition_en":"widened from particular cases into a broad rule, or spread through the whole of something rather than staying in one part","core_image":"一张网格纸上零散的小黑点被一支笔连成一大片灰面","scene":"A conclusion generalized from a single village cannot describe the whole country.","sceneCN":"这里 generalized 是「外推成通则的」（第 1 个义项：由个别案例推及一般）；句意：仅从一个村庄外推得出的结论无法描述整个国家。图中可辨识物件：网格纸、灰色填涂面、放大镜、铅笔、指示箭头。","pos":[{"tag":"adj.","zh":"泛化的；普遍化的；概括性的；（疾病）全身性的（多作定语，也可作表语）"}],"collocations":[{"phrase":"generalized conclusion","zh":"泛化的结论；笼统的结论"},{"phrase":"generalized anxiety disorder","zh":"广泛性焦虑障碍"},{"phrase":"generalized seizure","zh":"全身性癫痫发作"},{"phrase":"generalized linear model","zh":"广义线性模型"},{"phrase":"generalized statement","zh":"概括性陈述"},{"phrase":"generalized from a sample","zh":"由样本外推而来"}],"forms":[{"label":"原形（动词）","form":"generalize（英式亦作 generalise）"},{"label":"比较级（更泛化的）","form":"more generalized"},{"label":"最高级（最泛化的）","form":"most generalized"},{"label":"名词形式","form":"generalization（泛化；概括）"}],"derivatives":[{"word":"generalize","pos":"v.","zh":"泛化；概括；推广"},{"word":"generalization","pos":"n.","zh":"概括；泛化；通则"},{"word":"general","pos":"adj. / n.","zh":"一般的；总的；将军"},{"word":"generally","pos":"adv.","zh":"通常；普遍地"},{"word":"generality","pos":"n.","zh":"普遍性；概论；大多数"}],"senses":[{"no":"01","title":"Drawn out into a rule","titleCN":"扩为通则：从个别情形推出一条规律","definition":"taken from particular instances and stated as a rule that covers many of them","definitionCN":"从具体事例中提取出来，并表述为可覆盖众多同类情形的规律","example":"The claim was generalized from three experiments in one laboratory.","exampleCN":"这一主张是从同一个实验室的三次实验中推出来的。","why":"general comes from Latin generalis 'belonging to a whole kind', and -ize means 'to make'; -ed turns the verb into an adjective, so generalized literally means 'made kind-wide'.","whyCN":"general 出自拉丁 generalis“属于整个类别的”，-ize 意为“使成为”，-ed 把动词转为形容词，因此 generalized 字面就是“被做成整类通用的”。"},{"no":"02","title":"Applying to a whole class","titleCN":"适用于整类：不限于某个特例","definition":"valid for a whole group or category rather than for one member of it","definitionCN":"对整个群体或类别有效，而非只对其中某一个成员有效","example":"A generalized rule for all metals must also fit mercury.","exampleCN":"一条适用于所有金属的通则也必须适用于汞。","why":"Once a statement is made general, its scope is the whole kind; the adjective marks that breadth of application.","whyCN":"一旦陈述被“一般化”，其覆盖范围就是整个类别；这个形容词标记的正是这种适用面的宽度。"},{"no":"03","title":"Stated without detail","titleCN":"只给大意的：略去细节的概括说法","definition":"expressed in broad terms, with the specific details left out","definitionCN":"以宽泛的措辞表达，具体细节被略去","example":"He gave a generalized account of the meeting and named no one.","exampleCN":"他对会议只作了笼统叙述，没有点任何人的名字。","why":"To generalize is also to strip away particulars; the participle then describes speech or writing that has lost its specifics.","whyCN":"generalize 同时意味着剥离特殊性；分词形式于是描述那种丢掉了具体细节的言辞或文字。"},{"no":"04","title":"Affecting the whole body","titleCN":"全身性的：医学上波及全身而非局部","definition":"in medicine, of a condition that spreads through the whole body instead of one organ or area","definitionCN":"医学上指疾病波及全身，而不是局限于某个器官或部位","example":"A generalized seizure involves the whole brain rather than one region.","exampleCN":"全身性癫痫发作涉及整个大脑，而不是某一个区域。","why":"Medicine borrowed the 'whole rather than part' sense: a condition that is not localized has been generalized across the body.","whyCN":"医学借用了“整体而非局部”这一层意思：没有局限化的病症，就等于扩散到了全身。"},{"no":"05","title":"Statistical: broadly framed","titleCN":"统计上的广义模型：不绑定某一具体情形","definition":"in statistics, describing a model or method built to cover a wide family of cases rather than one fixed form","definitionCN":"统计学中指为覆盖一大类情形而构建、而非固定于单一形式的模型或方法","example":"The generalized linear model extends ordinary regression to counts and proportions.","exampleCN":"广义线性模型把普通回归扩展到计数与比例数据。","why":"Statistics generalizes the textbook model by loosening one assumption, so the label 'generalized' marks the wider family that results.","whyCN":"统计学通过放宽某一假设来“推广”教科书模型，因此“广义的”这个标签标记的是由此产生的更大模型族。"},{"no":"06","title":"Vague and imprecise","titleCN":"笼统的：不够精确，含批评意味","definition":"used critically of a statement that is so broad that it says very little","definitionCN":"带批评意味地形容某说法宽泛到几乎没说出什么内容","example":"The report's recommendations are too generalized to guide any decision.","exampleCN":"这份报告的建议过于笼统，无法指导任何决策。","why":"Breadth can become emptiness: when a claim covers everything, it distinguishes nothing, and the same adjective turns into a reproach.","whyCN":"宽度可以变成空洞：当一个论断覆盖一切时，它就区分不出任何东西，同一个形容词便转为贬义。"},{"no":"07","title":"Pushed beyond its origin","titleCN":"外推过度的：越过原本成立的范围","definition":"extended to situations beyond the ones in which it was actually established","definitionCN":"被扩展到其实际成立情形之外的场合","example":"Results generalized from mice to humans often fail to hold.","exampleCN":"从小鼠外推到人类的结果往往并不成立。","why":"The -ed form can also record a completed act of transfer, so it names findings that have been carried past the boundary where they were tested.","whyCN":"-ed 形式也可记录一次已完成的迁移动作，因此它指那些被搬过受检验边界之外的发现。"},{"no":"08","title":"Simplified into a pattern","titleCN":"概化成图的：把细节简化为整体图案","definition":"in mapping and design, reduced to a simplified overall pattern by dropping small details","definitionCN":"在地图绘制与设计中，通过删去细小细节而简化为整体图案","example":"A generalized coastline keeps the main bays and drops every inlet.","exampleCN":"概化后的海岸线保留主要海湾，省略所有小湾。","why":"Cartographers call the deliberate thinning of detail generalization; the participle describes a surface that has been treated that way.","whyCN":"制图学把有意删减细节称为 generalization（概化）；这个分词描述的就是经过此种处理的表面。"}],"etymology":{"intro":{"en":"Generalized is an English formation: the adjective general, borrowed from Latin generalis, plus the verb suffix -ize and the past-participle ending -ed. The dates below are approximate.","cn":"generalized 是英语内部构成的词：形容词 general 借自拉丁 generalis，再加动词后缀 -ize 与过去分词词尾 -ed。以下年代均为约数。"},"items":[{"era":"LATIN ROOT","en":"Latin generalis meant 'belonging to a whole kind or class'. It was built on genus 'kind, stock, family', whose deeper root is generally taken to be a Indo-European form meaning 'to beget'. That deeper link is a reconstruction.","cn":"拉丁 generalis 意为“属于整个类别的”，由 genus“种类、族、家系”构成。其更深词根一般被认为是某个意为“生育、产生”的印欧形式，但这属于重构。"},{"era":"OLD FRENCH AND ENGLISH","en":"Generalis passed through Old French as general and entered English in the 13th century as an adjective meaning 'of a whole class'. The first records are legal and religious.","cn":"generalis 经古法语 general 进入英语，13 世纪时作形容词，意为“整类的”。最早记录见于法律与宗教文本。"},{"era":"VERB SUFFIX","en":"The ending -ize comes from Late Latin -izare, itself from Greek -izein, a productive verb-forming suffix. English generalize appears in the 18th century with the sense 'to reduce to a general form'.","cn":"后缀 -ize 来自晚期拉丁 -izare，后者又出自希腊 -izein，是能产的动词构词后缀。英语 generalize 于 18 世纪出现，意为“化为一般形式”。"},{"era":"PAST PARTICIPLE","en":"Adding -ed produced the adjective generalized, first used for statements and later for conditions spread through a whole body or system.","cn":"加上 -ed 构成形容词 generalized，最初用于陈述，后用于波及整个身体或系统的状态。"},{"era":"MODERN TECHNICAL USES","en":"The 20th century added specific technical senses: generalized anxiety in psychiatry, generalized seizure in neurology, generalized linear model in statistics, and generalization in cartography.","cn":"20 世纪增加了专门技术义项：精神病学中的广泛性焦虑、神经学中的全身性发作、统计学中的广义线性模型，以及制图学中的概化。"},{"era":"UNCERTAIN DETAILS","en":"The exact date of the first English use of generalize is uncertain, and the Indo-European root behind Latin genus is a reconstructed form rather than a recorded word.","cn":"generalize 在英语中首次使用的确切年代存疑；拉丁 genus 背后的印欧词根是重构形式，并非有记录的实际词。"}]},"similar":{"note":{"en":"The first group holds words from the same family that are easily swapped; the second holds near-synonyms that stress breadth or vagueness.","cn":"第一组是同族易混词；第二组是强调宽泛或含糊的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"general","ipa":"/ˈdʒenrəl/","tag":"base adjective","definition":"Meaning 'affecting all or most', but attaching to the whole rather than marking a completed act of broadening. A general rule is simply a rule for all; a generalized rule has been made to cover all.","definitionCN":"意为“涉及全体或大多数的”，但它直接修饰整体，不标记一次已完成的推广动作。general rule 是本身就适用于全体的规则；generalized rule 是被推及全体的规则。"},{"word":"generalize","ipa":"/ˈdʒenrəlaɪz/","tag":"verb, not adjective","definition":"The verb meaning 'to draw a general rule'. It names the act, while generalized describes the result of that act.","definitionCN":"动词，意为“归纳出通则”，指动作本身；generalized 描述该动作的结果。"},{"word":"generality","ipa":"/ˌdʒenəˈræləti/","tag":"noun of breadth","definition":"A noun for the quality of being broad, or for a vague statement. It cannot replace the adjective before a noun.","definitionCN":"名词，指宽泛性，也指笼统的说法；不能像形容词那样放在名词前。"},{"word":"generic","ipa":"/dʒəˈnerɪk/","tag":"kind-level, not inferred","definition":"Also from Latin genus, but it means 'characteristic of a whole class' or 'unbranded'. It never implies that someone drew a conclusion from samples.","definitionCN":"同出拉丁 genus，但意为“整类共有的”或“无商标的”，不含“由样本归纳而来”之意。"}]},{"heading":"NEAR MEANING","entries":[{"word":"universal","ipa":"/ˌjuːnɪˈvɜːsl/","tag":"true of all without exception","definition":"Applying to every case whatsoever; stronger than generalized, which only claims broad coverage.","definitionCN":"适用于无一例外的所有情形；比 generalized 更强，后者只声称覆盖广泛。"},{"word":"sweeping","ipa":"/ˈswiːpɪŋ/","tag":"critically too broad","definition":"Wide in scope and often too broad to be accurate; it carries the same critical edge as sense 6 but more force.","definitionCN":"范围宽大且常宽到不准确；与第 6 个义项同样带批评意味，但语气更强。"},{"word":"broad","ipa":"/brɔːd/","tag":"wide in coverage","definition":"Covering a large range; a neutral word for width that does not say whether the width was earned.","definitionCN":"覆盖范围大；是中性的“宽”，不说明这种宽是否站得住。"},{"word":"vague","ipa":"/veɪɡ/","tag":"unclear in outline","definition":"Not clearly expressed or defined; it targets unclear boundaries rather than wide coverage.","definitionCN":"表达或界定不清；它针对的是边界模糊，而不是覆盖范围大。"},{"word":"widespread","ipa":"/ˈwaɪdspred/","tag":"found in many places","definition":"Present or occurring over a large area; it spreads across space, not across categories of cases.","definitionCN":"在大片区域内存在或发生；它是在空间上铺开，而不是在事例类别上推广。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"general + -ize 'make' + -ed: something has been made general.","cn":"general + -ize“使成为”+ -ed：某事物被做成了通用的。"},{"en":"The base genus means 'kind', so generalized keeps the image of one member standing for the whole kind.","cn":"词基 genus 意为“种类”，所以 generalized 保留了“一个成员代表整个类别”的意象。"},{"en":"Fixed phrases show the range: generalized anxiety, generalized seizure, generalized linear model, generalized statement.","cn":"固定搭配展示了义项范围：广泛性焦虑、全身性发作、广义线性模型、概括性陈述。"},{"en":"The family runs generalize, generalization, general, generally, generality and generic.","cn":"同族词包括 generalize、generalization、general、generally、generality、generic。"},{"en":"generic looks like a synonym but means 'class-wide or unbranded', not 'inferred from cases'.","cn":"generic 看似同义，实际意为“整类共有的或无商标的”，不是“由个案归纳来的”。"}],"abstract":[{"en":"Picture a single footprint being copied until it covers a whole field of snow.","cn":"想象一个脚印被复制，直到覆满整片雪地。"},{"en":"Picture a narrow funnel opening into a wide mouth: many small cases pour in and one broad rule comes out.","cn":"想象一个窄漏斗通向宽口：许多小案例灌进去，一条宽规则流出来。"},{"en":"Picture a painter filling every separate cell with the same grey until the grid reads as one surface.","cn":"想象画者把每个小格都填成同一种灰，直到整张网格看起来只有一整片。"}]},"examples":[{"en":"The authors admitted that their model was generalized from data collected in one climate zone.","cn":"作者承认，他们的模型是从一个气候带收集的数据外推而来的。"},{"en":"A generalized anxiety disorder is not tied to any single situation.","cn":"广泛性焦虑障碍并不与任何单一情境绑定。"},{"en":"Generalized maps sacrifice small inlets in order to show the shape of the coast.","cn":"概化地图牺牲小海湾，以显示海岸的整体形状。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“将军（general）下令，一概而论”——由个别推到全体 → generalized 泛化的、全身性的","word":"generalized"},"root":"拉丁 generalis“属于整类的”← genus“种类、族”；英语 general + -ize（使成为）+ -ed（形容词化）。","sensesIntro":{"en":"Eight senses follow one movement: a single case is stretched until it stands for the whole class, and that stretch can be useful, vague, or risky.","cn":"八个义项沿着一个动作展开：单个案例被拉宽到代表整类，而这一拉宽可以有用、可以空洞，也可以有风险。"},"semanticMap":{"core":{"en":"CORE IMAGE: scattered dots fused by one stroke into a single broad grey area.","cn":"核心意象：零散的点被一笔连成一整片宽大的灰色。"},"chain":["MAKE GENERAL","COVER THE CLASS","DROP DETAIL","SPREAD THROUGH THE BODY","WIDEN THE MODEL","FLATTEN INTO A PATTERN"],"branches":[{"senses":"01 · 02","en":"RULE-MAKING: a conclusion drawn from single cases and given the scope of a whole class.","cn":"立规则：由单个案例得出的结论被赋予整类的适用范围。"},{"senses":"03 · 06","en":"LOSING DETAIL: the same widening thins specifics until the statement becomes empty.","cn":"失去细节：同一过程把具体信息稀释，直到陈述变得空洞。"},{"senses":"04","en":"WHOLE BODY: medicine applies 'not localized' quite literally to disease.","cn":"全身：医学把“非局部”直接用于疾病。"},{"senses":"05","en":"WIDE MODEL: statistics broadens a fixed model into a family by relaxing one assumption.","cn":"宽模型：统计学放宽一个假设，把固定模型扩展成模型族。"},{"senses":"07 · 08","en":"TWO DIRECTIONS: one goes too far beyond the evidence, the other deliberately simplifies a surface into a pattern.","cn":"两个方向：一个是越出证据之外走得太远，另一个是有意把表面简化为图案。"}]},"affixes":{"intro":{"en":"Generalized is a transparent English build: a Latin-borrowed adjective, a Greek-derived verb suffix, and an Old English participial ending.","cn":"generalized 的构造清晰可拆：一个借自拉丁的形容词、一个源自希腊的动词后缀、一个古英语分词词尾。"},"latinIntro":{"en":"The root genus 'kind' supplies a large family: general, generate, generation, genus, generic, generous and genius all trace back to the same 'begetting, kind' source, though each entered English by its own path.","cn":"词根 genus“种类”衍生出庞大的词族：general、generate、generation、genus、generic、generous、genius 都可追溯到同一个“生育、种类”的来源，但各自经不同路径进入英语。"},"items":[{"word":"generalized","structure":"general + -ize + -ed (past participle)","meaning":"made broad or spread through the whole","meaningCN":"被泛化的；波及全身的","example":"A generalized rule must still be tested case by case.","exampleCN":"泛化的规则仍必须逐例检验。"},{"word":"generalize","structure":"general + -ize (to make)","meaning":"to draw a broad rule from particulars","meaningCN":"由个别得出通则；推广","example":"It is risky to generalize from one season of data.","exampleCN":"仅凭一季数据就作概括是有风险的。"},{"word":"generalization","structure":"generalize + -ation (noun of action)","meaning":"the act of broadening, or the broad statement produced","meaningCN":"概括行为；由此得出的概括性说法","example":"The paper offers a cautious generalization about urban growth.","exampleCN":"这篇论文对城市增长提出了谨慎的概括。"},{"word":"general","structure":"Latin generalis (of a whole kind)","meaning":"affecting all or most; not detailed","meaningCN":"总的；普遍的；不细的","example":"The general pattern holds across all four regions.","exampleCN":"总格局在四个地区都成立。"},{"word":"generally","structure":"general + -ly (adverb of manner)","meaning":"in most cases; as a broad statement","meaningCN":"通常；大体上","example":"Generally, warmer seas hold less dissolved oxygen.","exampleCN":"一般来说，较暖的海水溶解氧更少。"},{"word":"generality","structure":"general + -ity (abstract noun)","meaning":"the quality of being broad; a vague statement","meaningCN":"宽泛性；笼统说法","example":"The argument loses force at that level of generality.","exampleCN":"在那种笼统程度上，这个论证失去了力度。"},{"word":"generic","structure":"gener- (kind) + -ic (adjective)","meaning":"shared by a whole class; without a brand name","meaningCN":"整类共有的；无商标的","example":"The generic form of the drug costs a third as much.","exampleCN":"该药物的非专利剂型价格只有三分之一。"},{"word":"genus","structure":"Latin genus (kind, stock)","meaning":"a biological group above species","meaningCN":"生物学上的属","example":"The species belongs to a genus found only in Antarctica.","exampleCN":"该物种属于一个仅见于南极洲的属。"}],"latinEntries":[{"word":"genus","structure":"genus, generis (n., third declension)","meaning":"kind, stock, family, race","meaningCN":"种类；族；家系"},{"word":"generalis","structure":"genus + -alis (belonging to)","meaning":"belonging to a whole kind or class","meaningCN":"属于整个类别的"},{"word":"-izare","structure":"Late Latin -izare < Greek -izein","meaning":"verb-forming suffix meaning 'to make or do'","meaningCN":"动词后缀，意为“使之成为、做”"}]}},{"word":"geographical","ipa_uk":"/ˌdʒiːəˈɡræfɪkl/","ipa_us":"/ˌdʒiːəˈɡræfɪkl/","definition_zh":"地理的；地理学的；地理位置的；按地区划分的","definition_en":"relating to geography, to the physical features and arrangement of places on the earth, or to the way things are distributed across regions","core_image":"一张摊开的等高线地图，河流与山脊被细线描出","scene":"In geographical terms the two towns are close, yet a mountain range separates them.","sceneCN":"这里 geographical 是「地理位置上」的（第 1 个义项：就空间位置而言）；句意：从地理上说这两座城镇很近，却有一道山脉把二者隔开。图中可辨识物件：等高线地图、山脉符号、河流、比例尺、指南针。","pos":[{"tag":"adj.","zh":"地理的；地理学的；地理位置的；按地区划分的（多作定语）"}],"collocations":[{"phrase":"geographical area","zh":"地理区域"},{"phrase":"geographical distribution","zh":"地理分布"},{"phrase":"geographical indication","zh":"地理标志（贸易与知识产权术语）"},{"phrase":"geographical barrier","zh":"地理屏障"},{"phrase":"geographical scope","zh":"地理范围；适用范围"},{"phrase":"geographical variation","zh":"地理变异"}],"forms":[{"label":"比较级（更地理的）","form":"more geographical"},{"label":"最高级（最地理的）","form":"most geographical"},{"label":"副词形式","form":"geographically（地理上；就地理位置而言）"},{"label":"同义变体（更常用）","form":"geographic（多用于北美，作定语时更常见）"}],"derivatives":[{"word":"geography","pos":"n.","zh":"地理学；地形；地理分布"},{"word":"geographer","pos":"n.","zh":"地理学家；地理教师"},{"word":"geographic","pos":"adj.","zh":"地理的（更常用的变体）"},{"word":"geographically","pos":"adv.","zh":"在地理上；按地理位置"},{"word":"geopolitics","pos":"n.","zh":"地缘政治（共用 geo- 前缀）"}],"senses":[{"no":"01","title":"Of location on the earth","titleCN":"地理位置的：就所处空间而言","definition":"relating to where a place sits on the earth's surface","definitionCN":"关于某地在球面上所处位置的","example":"Their geographical position makes the harbour ice-free all winter.","exampleCN":"它们的地理位置使这个港口整个冬天不结冰。","why":"geo- is Greek for 'earth' and -graphy means 'writing, description'; geographical therefore marks anything to do with describing the earth's places.","whyCN":"geo- 是希腊语“大地”，-graphy 意为“书写、描述”，因此 geographical 标记的是与描述大地各处有关的事物。"},{"no":"02","title":"Of geography as a science","titleCN":"地理学的：作为一门学科","definition":"belonging to the academic study of the earth's surface, climate and human use of it","definitionCN":"属于研究地表、气候及人类利用方式的学科","example":"The journal publishes geographical research on migration.","exampleCN":"该刊发表关于人口迁移的地理学研究。","why":"Once geography became a university discipline in the 19th century, the adjective also named its methods, journals and departments.","whyCN":"地理学在 19 世纪成为大学学科之后，这个形容词也用来指称其方法、刊物与院系。"},{"no":"03","title":"Of terrain and landforms","titleCN":"地形地貌的：山川起伏本身","definition":"relating to the physical shape of the land, such as mountains, valleys and coasts","definitionCN":"关于山地、谷地、海岸等自然地表形态的","example":"Geographical features such as ridges decide where roads can run.","exampleCN":"山脊这样的地形特征决定了道路可以往哪里修。","why":"The earliest geography described the visible face of the earth; the adjective still points to relief and drainage rather than to people.","whyCN":"最早的地理学描述的是大地可见的表面；这个形容词至今仍可指起伏与水系，而非人群。"},{"no":"04","title":"Divided by region","titleCN":"按地区划分的：以区域为单位","definition":"organized or counted separately for each region","definitionCN":"按区域分别组织或统计的","example":"Sales are reported on a geographical basis, not by product line.","exampleCN":"销售额按地区而非按产品线报告。","why":"Because geography partitions the world into regions, the adjective came to describe any arrangement that follows regional boundaries.","whyCN":"由于地理学把世界划分为区域，这个形容词便用来描述任何沿区域边界作出的安排。"},{"no":"05","title":"Of spatial distribution","titleCN":"空间分布的：物种或现象铺开的样子","definition":"relating to how something is spread across space","definitionCN":"关于某物在空间上如何铺展开的","example":"The geographical distribution of the beetle stops at the frost line.","exampleCN":"这种甲虫的地理分布止于霜冻线。","why":"Distribution needs a map: the adjective ties a pattern of occurrence to the places where it holds.","whyCN":"分布需要一张地图：这个形容词把出现规律与发生地点绑定起来。"},{"no":"06","title":"Of a place's physical setting","titleCN":"地理环境的：某地的自然条件","definition":"relating to the natural conditions of a particular place, such as climate, soil and water","definitionCN":"关于某地气候、土壤、水源等自然条件的","example":"Geographical conditions limit how much rice the valley can produce.","exampleCN":"地理环境条件限制了这条谷地能产多少稻米。","why":"Place-based description shifts from 'where it is' to 'what it is like there', which is the environmental reading of the same word.","whyCN":"以地点为基础的描述从“它在哪”转向“那里条件如何”，这就是同一个词的环境义读法。"},{"no":"07","title":"Of a trade origin label","titleCN":"地理标志的：产地名称的法律保护","definition":"in trade law, naming a product whose reputation is tied to a specific place","definitionCN":"贸易法中指产品声誉与特定产地绑定的名称保护","example":"Champagne is protected as a geographical indication in many markets.","exampleCN":"香槟在许多市场作为地理标志受到保护。","why":"If a product's quality comes from its region, the region's name becomes the legal asset; the adjective marks that kind of protected name.","whyCN":"当产品品质源自其地区时，地区名本身就成了法律资产；这个形容词标记的正是这类受保护的名称。"},{"no":"08","title":"Of maps and coordinates","titleCN":"地图与坐标的：测绘所用的","definition":"relating to mapping, survey grids and coordinates","definitionCN":"关于地图绘制、测量网格与坐标的","example":"Every site is recorded with its geographical coordinates.","exampleCN":"每个地点都用其地理坐标记录。","why":"Description of the earth requires a grid; the adjective extends from the described surface to the instruments that describe it.","whyCN":"描述大地需要一套网格；这个形容词从被描述的表面延伸到用于描述它的工具。"}],"etymology":{"intro":{"en":"Geographical joins Greek geo- 'earth' and -graphical 'relating to writing or drawing', through the ancient compound geographia 'description of the earth'. Dates are approximate.","cn":"geographical 由希腊 geo-“大地”与 -graphical“与书写、描绘有关的”组合而成，中间经过古代复合词 geographia“对大地的描述”。年代为约数。"},"items":[{"era":"GREEK COMPOUND","en":"Greek gē meant 'earth, land', and graphein meant 'to write, scratch, draw'. Joined as geōgraphia, the compound meant 'a writing about the earth'. The coinage is generally attributed to Eratosthenes in the 3rd century BC.","cn":"希腊 gē 意为“大地、陆地”，graphein 意为“书写、刻画、描绘”。合为 geōgraphia，意为“关于大地的记述”。该复合词的创制一般认为是公元前 3 世纪的埃拉托色尼。"},{"era":"LATIN AND FRENCH","en":"Latin took the word as geographia, and French formed géographie. English geography appears in the 16th century alongside the older borrowings of the same Greek stems.","cn":"拉丁语借作 geographia，法语构成 géographie。英语 geography 于 16 世纪出现，与同一希腊词干的更早借词并行。"},{"era":"ADJECTIVE SUFFIX","en":"The ending -ical comes from Latin -icalis, itself from Greek -ikos, the suffix that makes 'relating to' adjectives. Latin geographicus and Greek geōgraphikos both existed.","cn":"后缀 -ical 来自拉丁 -icalis，后者又出自希腊 -ikos，即构成“与……有关”形容词的后缀。拉丁 geographicus 与希腊 geōgraphikos 均已存在。"},{"era":"ENGLISH ADJECTIVE","en":"Geographical enters English in the 16th century as the adjective of the new discipline, competing with geographic ever since.","cn":"geographical 于 16 世纪进入英语，作为这门新学科的形容词，此后一直与 geographic 并存竞争。"},{"era":"MODERN EXTENSIONS","en":"The 20th century added geographical indication in trade law and geographical information systems in computing, both extending 'about places' into new fields.","cn":"20 世纪新增了贸易法中的地理标志与计算领域的地理信息系统，都把“关于地点”延伸到新领域。"},{"era":"UNCERTAIN DETAILS","en":"The date of Eratosthenes' coinage is reported by later writers rather than by a surviving title page, and the deeper origin of graphein is disputed; it is often linked to a root meaning 'to scratch'.","cn":"埃拉托色尼创制此词的年代来自后世记述，而非存世的书名页；graphein 的更深来源有争议，常被联系到一个意为“刻划”的词根。"}]},"similar":{"note":{"en":"The first group contains close spelling relatives from the same roots; the second contains words about space and place that do not share the earth-description core.","cn":"第一组是同根形近词；第二组是谈空间与地点、但不含“描述大地”这一核心的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"geographic","ipa":"/ˌdʒiːəˈɡræfɪk/","tag":"same meaning, shorter form","definition":"The shorter adjective of geography, preferred in North American usage before nouns. It differs from geographical in style, not in sense.","definitionCN":"geography 的较短形容词，北美用法中更常置于名词前；与 geographical 的差别在风格而非词义。"},{"word":"geographical","ipa":"/ˌdʒiːəˈɡræfɪkl/","tag":"this entry","definition":"The longer form, common in British usage and in fixed terms such as geographical indication.","definitionCN":"较长形式，常见于英式用法及 geographical indication 等固定术语。"},{"word":"geologically","ipa":"/ˌdʒiːəˈlɒdʒɪkli/","tag":"different second element","definition":"An adverb about rock structure and deep time, from -logy 'study', not from -graphy 'description'. It answers 'how old and how formed', not 'where'.","definitionCN":"副词，谈岩层构造与漫长年代，来自 -logy“研究”而非 -graphy“描述”；它回答“多古老、怎么形成”，而非“在哪里”。"},{"word":"geometric","ipa":"/ˌdʒiːəˈmetrɪk/","tag":"same geo-, different stem","definition":"Relating to shape and measurement, from metron 'measure'. It shares geo- with geographical but has nothing to do with places.","definitionCN":"关于形状与度量，来自 metron“测量”；与 geographical 共用 geo-，但与地点无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"spatial","ipa":"/ˈspeɪʃl/","tag":"space in general","definition":"Relating to space and position in any frame, including rooms and graphs; it does not require the earth's surface.","definitionCN":"关于任何框架中的空间与位置，包括房间和图表；不要求涉及地表。"},{"word":"territorial","ipa":"/ˌterɪˈtɔːriəl/","tag":"land under control","definition":"Relating to territory held by a state or animal; it adds ownership or defence, which geographical does not.","definitionCN":"关于国家或动物所占的领地；带有归属或防卫含义，而 geographical 没有。"},{"word":"regional","ipa":"/ˈriːdʒənl/","tag":"larger than local","definition":"Relating to a region within a country; it names an administrative scale rather than a physical setting.","definitionCN":"关于国内某一区域；标明的是一种行政尺度，而非自然条件。"},{"word":"topographical","ipa":"/ˌtɒpəˈɡræfɪkl/","tag":"surface relief","definition":"Relating specifically to the detailed relief of a surface, from topos 'place' and graphein 'write'; narrower than geographical.","definitionCN":"专指地表起伏细节，来自 topos“地点”与 graphein“书写”；比 geographical 更窄。"},{"word":"physical","ipa":"/ˈfɪzɪkl/","tag":"natural, not human","definition":"In geography, 'physical' contrasts natural features with human ones; the pair physical geography and human geography marks that split.","definitionCN":"在地理学中，“自然的”与“人文的”相对；自然地理与人文地理这一对术语正体现该分工。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词。"},"normal":[{"en":"geo- 'earth' + graph- 'write' + -ical: a written description of the earth.","cn":"geo-“大地”+ graph-“书写”+ -ical：对大地所作的书面描述。"},{"en":"geography is the noun, geographer the person, geographic and geographical the adjectives, geographically the adverb.","cn":"geography 是名词，geographer 指人，geographic 与 geographical 是形容词，geographically 是副词。"},{"en":"The phrase geographical distribution is the standard label for range maps.","cn":"地理分布是分布图的标准说法。"},{"en":"geographical indication is a legal term, not a synonym for location.","cn":"地理标志是法律术语，不是“位置”的同义词。"},{"en":"geology, geometry and geography all begin with geo-, but their second elements mean study, measure and write.","cn":"geology、geometry、geography 都以 geo- 开头，但第二部分分别是研究、测量、书写。"}],"abstract":[{"en":"Picture a folded map spread on a table, its contour lines tightening as the hills rise.","cn":"想象一张摊在桌上的折叠地图，山越高，等高线越密。"},{"en":"Picture a dotted range map where the dots stop exactly at a cold coastline.","cn":"想象一张打点分布图，点阵恰好在寒冷的海岸线处停止。"},{"en":"Picture a wine bottle whose label carries a place name protected by law.","cn":"想象一只酒瓶，标签上印着受法律保护的产地名。"}]},"examples":[{"en":"Geographical barriers kept the two languages apart for centuries.","cn":"地理屏障使这两种语言分隔了数个世纪。"},{"en":"The team compared the geographical spread of the disease across three provinces.","cn":"研究组比较了该疾病在三个省份的地理分布。"},{"en":"Under the agreement, the name can no longer be used as a geographical indication by other producers.","cn":"根据该协议，其他生产者不得再将该名称作为地理标志使用。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“记（geo）一下地图（graph）” → geographical 地理的、按地区划分的","word":"geographical"},"root":"希腊 gē“大地”+ graphein“书写、描绘”→ geōgraphia“对大地的记述”；拉丁 geographia、法语 géographie → 英语 geography + -ical。","sensesIntro":{"en":"Eight senses all return to one act: writing down what the earth looks like, and then sorting the world by the places so described.","cn":"八个义项都回到同一个动作：把大地的样子书写下来，再按这样描述出的地点来划分世界。"},"semanticMap":{"core":{"en":"CORE IMAGE: a contour map in which every line writes down the shape of the land.","cn":"核心意象：一张等高线地图，每条线都在书写大地的形状。"},"chain":["DESCRIBE THE EARTH","LOCATE A PLACE","STUDY AS A SCIENCE","READ THE TERRAIN","SORT BY REGION","MAP THE DISTRIBUTION"],"branches":[{"senses":"01 · 02","en":"PLACE AND DISCIPLINE: the adjective serves both the position of a town and the academic study of places.","cn":"位置与学科：这个形容词既服务于一城的位置，也服务于关于地点的学术研究。"},{"senses":"03 · 06","en":"PHYSICAL SETTING: landforms and local climate are the visible and environmental faces of the same description.","cn":"自然条件：地形与地方气候是同一描述的外观面与环境面。"},{"senses":"04 · 05","en":"SORTING SPACE: reporting by region and mapping a range both slice the world along lines drawn on a map.","cn":"切分空间：按地区报告与绘制分布范围，都沿地图上画出的线切开世界。"},{"senses":"07","en":"LEGAL PLACE: a product tied to a region turns a place name into protected property.","cn":"法律上的地点：与地区绑定的产品把地名变成受保护的财产。"},{"senses":"08","en":"THE GRID: coordinates are description made numerical, so the map can be read by machines.","cn":"网格：坐标是数值化的描述，使地图可被机器读取。"}]},"affixes":{"intro":{"en":"Geographical is a three-part build: the Greek prefix geo-, the Greek stem graph-, and the adjective ending -ical. All three are still productive in English.","cn":"geographical 由三部分构成：希腊前缀 geo-、希腊词干 graph-、形容词词尾 -ical。三者在英语中仍有构词能力。"},"latinIntro":{"en":"The same Greek stems travel through Latin borrowings into dozens of English words: geography, geology, geometry, graph, paragraph, photograph, biography and telegraph.","cn":"同一批希腊词干经拉丁借词进入大量英语词：geography、geology、geometry、graph、paragraph、photograph、biography、telegraph。"},"items":[{"word":"geographical","structure":"geo- (earth) + graph- (write) + -ical","meaning":"relating to the description of places on earth","meaningCN":"与描述大地各处有关的","example":"The atlas groups the plates by geographical region.","exampleCN":"这本地图集按地理区域编排图版。"},{"word":"geography","structure":"geo- + -graphy (writing, description)","meaning":"the study or description of the earth's surface","meaningCN":"地理学；对地表的描述","example":"She teaches geography to secondary students.","exampleCN":"她给中学生教地理。"},{"word":"geographer","structure":"geography + -er (person who)","meaning":"a person who studies places","meaningCN":"地理学家","example":"The geographer mapped every village along the river.","exampleCN":"这位地理学家把河边的每个村庄都绘入地图。"},{"word":"geographic","structure":"geo- + graph- + -ic","meaning":"the shorter adjective of geography","meaningCN":"地理的（较短变体）","example":"The report includes a geographic breakdown of sales.","exampleCN":"报告包含按地理划分的销售数据。"},{"word":"geologically","structure":"geology + -ical + -ly","meaning":"in terms of rock structure and deep time","meaningCN":"从地质构造与深远年代的角度","example":"Geologically, the valley is very young.","exampleCN":"从地质上看，这条谷地非常年轻。"},{"word":"geometry","structure":"geo- + metron (measure) + -y","meaning":"measurement of the earth, now the study of shape","meaningCN":"原为土地测量，今指几何学","example":"The bridge design depends on plain geometry.","exampleCN":"这座桥的设计依赖基础几何。"},{"word":"graph","structure":"graph- (write, draw)","meaning":"a drawing that shows how values relate","meaningCN":"用图线表示数值关系的图表","example":"The graph shows rainfall against temperature.","exampleCN":"这张图显示降雨量与温度的关系。"},{"word":"geocentric","structure":"geo- + centron (centre) + -ic","meaning":"treating the earth as the centre","meaningCN":"以地球为中心的","example":"The geocentric model held sway for centuries.","exampleCN":"地心模型统治了数百年。"}],"latinEntries":[{"word":"geōgraphia","structure":"Greek gē (earth) + graphein (write) + -ia","meaning":"a description of the earth","meaningCN":"对大地的描述"},{"word":"geographia","structure":"Latin borrowing of Greek geōgraphia","meaning":"geography, a written account of lands","meaningCN":"地理；关于各地的书面记述"},{"word":"-icalis","structure":"Latin adjective suffix < Greek -ikos","meaning":"relating to, having the nature of","meaningCN":"与……有关的、具有……性质的"}]}},{"word":"geologist","ipa_uk":"/dʒiˈɒlədʒɪst/","ipa_us":"/dʒiˈɑːlədʒɪst/","definition_zh":"地质学家；地质工作者；研究岩层与地球历史的人","definition_en":"a scientist who studies rocks, layers, minerals and the long history of the earth, often by fieldwork as well as laboratory analysis","core_image":"一个人蹲在岩壁前，手举地质锤敲下一块带层理的岩石","scene":"The geologist read the cliff like a page, naming each layer in order.","sceneCN":"这里 geologist 是「地质学家」的本义（第 1 个义项：以岩层为研究对象的人）；句意：这位地质学家像读一页书那样读那道崖壁，依次说出每一层。图中可辨识物件：地质锤、放大镜、岩层剖面、记录本、安全帽。","pos":[{"tag":"n.","zh":"地质学家；地质工作者（可数名词，复数形式规则变化）"}],"collocations":[{"phrase":"field geologist","zh":"野外地质工作者"},{"phrase":"petroleum geologist","zh":"石油地质师"},{"phrase":"planetary geologist","zh":"行星地质学家"},{"phrase":"consultant geologist","zh":"顾问地质学家"},{"phrase":"a team of geologists","zh":"一支地质队"},{"phrase":"geologist's hammer","zh":"地质锤"}],"forms":[{"label":"复数","form":"geologists"},{"label":"学科名词","form":"geology（地质学）"},{"label":"形容词","form":"geological / geologic（地质的）"},{"label":"副词","form":"geologically（从地质上看）"}],"derivatives":[{"word":"geology","pos":"n.","zh":"地质学；地质构造"},{"word":"geological","pos":"adj.","zh":"地质的；地质学的"},{"word":"geologic","pos":"adj.","zh":"地质的（较短变体）"},{"word":"geochemistry","pos":"n.","zh":"地球化学"},{"word":"geophysics","pos":"n.","zh":"地球物理学"}],"senses":[{"no":"01","title":"A scientist of rocks and strata","titleCN":"岩石与地层的研究者：本义","definition":"a scientist whose subject is the solid earth, its rocks, minerals and layered history","definitionCN":"以固体地球、岩石、矿物与层状历史为研究对象的科学家","example":"A geologist can date the flow of lava from its mineral grains.","exampleCN":"地质学家能根据矿物颗粒测定熔岩流出的年代。","why":"geology joins Greek gē 'earth' and -logia 'study, account'; -ist marks the person, so a geologist is literally 'one who studies the earth'.","whyCN":"geology 由希腊 gē“大地”与 -logia“研究、论述”构成，-ist 标记从事者，因此 geologist 字面就是“研究大地的人”。"},{"no":"02","title":"The field worker","titleCN":"野外地质工作者：在山野里读岩的人","definition":"one who maps and samples rock exposures outdoors rather than only in a laboratory","definitionCN":"在野外测绘、采样岩石露头，而非只在实验室工作的人","example":"The geologist spent the summer mapping exposures along the fault.","exampleCN":"这位地质工作者整个夏天都在测绘断层沿线出露的岩体。","why":"Because strata are visible only where they break the surface, the profession's core skill has always been reading outcrops in the field.","whyCN":"由于地层只有在出露地表处才可见，这门职业的核心技能始终是在野外读露头。"},{"no":"03","title":"The exploration specialist","titleCN":"资源勘探地质师：找矿找油的人","definition":"an applied geologist who locates oil, gas, groundwater or ore for industry","definitionCN":"为工业寻找石油、天然气、地下水或矿石的应用型地质工作者","example":"The company hired a geologist to assess the shale under the plain.","exampleCN":"公司聘请了一位地质师评估平原下方的页岩。","why":"Industry needs predictions about what lies underground, and that is exactly the stratigraphic reading a geologist supplies.","whyCN":"工业需要关于地下埋藏什么的预测，而这正是地质学家所提供的层序判读。"},{"no":"04","title":"The planetary geologist","titleCN":"行星地质学家：读别的星球表面","definition":"a geologist who applies earthly rock science to the surfaces of the moon, Mars or other bodies","definitionCN":"把地球岩石科学用于月球、火星等天体表面的地质学家","example":"A planetary geologist compared the crater floors on Mars with basalt fields on earth.","exampleCN":"一位行星地质学家把火星的坑底与地球的玄武岩区作比较。","why":"The same processes of impact, flow and erosion leave records elsewhere, so the earth-trained eye transfers to other worlds.","whyCN":"撞击、流动与侵蚀等同一批过程在其他天体也留下记录，因此受训于地球的眼光可转移到别的世界。"},{"no":"05","title":"The engineering geologist","titleCN":"工程地质人员：为建筑判断地基","definition":"a geologist who judges ground conditions for tunnels, dams, foundations and slopes","definitionCN":"为隧道、水坝、地基与边坡判断地下条件的地质工作者","example":"An engineering geologist warned that the slope would fail after heavy rain.","exampleCN":"一位工程地质人员警告说，大雨之后该边坡会失稳。","why":"Buildings rest on materials a geologist can name and test, so the discipline becomes a safety service at construction sites.","whyCN":"建筑坐落在能由地质工作者命名并测试的材料上，于是这门学问在工地变成一项安全服务。"},{"no":"06","title":"The hazard assessor","titleCN":"灾害评估者：判读地震与滑坡风险","definition":"one who studies faults, volcanoes and unstable ground to estimate future risk","definitionCN":"研究断层、火山与不稳定地面以估计未来风险的人","example":"The geologist mapped old landslide scars before the town expanded.","exampleCN":"在小镇扩建之前，这位地质学家测绘了旧滑坡的痕迹。","why":"Past rock movement is written into the landscape; reading it forward into future risk is the hazard branch of the same skill.","whyCN":"过去的岩体运动被写入地貌；把这种记录向前读成未来风险，就是同一技能的风险分支。"},{"no":"07","title":"The map-maker of strata","titleCN":"地层编图者：把岩层画成图","definition":"one who compiles geological maps showing the age and arrangement of rock units","definitionCN":"编制显示岩层年代与分布关系的地质图的人","example":"The geologist finished a sheet covering four hundred square kilometres.","exampleCN":"这位地质学家完成了一幅覆盖四百平方公里的图幅。","why":"A geological map is the profession's written form: the geologist converts scattered outcrops into a continuous picture of what lies beneath.","whyCN":"地质图是这门职业的书面形态：地质学家把零散露头转成一幅连续的地下图景。"},{"no":"08","title":"The teacher and explainer","titleCN":"教学与科普者：把深时讲给人听","definition":"a geologist who teaches the subject or explains deep time to the public","definitionCN":"教授这门学科或向公众解释深远年代的地质工作者","example":"The geologist showed visitors how a river cuts through a million years in one bank.","exampleCN":"这位地质学家向参观者展示一条河如何在一道岸壁上切开百万年。","why":"Deep time is invisible without explanation, so part of the role is turning rock evidence into a story nonspecialists can follow.","whyCN":"深时若不经解释便不可见，因此这一角色的一部分工作就是把岩石证据转成非专业者能跟上的一段叙述。"}],"etymology":{"intro":{"en":"Geologist is geolog(y) plus -ist. The compound is Greek in its parts, Latin in its transmission, and modern in its meaning. Dates are approximate.","cn":"geologist 是 geolog(y) 加 -ist。其构件属希腊语，传承经拉丁语，词义则是近代形成的。年代为约数。"},"items":[{"era":"GREEK PARTS","en":"gē meant 'earth', and logos meant 'word, account, reason'. The compound geologia would have meant 'an account of the earth'; it is not common in surviving classical texts.","cn":"gē 意为“大地”，logos 意为“言说、记述、道理”。复合形式 geologia 本应意为“关于大地的论述”，在现存古典文本中并不常见。"},{"era":"EARLY MODERN COINAGE","en":"The Latinized form geologia appears in the 17th century for the study of the earth's materials. Several writers used it independently, so no single coiner can be named with certainty.","cn":"拉丁化形式 geologia 于 17 世纪出现，指对地球物质的研究。多位作者各自使用过它，因此无法确定唯一的创制者。"},{"era":"MODERN DISCIPLINE","en":"Only in the late 18th and early 19th centuries did geology settle on its modern meaning: the study of strata and earth history, with field mapping as its method.","cn":"直到 18 世纪末至 19 世纪初，geology 才固定为现代含义：研究地层与地球历史，以野外填图为方法。"},{"era":"PERSON SUFFIX","en":"-ist comes from Greek -istēs through Latin -ista and French -iste, and names a person engaged in something. Geologist is recorded from the late 18th century.","cn":"-ist 经拉丁 -ista、法语 -iste 来自希腊 -istēs，指从事某事的人。geologist 的记录可追溯到 18 世纪后期。"},{"era":"SPECIALIZED ROLES","en":"The 20th century split the role into branches such as petroleum geologist, engineering geologist and planetary geologist.","cn":"20 世纪把这个角色分化为石油地质师、工程地质人员、行星地质学家等分支。"},{"era":"UNCERTAIN DETAILS","en":"The first use of geologia and of geologist is uncertain, and the deeper sense of Greek logos ranges from 'word' to 'reason', so the original force of the compound is disputed.","cn":"geologia 与 geologist 的首见年代存疑；希腊 logos 的深层含义从“言词”到“道理”不等，因此该复合词最初的含义有争议。"}]},"similar":{"note":{"en":"The first group contains words built on the same stems; the second contains other earth-science specialists who study different materials.","cn":"第一组是同一词干构成的词；第二组是研究不同对象的其他地球科学专家。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"geology","ipa":"/dʒiˈɒlədʒi/","tag":"the field, not the person","definition":"The discipline itself, or the rock structure of a region. A geologist practises geology.","definitionCN":"指学科本身或某地的地质构造；地质学家从事的是这门学科。"},{"word":"geological","ipa":"/ˌdʒiːəˈlɒdʒɪkl/","tag":"adjective","definition":"Relating to geology, as in geological map or geological time. It cannot stand for a person.","definitionCN":"形容词，如地质图、地质年代；不能用来指人。"},{"word":"geologer","ipa":"/dʒiˈɒlədʒə/","tag":"rare older word","definition":"An obsolete variant for a geologist, formed with -er instead of -ist. It appears only in older texts.","definitionCN":"地质学家的废弃变体，以 -er 而非 -ist 构成，仅见于旧文本。"},{"word":"geographer","ipa":"/dʒiˈɒɡrəfə/","tag":"places, not rocks","definition":"A specialist in the description of places, climate and distribution, from -graphy 'write'; a geologist reads strata, a geographer maps surfaces and peoples.","definitionCN":"专长于描述地点、气候与分布，源自 -graphy“书写”；地质学家读地层，地理学家绘地表与人群。"}]},{"heading":"NEAR MEANING","entries":[{"word":"earth scientist","ipa":"/ɜːθ ˈsaɪəntɪst/","tag":"broad umbrella","definition":"Anyone studying the planet, including oceans, atmosphere and magnetism; a geologist is one member of this wider group.","definitionCN":"研究地球的任何人，包括海洋、大气与地磁；地质学家是这一更大群体中的一个分支。"},{"word":"mineralogist","ipa":"/ˌmɪnəˈrælədʒɪst/","tag":"minerals only","definition":"One who studies the chemistry and structure of minerals rather than whole rock sequences.","definitionCN":"研究矿物的化学成分与结构，而非整套岩层序列的人。"},{"word":"seismologist","ipa":"/saɪzˈmɒlədʒɪst/","tag":"earthquakes","definition":"One who records and interprets seismic waves; a geologist may study faults, but a seismologist measures the shaking itself.","definitionCN":"记录并解释地震波的人；地质学家可以研究断层，但地震学家测量的是震动本身。"},{"word":"volcanologist","ipa":"/ˌvɒlkəˈnɒlədʒɪst/","tag":"volcanoes","definition":"One who specializes in volcanic systems and eruptions, a narrower branch of geology.","definitionCN":"专攻火山系统与喷发的人，是地质学中更窄的分支。"},{"word":"prospector","ipa":"/prəˈspektə/","tag":"finder, often untrained","definition":"A person who searches for ore or gold, often by practical experience rather than formal geological training.","definitionCN":"寻找矿石或黄金的人，常凭实践经验而非正规地质训练。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词。"},"normal":[{"en":"geo- 'earth' + -logy 'study' + -ist 'person': the person who studies the earth.","cn":"geo-“大地”+ -logy“研究”+ -ist“人”：研究大地的人。"},{"en":"geology is the field, geologist is the person, geological is the adjective; keep the trio straight.","cn":"geology 是学科，geologist 是人，geological 是形容词；三者要分清。"},{"en":"Fixed phrases mark the branches: field geologist, petroleum geologist, planetary geologist, engineering geologist.","cn":"固定搭配标出各分支：野外地质工作者、石油地质师、行星地质学家、工程地质人员。"},{"en":"A geologist's basic tools are the hammer, the hand lens and the notebook.","cn":"地质工作者的基本工具是地质锤、放大镜和记录本。"},{"en":"Do not confuse geologist with geographer: rocks versus places.","cn":"别把 geologist 与 geographer 混淆：一个是岩石，一个是地点。"}],"abstract":[{"en":"Picture a cliff face as a stack of pages, each layer a sentence written in sand and shell.","cn":"想象崖壁是一叠书页，每一层都是用沙与贝壳写下的句子。"},{"en":"Picture a hammer tapping a stone and a clock hand jumping back a million years with each blow.","cn":"想象锤子敲一下石头，时钟的指针就回跳一百万年。"},{"en":"Picture scattered outcrops joined by faint lines into one continuous underground sheet.","cn":"想象零散露头被细线连成一整幅连续的地下图纸。"}]},"examples":[{"en":"The geologist sampled the ash layer on both sides of the valley to compare the two sections.","cn":"这位地质学家在谷地两侧都采了火山灰层样品，以对比两个剖面。"},{"en":"After the earthquake, a geologist measured how far the fence had been offset.","cn":"地震之后，一位地质学家测量了栅栏被错开的距离。"},{"en":"The museum's geologist explains to school groups why the fossils are older than the lava above them.","cn":"博物馆的地质学家向学生团体解释，为什么化石比覆盖其上的熔岩更古老。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“地（geo）质学家爱敲石头（logist 像‘逻辑师’）”——读岩层如读书 → geologist 地质学家","word":"geologist"},"root":"希腊 gē“大地”+ logos“言说、道理”→ geologia“关于大地的论述”；拉丁 geologia + -ist（从事者后缀）。","sensesIntro":{"en":"Eight senses belong to one figure: a person who reads stone. The same reader moves from outcrop to industry, to other planets, to risk, to maps and to the classroom.","cn":"八个义项都属于同一个人物：读石头的人。这同一个读石者从露头走向工业、走向别的星球、走向风险、走向地图，最后走向课堂。"},"semanticMap":{"core":{"en":"CORE IMAGE: a kneeling figure tapping a layered cliff with a hammer.","cn":"核心意象：一个蹲在层状崖壁前、用锤子敲击的人。"},"chain":["STUDY THE EARTH","READ THE OUTCROP","FIND RESOURCES","JUDGE THE GROUND","ASSESS THE HAZARD","EXPLAIN DEEP TIME"],"branches":[{"senses":"01 · 02","en":"THE READER: the scientist and the field worker are the same core role seen in the library and on the cliff.","cn":"读石者：学科专家与野外工作者是同一核心角色在书房与崖壁上的两种样子。"},{"senses":"03","en":"RESOURCES: reading strata becomes a service to mining, oil and water supply.","cn":"资源：读地层变成对采矿、石油与供水的服务。"},{"senses":"04 · 05","en":"OTHER GROUND: the same eye is turned to other planets and to the ground under a dam.","cn":"别处的地面：同一双眼睛转向别的行星，也转向水坝之下的土地。"},{"senses":"06 · 07","en":"RISK AND RECORD: old movement becomes future hazard, and scattered evidence becomes a published map.","cn":"风险与记录：过去的运动变成未来的风险，零散证据变成公开发表的地图。"},{"senses":"08","en":"THE EXPLAINER: the geologist also converts deep time into words the public can hold.","cn":"解释者：地质学家还负责把深时转换成公众能把握的语言。"}]},"affixes":{"intro":{"en":"Geologist is a clean three-part word: geo- 'earth', -log- 'study or account', -ist 'person'. The middle element is the same one that gives logic and dialogue.","cn":"geologist 是清晰的三段式词：geo-“大地”、-log-“研究或论述”、-ist“人”。中间这一段也构成 logic 与 dialogue。"},"latinIntro":{"en":"Greek logos supplied a whole family through Latin and French: logic, dialogue, biology, geology, theology, psychology and technology all carry -logy or -logue.","cn":"希腊 logos 经拉丁与法语衍生出整族词：logic、dialogue、biology、geology、theology、psychology、technology 都带 -logy 或 -logue。"},"items":[{"word":"geologist","structure":"geo- (earth) + -log- (study) + -ist (person)","meaning":"a person who studies the earth's rocks","meaningCN":"研究地球岩石的人","example":"The geologist logged the section in a waterproof notebook.","exampleCN":"这位地质学家在防水本上记录了该剖面。"},{"word":"geology","structure":"geo- + -logy (study, account)","meaning":"the science of the earth's solid materials","meaningCN":"研究地球固体物质的科学","example":"The geology of the basin is dominated by sandstone.","exampleCN":"该盆地的地质以砂岩为主。"},{"word":"geological","structure":"geology + -ical (relating to)","meaning":"relating to rock structure and earth history","meaningCN":"与岩层构造和地球历史有关的","example":"The survey produced a new geological map.","exampleCN":"这次调查绘制了新的地质图。"},{"word":"geologic","structure":"geo- + -logic (shorter form)","meaning":"the shorter adjective of geology","meaningCN":"地质的（较短形式）","example":"Geologic time is measured in millions of years.","exampleCN":"地质年代以百万年计。"},{"word":"geochemistry","structure":"geo- + chemistry (chemical study)","meaning":"the chemistry of rocks and fluids","meaningCN":"岩石与流体的化学研究","example":"Geochemistry can reveal where the granite came from.","exampleCN":"地球化学能揭示花岗岩的来源。"},{"word":"geophysics","structure":"geo- + physics (natural science)","meaning":"the physics of the earth's interior and fields","meaningCN":"研究地球内部与场的物理学","example":"Geophysics locates the ore body without digging.","exampleCN":"地球物理学不必开挖就能定位矿体。"},{"word":"biology","structure":"bio- (life) + -logy (study)","meaning":"the study of living things; shows -logy at work","meaningCN":"研究生物的科学；展示 -logy 的构词方式","example":"Biology and geology meet in the study of fossils.","exampleCN":"生物学与地质学在化石研究中相遇。"},{"word":"logic","structure":"log- (word, reason) + -ic","meaning":"the study of valid reasoning, from the same logos","meaningCN":"研究有效推理的学问，同出 logos","example":"The argument's logic is sound even if its data are thin.","exampleCN":"即便数据单薄，这个论证的逻辑仍然成立。"}],"latinEntries":[{"word":"logos","structure":"Greek logos (word, account, reason)","meaning":"a word, an account, or reasoned explanation","meaningCN":"言词；记述；理性解释"},{"word":"geologia","structure":"Latinized Greek gē + logos","meaning":"an account of the earth (early modern Latin)","meaningCN":"关于大地的论述（早期近代拉丁）"},{"word":"-ista","structure":"Latin -ista < Greek -istēs","meaning":"person who practises something","meaningCN":"从事某事的人"}]}},{"word":"geological","ipa_uk":"/ˌdʒiːəˈlɒdʒɪkl/","ipa_us":"/ˌdʒiːəˈlɑːdʒɪkl/","definition_zh":"地质的；地质学的；岩层构造的；地质年代的","definition_en":"relating to the structure, materials and long history of the earth's rocks, or to the timescales over which they formed","core_image":"一堵被错断的岩墙，两边的层理错开了半米","scene":"The fault is a geological boundary that no road builder can ignore.","sceneCN":"这里 geological 是「岩层构造的」（第 4 个义项：断层等岩体结构）；句意：这条断层是一条任何筑路者都无法忽视的地质界线。图中可辨识物件：错断的岩层、断层线、公路、罗盘、剖面标尺。","pos":[{"tag":"adj.","zh":"地质的；地质学的；岩层构造的；地质年代的（多作定语）"}],"collocations":[{"phrase":"geological survey","zh":"地质调查；地质调查所"},{"phrase":"geological time","zh":"地质年代；地质时间"},{"phrase":"geological formation","zh":"地质建造；岩层组成"},{"phrase":"geological fault","zh":"地质断层"},{"phrase":"geological storage","zh":"地质封存（如二氧化碳封存）"},{"phrase":"geological heritage","zh":"地质遗产"}],"forms":[{"label":"比较级（更地质的）","form":"more geological"},{"label":"最高级（最地质的）","form":"most geological"},{"label":"副词形式","form":"geologically（从地质上看）"},{"label":"较短变体","form":"geologic（多见于北美用法）"}],"derivatives":[{"word":"geology","pos":"n.","zh":"地质学；地质构造"},{"word":"geologist","pos":"n.","zh":"地质学家；地质工作者"},{"word":"geologically","pos":"adv.","zh":"从地质角度；在地质上"},{"word":"geologic","pos":"adj.","zh":"地质的（较短变体）"},{"word":"geochronology","pos":"n.","zh":"地质年代学（测定岩层年龄的分支）"}],"senses":[{"no":"01","title":"Belonging to the science of geology","titleCN":"地质学的：作为学科的一部分","definition":"belonging to or produced by the scientific study of the earth's solid materials","definitionCN":"属于研究地球固体物质的科学，或由其产生的","example":"The paper appears in a geological journal, not a biological one.","exampleCN":"这篇论文发表在地质学期刊上，而非生物学刊物。","why":"geology names the discipline, and -ical makes the relational adjective: anything marked geological belongs to that field's work.","whyCN":"geology 是学科名，-ical 构成关系形容词：凡被标记为 geological 的，都属于该领域的工作。"},{"no":"02","title":"Of strata and their order","titleCN":"岩层的：层理与叠压次序","definition":"relating to the layering of rock and the order in which one bed lies on another","definitionCN":"关于岩石的层状构造以及一层压在另一层之上的次序","example":"A geological section shows the sandstone below the shale.","exampleCN":"一幅地质剖面显示砂岩位于页岩之下。","why":"The first task of geology was to put rock beds in order, so the adjective points at stacked layers before anything else.","whyCN":"地质学最早的任务就是给岩层排序，因此这个形容词首先指向叠压的层。"},{"no":"03","title":"Of deep time","titleCN":"地质年代的：以百万年计的尺度","definition":"relating to the very long timescales over which rocks form and continents move","definitionCN":"关于岩石形成、大陆漂移所经历的极长时间尺度","example":"Geological time makes a thousand years look like a single breath.","exampleCN":"在地质年代尺度上，一千年短得像一次呼吸。","why":"Rock processes run far slower than human history, so geology needed a separate clock, and the adjective names that clock's units.","whyCN":"岩石过程远比人类历史缓慢，因此地质学需要另一套时钟，而这个形容词指的就是那套时钟的单位。"},{"no":"04","title":"Of rock structure","titleCN":"地质构造的：断层、褶皱与节理","definition":"relating to the deformation of rock, such as faults, folds and joints","definitionCN":"关于岩石变形，如断层、褶皱与节理的","example":"The tunnel had to be rerouted around a geological fault.","exampleCN":"隧道不得不改线以避开一条地质断层。","why":"Beds that were once flat are now broken and bent; the adjective covers the structures produced by that deformation.","whyCN":"曾经平躺的岩层如今破裂弯折；这个形容词覆盖的正是这种变形所产生的构造。"},{"no":"05","title":"Of survey and exploration","titleCN":"地质调查的：测绘与勘探工作","definition":"relating to systematic mapping, sampling and testing of the ground","definitionCN":"关于对地下进行系统测绘、采样与测试的","example":"A geological survey of the region began before the dam was designed.","exampleCN":"在设计水坝之前，该地区的地质调查就已开始。","why":"Before anyone builds or drills, the ground must be described; the adjective marks that descriptive and testing phase.","whyCN":"在建造或钻探之前，必须先描述地下情况；这个形容词标记的正是那一描述与测试阶段。"},{"no":"06","title":"Of active earth processes","titleCN":"地质活动的：地震、火山与侵蚀","definition":"relating to processes that move or melt rock, such as earthquakes, eruptions and erosion","definitionCN":"关于使岩石移动或熔融的过程，如地震、喷发与侵蚀","example":"The coast is shaped by geological processes that operate over millennia.","exampleCN":"这条海岸由持续数千年的地质过程塑造。","why":"Structure is not static: the same forces that made the layers keep breaking them, and the adjective extends to those forces.","whyCN":"构造并非静止：造出层理的力量仍在破坏层理，这个形容词便延伸到这些力量上。"},{"no":"07","title":"Of underground storage","titleCN":"地质封存的：把物质存入岩层","definition":"relating to long-term storage of substances such as carbon dioxide in deep rock formations","definitionCN":"关于把二氧化碳等物质长期存入深部岩层的","example":"The project injects carbon dioxide into a geological storage site under the sea.","exampleCN":"该项目把二氧化碳注入海底的一处地质封存场地。","why":"Deep porous rock can hold fluids for geological timescales, so engineers borrowed the adjective for that kind of vault.","whyCN":"深部多孔岩石能在地质时间尺度上容纳流体，于是工程人员借这个形容词来指称这类“地下库房”。"},{"no":"08","title":"Of protected earth heritage","titleCN":"地质遗产的：值得保护的岩景","definition":"relating to landforms or rock exposures preserved for their scientific or educational value","definitionCN":"关于因科学或教育价值而被保护的地貌或岩石露头的","example":"The gorge became a geological heritage site in 1998.","exampleCN":"这条峡谷于 1998 年成为地质遗产地。","why":"When a rock exposure is treated as a document to keep rather than a resource to use, the adjective shifts from study to conservation.","whyCN":"当某处岩石露头被视为需要保存的文献、而不是可利用的资源时，这个形容词就从研究转向保护。"}],"etymology":{"intro":{"en":"Geological is geology plus -ical, built on Greek gē 'earth' and -logia 'account, study'. The word is modern; the parts are ancient. Dates are approximate.","cn":"geological 是 geology 加 -ical，词基为希腊 gē“大地”与 -logia“论述、研究”。词是近代的，构件则古老。年代为约数。"},"items":[{"era":"GREEK ELEMENTS","en":"gē 'earth' and logos 'word, account, reason' combine in geologia, an account of the earth. Classical use of the compound is thin, so its early meaning is inferred rather than documented.","cn":"gē“大地”与 logos“言词、记述、道理”合成 geologia，即关于大地的论述。该复合词在古典时期用例稀少，其早期含义属推断而非有据可查。"},{"era":"LATIN AND EARLY MODERN USE","en":"The Latinized geologia appears in the 17th century for descriptions of earthly materials. Different writers coined it independently, so no single originator is certain.","cn":"拉丁化形式 geologia 于 17 世纪出现，用于描述地球物质。不同作者各自创用，因此没有确定的唯一首创者。"},{"era":"THE MODERN SCIENCE","en":"In the late 18th century geology narrowed to the study of strata and earth history, and the adjective geological followed the new discipline.","cn":"18 世纪后期，geology 收窄为研究地层与地球历史的学科，形容词 geological 也随之指向这门新学科。"},{"era":"ADJECTIVE ENDING","en":"-ical comes from Latin -icalis, from Greek -ikos, the suffix of relation. Latin had geologicus, and English formed geological on the same pattern as logical and physical.","cn":"-ical 来自拉丁 -icalis，后者出自希腊 -ikos，即关系形容词后缀。拉丁已有 geologicus，英语按 logical、physical 的同一模式造出 geological。"},{"era":"TECHNICAL EXTENSIONS","en":"The 20th century added geological storage in climate engineering and geological heritage in conservation, both using 'deep rock and deep time' as their base.","cn":"20 世纪新增气候工程中的地质封存与保护领域的地质遗产，两者都以“深部岩层与深远年代”为基底。"},{"era":"UNCERTAIN DETAILS","en":"Exact first dates for geology and geological in their modern senses are uncertain, and the range of meanings carried by Greek logos is still debated.","cn":"geology 与 geological 在现代义上的确切首见年代存疑；希腊 logos 所承载的意义范围至今仍有争论。"}]},"similar":{"note":{"en":"The first group contains forms of the same word family; the second contains adjectives for neighbouring branches of earth science.","cn":"第一组是同一词族的不同形式；第二组是相邻地球科学分支的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"geologic","ipa":"/ˌdʒiːəˈlɒdʒɪk/","tag":"same meaning, shorter","definition":"The clipped adjective of geology, frequent in North American technical writing. The difference from geological is stylistic.","definitionCN":"geology 的截短形容词，北美技术写作中常见；与 geological 的差别在风格。"},{"word":"geology","ipa":"/dʒiˈɒlədʒi/","tag":"noun, not adjective","definition":"The discipline or a region's rock structure. It cannot modify another noun the way geological does.","definitionCN":"指学科或某地的岩石构造；不能像 geological 那样修饰其他名词。"},{"word":"geologically","ipa":"/ˌdʒiːəˈlɒdʒɪkli/","tag":"adverb","definition":"The adverb meaning 'in geological terms'. It modifies verbs and whole clauses, not nouns.","definitionCN":"副词，意为“从地质上看”，修饰动词或整句，而非名词。"},{"word":"geologist","ipa":"/dʒiˈɒlədʒɪst/","tag":"the person","definition":"The specialist who practises geology. It is a countable person noun, not a description of rock.","definitionCN":"从事地质学的专家；是可数的人物名词，不描述岩石。"}]},{"heading":"NEAR MEANING","entries":[{"word":"tectonic","ipa":"/tekˈtɒnɪk/","tag":"plate-scale structure","definition":"Relating to the deformation of the earth's crust at plate scale; narrower than geological, which covers materials, time and process alike.","definitionCN":"关于板块尺度上地壳的变形；比 geological 窄，后者同时覆盖物质、时间与过程。"},{"word":"stratigraphic","ipa":"/ˌstrætɪˈɡræfɪk/","tag":"layer order only","definition":"Relating specifically to the order and correlation of strata; one branch of what geological covers.","definitionCN":"专指地层的层序与对比，只是 geological 所覆盖内容中的一个分支。"},{"word":"mineralogical","ipa":"/ˌmɪnərəˈlɒdʒɪkl/","tag":"minerals, not strata","definition":"Relating to the composition and crystallography of minerals rather than to whole rock bodies.","definitionCN":"关于矿物的成分与结晶学，而非整个岩体。"},{"word":"geomorphic","ipa":"/ˌdʒiːəˈmɔːfɪk/","tag":"landforms","definition":"Relating to the shape of landforms and the processes that carve them; it studies surfaces, while geological also studies what lies beneath.","definitionCN":"关于地貌形态及其塑造过程；它研究地表，而 geological 也研究地下。"},{"word":"seismic","ipa":"/ˈsaɪzmɪk/","tag":"waves and shaking","definition":"Relating to earthquake waves and vibration; used in geological work but limited to the shaking itself.","definitionCN":"关于地震波与震动；虽用于地质工作，但只限于震动本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词。"},"normal":[{"en":"geo- 'earth' + -logical 'relating to study': belonging to the study of the earth.","cn":"geo-“大地”+ -logical“与研究有关”：属于研究大地的学问。"},{"en":"geology is the field, geologist the person, geological the adjective, geologically the adverb.","cn":"geology 是学科，geologist 是人，geological 是形容词，geologically 是副词。"},{"en":"geological time is the phrase that carries sense 3; geological survey carries senses 1, 2 and 5.","cn":"geological time 承载第 3 个义项；geological survey 承载第 1、2、5 个义项。"},{"en":"The family includes geology, geologist, geologically, geochronology and geochemistry.","cn":"同族词包括 geology、geologist、geologically、geochronology、geochemistry。"},{"en":"geological describes rock; geographic describes place. The second element decides the meaning.","cn":"geological 描述岩石，geographic 描述地点；第二个构件决定词义。"}],"abstract":[{"en":"Picture a ruler laid on a cliff, each tick worth a million years.","cn":"想象一把尺子贴在崖壁上，每一格代表一百万年。"},{"en":"Picture a flat cake of rock cut and pushed sideways, its layers offset like a broken comb.","cn":"想象一块平整的岩层被切开并横向错动，层理像断了的梳齿。"},{"en":"Picture carbon dioxide sealed in stone pores under the sea, held for longer than humans have existed.","cn":"想象二氧化碳被封在海底岩石的孔隙里，封存时间比人类存在的历史还长。"}]},"examples":[{"en":"The geological record shows that the lake dried out at least three times.","cn":"地质记录显示，这个湖至少干涸过三次。"},{"en":"Engineers stopped drilling when they hit a geological formation too hard to bore through.","cn":"工程师遇到一层硬得无法钻透的地质建造，于是停止钻进。"},{"en":"The park was listed as a geological heritage site because of its folded limestone.","cn":"这座公园因褶皱石灰岩而被列为地质遗产地。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“地（geo）层有逻辑（logical）地叠着”——一层压一层 → geological 地质的、岩层的","word":"geological"},"root":"希腊 gē“大地”+ logos“论述、道理”→ geologia；拉丁 geologicus + 英语 -ical（关系形容词后缀）。","sensesIntro":{"en":"Eight senses run from the science itself to the layers it reads, the clock it uses, the structures it maps, the work it does and the ground it protects.","cn":"八个义项从这门学科本身，延伸到它阅读的岩层、它使用的时钟、它测绘的构造、它开展的工作，以及它保护的地面。"},"semanticMap":{"core":{"en":"CORE IMAGE: a rock wall whose bands are broken and offset along a fault.","cn":"核心意象：一堵层带被断层错开的岩壁。"},"chain":["STUDY OF ROCK","LAYER ORDER","DEEP TIME","DEFORMED STRUCTURE","SURVEY THE GROUND","ACTIVE PROCESS"],"branches":[{"senses":"01 · 04","en":"SCIENCE AND STRUCTURE: the discipline and the broken beds it describes belong to one frame.","cn":"学科与构造：这门学科与它所描述的破裂岩层属于同一个框架。"},{"senses":"02 · 03","en":"ORDER AND TIME: stacked beds are a clock, and reading their order is reading elapsed time.","cn":"层序与时间：叠压的岩层就是一座钟，读层序就是读流逝的时间。"},{"senses":"05","en":"FIELDWORK: before use comes description, so survey is the practical face of the adjective.","cn":"野外工作：在使用之前先有描述，因此调查是这个形容词的实践面。"},{"senses":"06","en":"LIVING EARTH: the same forces still break, melt and carry rock away.","cn":"活动的地球：同一批力量仍在破坏、熔融并搬走岩石。"},{"senses":"07 · 08","en":"TWO USES OF DEEP ROCK: one stores what industry must bury, the other preserves what science must keep.","cn":"深部岩层的两种用途：一个封存工业必须埋掉的东西，一个保存科学必须留住的东西。"}]},"affixes":{"intro":{"en":"Geological is geology plus -ical. The prefix geo- and the combining form -log- both come from Greek and remain productive.","cn":"geological 是 geology 加 -ical。前缀 geo- 与组合成分 -log- 都来自希腊语，至今仍有构词能力。"},"latinIntro":{"en":"Through Latin, Greek geo- and -logia produced a dense family: geology, geologist, geophysics, geochemistry, biology, theology and ecology all share the pattern.","cn":"经拉丁语传承，希腊 geo- 与 -logia 造出密集词族：geology、geologist、geophysics、geochemistry、biology、theology、ecology 都共享这一模式。"},"items":[{"word":"geological","structure":"geo- + -log- + -ical","meaning":"relating to the study of the earth's rocks","meaningCN":"与地球岩石研究有关的","example":"The map's legend explains each geological unit.","exampleCN":"该图图例解释了每一个地质单元。"},{"word":"geology","structure":"geo- + -logy (study, account)","meaning":"the science of the earth's solid matter","meaningCN":"研究地球固体物质的科学","example":"Geology explains why the two hills differ in age.","exampleCN":"地质学解释了这两座山丘年龄不同的原因。"},{"word":"geologist","structure":"geo- + -log- + -ist (person)","meaning":"a person who studies rocks","meaningCN":"研究岩石的人","example":"The geologist dated the ash by its crystals.","exampleCN":"地质学家通过晶体测定了火山灰的年代。"},{"word":"geologically","structure":"geological + -ly (adverb)","meaning":"in terms of rock structure or deep time","meaningCN":"从岩石构造或深远年代的角度","example":"Geologically, the two banks are quite different.","exampleCN":"从地质上看，两岸差别很大。"},{"word":"geochronology","structure":"geo- + chrono- (time) + -logy","meaning":"the dating of rocks and events","meaningCN":"测定岩石与事件年代的分支","example":"Geochronology fixed the eruption at about 74,000 years ago.","exampleCN":"地质年代学把这次喷发定在约七万四千年前。"},{"word":"geochemistry","structure":"geo- + chemistry","meaning":"the chemistry of earth materials","meaningCN":"地球物质的化学","example":"Geochemistry traces the metal to a deep source.","exampleCN":"地球化学把这批金属追溯到深部来源。"},{"word":"geophysics","structure":"geo- + physics","meaning":"the physics of the earth and its fields","meaningCN":"地球及其各种场的物理学","example":"Geophysics revealed a dense body under the plain.","exampleCN":"地球物理探测揭示了平原下方的高密度体。"},{"word":"tectonic","structure":"Greek tekton (builder) + -ic","meaning":"relating to crustal building and deformation","meaningCN":"与地壳建造和变形有关的","example":"Tectonic uplift raised the plateau by two kilometres.","exampleCN":"构造抬升把高原升高了两千米。"}],"latinEntries":[{"word":"geologia","structure":"gē (earth) + logos (account)","meaning":"an account of the earth (Latinized Greek)","meaningCN":"关于大地的论述（拉丁化的希腊词）"},{"word":"geologicus","structure":"geologia + -icus (relating to)","meaning":"relating to the study of the earth","meaningCN":"与大地研究有关的"},{"word":"-icalis","structure":"Latin -icalis < -icus + -alis","meaning":"adjective ending meaning 'relating to'","meaningCN":"关系形容词词尾，意为“与……有关的”"}]}},{"word":"geology","ipa_uk":"/dʒiˈɒlədʒi/","ipa_us":"/dʒiˈɑːlədʒi/","definition_zh":"地质学；地质构造；地质条件","definition_en":"the science that studies the earth's rocks, layers and history, or the actual rock structure of a particular region","core_image":"一本摊开的图册，左页画着地层剖面，右页写着年代","scene":"The geology of the basin is dominated by thick sandstone laid down in a shallow sea.","sceneCN":"这里 geology 是「地质构造」（第 2 个义项：某地区的岩层组成与层序）；句意：这个盆地的地质以浅海中沉积的厚层砂岩为主。图中可辨识物件：盆地剖面、砂岩层、化石、年代柱、野外记录本。","pos":[{"tag":"n.","zh":"地质学；地质构造；地质条件（作学科名时不可数，指某地构造时可加不定冠词）"}],"collocations":[{"phrase":"the geology of an area","zh":"某地区的地质构造"},{"phrase":"study geology","zh":"学习地质学；攻读地质"},{"phrase":"petroleum geology","zh":"石油地质学"},{"phrase":"engineering geology","zh":"工程地质学"},{"phrase":"glacial geology","zh":"冰川地质学"},{"phrase":"the geology department","zh":"地质系"}],"forms":[{"label":"复数（指多地区的地质构造）","form":"geologies（少见，多用于对比不同地区时）"},{"label":"人物名词","form":"geologist（地质学家）"},{"label":"形容词","form":"geological / geologic（地质的）"},{"label":"副词","form":"geologically（从地质上看）"}],"derivatives":[{"word":"geologist","pos":"n.","zh":"地质学家"},{"word":"geological","pos":"adj.","zh":"地质的；地质学的"},{"word":"geologically","pos":"adv.","zh":"从地质角度"},{"word":"geologic","pos":"adj.","zh":"地质的（较短变体）"},{"word":"geophysics","pos":"n.","zh":"地球物理学"}],"senses":[{"no":"01","title":"The science of the solid earth","titleCN":"地质学：研究固体地球的学科","definition":"the branch of science that studies rocks, minerals, strata and the history of the earth","definitionCN":"研究岩石、矿物、地层与地球历史的科学分支","example":"Geology explains both the mountain and the sea floor beside it.","exampleCN":"地质学既能解释这座山，也能解释它旁边的海底。","why":"geology joins Greek gē 'earth' with -logia 'account, study', so the word's first sense is simply 'the account of the earth'.","whyCN":"geology 由希腊 gē“大地”与 -logia“论述、研究”构成，因此其第一义项就是“关于大地的论述”。"},{"no":"02","title":"A region's rock structure","titleCN":"某地区的地质构造：那里的岩层组成","definition":"the actual arrangement of rocks and strata in a particular place","definitionCN":"某地岩石与地层的实际排列方式","example":"The geology here is simple: flat limestone over granite.","exampleCN":"这里的地质很简单：平坦的石灰岩覆盖在花岗岩上。","why":"The same noun shifts from the subject to its object, as 'biology' can mean the living world of a region; here it names what the ground is made of.","whyCN":"同一个名词从学科转向其对象，正如 biology 也可指某地的生物界；这里它指地下由什么构成。"},{"no":"03","title":"Ground conditions for building","titleCN":"地质条件：工程眼中的地下状况","definition":"the underground conditions that affect construction, drilling or tunnelling","definitionCN":"影响施工、钻探或掘进的地下条件","example":"The engineers ordered a report on the site's geology before bidding.","exampleCN":"工程师在投标前要求提交该场地的地质条件报告。","why":"Practical builders need to know what will resist or collapse; the abstract science becomes a site-specific condition.","whyCN":"实际施工者需要知道什么会承重、什么会坍塌；抽象学问于是变成具体场地的条件。"},{"no":"04","title":"The subject as taught","titleCN":"作为课程的地质学：大学里的一门学科","definition":"the school or university subject and its departments and degrees","definitionCN":"中小学或大学里的课程，及其院系与学位","example":"She took geology as her major and never left the field.","exampleCN":"她主修地质学，此后从未离开这个领域。","why":"Any science also exists as a curriculum; the noun covers lecture halls and degrees, not only research.","whyCN":"任何科学也以课程形式存在；这个名词覆盖讲堂与学位，而不只是研究。"},{"no":"05","title":"Geology of other worlds","titleCN":"行星地质：别的天体的岩层研究","definition":"the study of the solid surface and interior of moons, planets and asteroids","definitionCN":"对卫星、行星与小行星固体表面与内部的研究","example":"Planetary geology compares Martian dunes with desert sand on earth.","exampleCN":"行星地质学把火星沙丘与地球沙漠的沙作比较。","why":"Rock physics is not earth-bound, so the discipline's name travels to any solid body with a surface to read.","whyCN":"岩石物理并不限于地球，因此这门学科的名字可以迁移到任何有表面可读的固体天体。"},{"no":"06","title":"Economic geology","titleCN":"经济地质：矿产与能源的成因研究","definition":"the branch concerned with the origin and location of ore, oil, gas and coal","definitionCN":"研究矿石、石油、天然气与煤的成因与分布的分支","example":"Economic geology pointed the company to a copper belt nobody had mapped.","exampleCN":"经济地质把这家公司引向一条此前无人测绘的铜矿带。","why":"If rocks concentrate metals and fuels, then understanding rock history is directly profitable, and the branch is named for that use.","whyCN":"既然岩石会富集金属与燃料，理解岩石历史便直接有利可图，这一分支正因这种用途而得名。"},{"no":"07","title":"Environmental and water geology","titleCN":"环境与水文地质：地下水与污染的研究","definition":"the branch dealing with groundwater, soil contamination and land stability","definitionCN":"研究地下水、土壤污染与土地稳定性的分支","example":"Environmental geology traced the solvent plume to a leaking tank.","exampleCN":"环境地质把这片溶剂羽流追溯到一只渗漏的储罐。","why":"Once pollution travels through pores and fractures, rock structure decides where it goes, so geology becomes an environmental tool.","whyCN":"一旦污染物沿孔隙与裂隙运移，岩石结构就决定它的去向，地质学于是成为环境工具。"},{"no":"08","title":"The knowledge of a planet's structure","titleCN":"地质知识体系：关于某天体构造的总认识","definition":"the accumulated body of knowledge about how a planet or moon is built","definitionCN":"关于某行星或卫星如何构成的知识总汇","example":"What we call the geology of Mars rests on a few landers and many orbits.","exampleCN":"我们所说的火星地质，只建立在少数着陆器与大量轨道观测之上。","why":"Beyond any single region or course, the noun can name everything known about one body's solid structure.","whyCN":"超出单一地区或课程之外，这个名词还可指关于某一固体天体构造的全部已知。"}],"etymology":{"intro":{"en":"Geology is Greek in its parts (gē 'earth', -logia 'account') and modern in its meaning. Its Latinized form geologia appears in the 17th century. Dates are approximate.","cn":"geology 的构件属希腊语（gē“大地”、-logia“论述”），词义则是近代形成的。其拉丁化形式 geologia 于 17 世纪出现。年代为约数。"},"items":[{"era":"GREEK ELEMENTS","en":"gē 'earth' plus logos 'word, account, reason' gives the combining form -logia, 'a speaking or writing about'. The classical compound geologia is rarely attested.","cn":"gē“大地”加 logos“言词、记述、道理”构成组合成分 -logia，意为“关于……的言说或书写”。古典时期 geologia 这一复合词极少见。"},{"era":"SEVENTEENTH-CENTURY LATIN","en":"geologia is used in 17th-century Latin for descriptions of the earth's materials, often in contrast with theology. Several writers used it separately.","cn":"17 世纪拉丁语用 geologia 指对地球物质的描述，常与神学相对。多位作者各自使用过该词。"},{"era":"EIGHTEENTH-CENTURY NARROWING","en":"In the late 18th century the word settled on strata and earth history, as field mapping and fossil correlation became standard methods.","cn":"18 世纪后期，随着野外填图与化石对比成为标准方法，该词固定为研究地层与地球历史的含义。"},{"era":"NINETEENTH-CENTURY EXPANSION","en":"The 19th century multiplied its branches: stratigraphy, palaeontology, mineralogy and later geophysics, each keeping geology as the umbrella name.","cn":"19 世纪其分支大量增生：地层学、古生物学、矿物学，以及后来的地球物理学，都以 geology 作为统称。"},{"era":"TWENTIETH-CENTURY USES","en":"Plate tectonics unified the science in the 1960s, and planetary geology extended the name to other bodies after the first lunar samples.","cn":"板块构造学说在 20 世纪 60 年代统一了这门科学；首批月球样品之后，行星地质又把这一名称扩展到其他天体。"},{"era":"UNCERTAIN DETAILS","en":"The first appearance of geologia and the exact moment when it lost its broader 'natural philosophy of the earth' sense are both uncertain.","cn":"geologia 的首见时间，以及它何时失去更宽泛的“地球自然哲学”含义，都存疑。"}]},"similar":{"note":{"en":"The first group holds forms and neighbours from the same stems; the second holds other earth-science disciplines that are often confused with it.","cn":"第一组是同词干的形式与邻词；第二组是常与之混淆的其他地球科学学科。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"geologist","ipa":"/dʒiˈɒlədʒɪst/","tag":"the person","definition":"The specialist who practises geology. Use the -ist form for people and the bare noun for the field.","definitionCN":"从事地质学的专家；指人用 -ist 形式，指学科用本词。"},{"word":"geological","ipa":"/ˌdʒiːəˈlɒdʒɪkl/","tag":"adjective","definition":"Relating to geology, as in geological time or geological survey. It modifies nouns rather than naming the field.","definitionCN":"形容词，如地质年代、地质调查；它修饰名词，而非命名学科。"},{"word":"geography","ipa":"/dʒiˈɒɡrəfi/","tag":"description of places","definition":"The study of places, climate and distribution, built on -graphy 'write'; geology reads what lies under the surface, geography describes what lies on it.","definitionCN":"研究地点、气候与分布，词基为 -graphy“书写”；地质学读地下，地理学描述地上。"},{"word":"geomorphology","ipa":"/ˌdʒiːəmɔːˈfɒlədʒi/","tag":"landform branch","definition":"The branch of geology and geography that studies landform origin; it is one subfield, not the whole science.","definitionCN":"研究地貌成因的分支，横跨地质学与地理学；它只是一个子领域，而非整门科学。"}]},{"heading":"NEAR MEANING","entries":[{"word":"earth science","ipa":"/ɜːθ ˈsaɪəns/","tag":"wider umbrella","definition":"The whole group of sciences about the planet, including atmosphere and oceans; geology is one member.","definitionCN":"关于本行星的全部科学，包括大气与海洋；地质学是其中一员。"},{"word":"stratigraphy","ipa":"/strəˈtɪɡrəfi/","tag":"layer order","definition":"The study of strata and their correlation; a core method within geology rather than a synonym for it.","definitionCN":"研究地层及其对比；是地质学的核心方法，而非其同义词。"},{"word":"geophysics","ipa":"/ˌdʒiːəʊˈfɪzɪks/","tag":"physics of the earth","definition":"The measurement and modelling of the earth's fields and interior using physical methods; it overlaps geology but asks physical questions.","definitionCN":"用物理方法测量并建模地球的场与内部；与地质学重叠，但提出的是物理问题。"},{"word":"mineralogy","ipa":"/ˌmɪnəˈrælədʒi/","tag":"minerals only","definition":"The study of mineral composition and crystal structure; narrower than geology, which also covers strata and history.","definitionCN":"研究矿物成分与晶体结构；比地质学窄，后者还覆盖地层与历史。"},{"word":"physical geography","ipa":"/ˈfɪzɪkl dʒiˈɒɡrəfi/","tag":"surface processes","definition":"The study of climate, rivers and landforms at the surface; it meets geology but keeps its focus above ground.","definitionCN":"研究地表的气候、河流与地貌；与地质学相接，但焦点保持在地上。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词。"},"normal":[{"en":"geo- 'earth' + -logy 'study': the study of the earth.","cn":"geo-“大地”+ -logy“研究”：研究大地的学问。"},{"en":"Petroleum geology, engineering geology and glacial geology are the standard branch names.","cn":"石油地质学、工程地质学、冰川地质学是标准的分支名称。"},{"en":"The noun pattern is geology, geologist, geological; only the first names the field.","cn":"名词序列是 geology、geologist、geological；只有第一个指学科。"},{"en":"The phrase the geology of an area covers sense 2 and is the most common non-academic use.","cn":"the geology of an area 这一说法对应第 2 个义项，是最常见的非学术用法。"},{"en":"geology studies stone; geography describes places; geometry measures shapes. Same prefix, three stems.","cn":"geology 研究石头，geography 描述地点，geometry 测量形状；同一前缀，三个不同词干。"}],"abstract":[{"en":"Picture a library where every shelf is a rock layer and every book a fossil.","cn":"想象一座图书馆，每一层书架都是一层岩石，每本书都是一块化石。"},{"en":"Picture a clock whose second hand takes a million years to move once.","cn":"想象一座钟，秒针走一格要一百万年。"},{"en":"Picture a building site where the blueprints include what lies fifty metres down.","cn":"想象一处工地，图纸上连地下五十米的东西也要画出来。"}]},"examples":[{"en":"He studied geology because he wanted to know why the Alps are still rising.","cn":"他学地质学，是因为想知道阿尔卑斯山为什么还在升高。"},{"en":"The geology of the delta consists of river sand over marine clay.","cn":"这个三角洲的地质由河流砂层覆盖海相黏土构成。"},{"en":"Economic geology identified a gold-bearing quartz vein under the old mine.","cn":"经济地质在旧矿下方识别出一条含金石英脉。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“地（geo）层讲逻辑（logy）”——一层压一层自有道理 → geology 地质学、地质构造","word":"geology"},"root":"希腊 gē“大地”+ logos“言说、道理”（组合形式 -logia）→ 拉丁化 geologia；现代义为研究地层与地球历史。","sensesIntro":{"en":"Eight senses fan out from one object: the layered ground. The name covers the science, the ground itself, the site report, the course, other worlds and its profitable branches.","cn":"八个义项从同一个对象展开：层状的地下。这个名称覆盖学科、地下本身、场地报告、课程、别的天体，以及它有利可图的分支。"},"semanticMap":{"core":{"en":"CORE IMAGE: a cross-section of ground in which each band is a period of time.","cn":"核心意象：一幅地下剖面，每一条带都是一段时间。"},"chain":["ACCOUNT OF THE EARTH","ROCK STRUCTURE","GROUND CONDITIONS","A TAUGHT SUBJECT","OTHER SOLID WORLDS","APPLIED BRANCHES"],"branches":[{"senses":"01 · 02","en":"SCIENCE AND OBJECT: the discipline and a region's actual layers are the two faces of one noun.","cn":"学科与对象：这门学问与某地实际的岩层，是同一个名词的两面。"},{"senses":"03","en":"SITE REPORT: what the science knows becomes a practical condition at a building site.","cn":"场地报告：这门学问所知转化成工地上的实际条件。"},{"senses":"04","en":"CURRICULUM: the field also exists as lectures, departments and degrees.","cn":"课程：这一领域也以讲座、院系与学位的形式存在。"},{"senses":"05 · 08","en":"OTHER BODIES: the name travels to any solid world, and also names the total knowledge of one such world.","cn":"别的天体：这个名称可迁移到任何固体世界，也可指关于某一世界的全部认识。"},{"senses":"06 · 07","en":"USEFUL BRANCHES: rocks hold fuel and ore, and also carry water and pollution.","cn":"有用的分支：岩石既藏燃料与矿石，也输送地下水与污染。"}]},"affixes":{"intro":{"en":"Geology is a two-part Greek compound, geo- 'earth' plus -logy 'study or account'. Both parts remain productive in modern technical English.","cn":"geology 是两段式希腊复合词：geo-“大地”加 -logy“研究或论述”。两部分在现代技术英语中仍能产。"},"latinIntro":{"en":"The -logy family reached English chiefly through Latin and French: biology, ecology, theology, psychology and technology all follow the same model.","cn":"-logy 词族主要经拉丁语与法语进入英语：biology、ecology、theology、psychology、technology 都遵循同一模式。"},"items":[{"word":"geology","structure":"geo- (earth) + -logy (study)","meaning":"the science of the earth's solid matter","meaningCN":"研究地球固体物质的科学","example":"Geology is the backbone of the mining programme.","exampleCN":"地质学是该采矿计划的主干。"},{"word":"geologist","structure":"geology + -ist (person)","meaning":"one who practises geology","meaningCN":"从事地质学的人","example":"Two geologists checked the outcrop before the blast.","exampleCN":"爆破前两名地质学家检查了露头。"},{"word":"geological","structure":"geology + -ical","meaning":"relating to geology","meaningCN":"与地质学有关的","example":"The geological map covers the whole catchment.","exampleCN":"这幅地质图覆盖整个流域。"},{"word":"geologically","structure":"geological + -ly","meaning":"in geological terms","meaningCN":"从地质角度","example":"Geologically, the island is a young volcano.","exampleCN":"从地质上看，这座岛是一座年轻的火山。"},{"word":"geophysics","structure":"geo- + physics","meaning":"physics applied to the earth","meaningCN":"应用于地球的物理学","example":"Geophysics mapped the water table by sound waves.","exampleCN":"地球物理学用声波测绘了地下水位。"},{"word":"geochemistry","structure":"geo- + chemistry","meaning":"chemistry of rocks and fluids","meaningCN":"岩石与流体的化学","example":"Geochemistry dates the granite by its isotopes.","exampleCN":"地球化学用同位素测定花岗岩年龄。"},{"word":"stratigraphy","structure":"stratum (layer) + -graphy (description)","meaning":"the description and ordering of strata","meaningCN":"对地层的描述与层序研究","example":"Stratigraphy places the ash layer between two lavas.","exampleCN":"地层学把火山灰层置于两层熔岩之间。"},{"word":"mineralogy","structure":"mineral + -logy (study)","meaning":"the study of minerals","meaningCN":"研究矿物的学问","example":"Mineralogy identified the green crystal as olivine.","exampleCN":"矿物学把那颗绿色晶体鉴定为橄榄石。"}],"latinEntries":[{"word":"gē","structure":"Greek gē (earth, land)","meaning":"earth, land, country","meaningCN":"大地；陆地；国土"},{"word":"logos","structure":"Greek logos (word, account, reason)","meaning":"word, account, reasoned explanation","meaningCN":"言词；记述；理性解释"},{"word":"geologia","structure":"Latinized gē + -logia","meaning":"an account of the earth (17th-century Latin)","meaningCN":"关于大地的论述（17 世纪拉丁语）"}]}},{"word":"geometrical","ipa_uk":"/ˌdʒiːəˈmetrɪkl/","ipa_us":"/ˌdʒiːəˈmetrɪkl/","definition_zh":"几何的；几何图形的；按几何级数增长的；规整对称的","definition_en":"relating to geometry or to shapes built from points, lines and surfaces, or increasing by a constant multiplying factor","core_image":"一把圆规与一把直尺压在六边形瓷砖的接缝上","scene":"The tiles form a geometrical pattern of hexagons that fit together without gaps.","sceneCN":"这里 geometrical 是「几何图形的」（第 2 个义项：由规则图形拼成）；句意：这些瓷砖构成一个由六边形拼成、无缝相接的几何图案。图中可辨识物件：六边形瓷砖、圆规、直尺、角度标记、网格线。","pos":[{"tag":"adj.","zh":"几何的；几何图形的；按几何级数增长的；规整对称的（多作定语）"}],"collocations":[{"phrase":"geometrical pattern","zh":"几何图案"},{"phrase":"geometrical progression","zh":"几何级数；等比数列"},{"phrase":"geometrical shape","zh":"几何形状"},{"phrase":"geometrical optics","zh":"几何光学"},{"phrase":"geometrical abstraction","zh":"几何抽象（艺术流派）"},{"phrase":"geometrical proportion","zh":"几何比例；等比"}],"forms":[{"label":"比较级（更几何的）","form":"more geometrical"},{"label":"最高级（最几何的）","form":"most geometrical"},{"label":"副词形式","form":"geometrically（几何上；按几何方式）"},{"label":"较短变体","form":"geometric（更常用，尤见于术语与北美用法）"}],"derivatives":[{"word":"geometry","pos":"n.","zh":"几何学；几何形状；空间布置"},{"word":"geometric","pos":"adj.","zh":"几何的（较短变体）"},{"word":"geometrically","pos":"adv.","zh":"在几何上；按几何方式"},{"word":"geometer","pos":"n.","zh":"几何学家；（古）土地测量员"},{"word":"geometrician","pos":"n.","zh":"几何学家"}],"senses":[{"no":"01","title":"Of the science of geometry","titleCN":"几何学的：属于这门学科","definition":"belonging to the branch of mathematics that deals with points, lines, angles and figures","definitionCN":"属于研究点、线、角与图形的数学分支","example":"The proof uses purely geometrical reasoning, with no algebra.","exampleCN":"这个证明只用纯几何推理，不含代数。","why":"geōmetria in Greek meant 'land measurement', built from gē 'earth' and metron 'measure'; -ical makes the relational adjective.","whyCN":"希腊 geōmetria 意为“土地测量”，由 gē“大地”与 metron“测量”构成；-ical 构成关系形容词。"},{"no":"02","title":"Built from regular shapes","titleCN":"几何图形的：由规则图形拼成","definition":"made of or resembling regular figures such as circles, triangles and polygons","definitionCN":"由圆、三角形、多边形等规则图形构成或形似的","example":"The façade is covered in a geometrical grid of squares and circles.","exampleCN":"立面覆满由方形与圆形组成的几何网格。","why":"When drawing replaces measuring land, the adjective comes to describe anything whose outline is a figure from the textbook.","whyCN":"当绘图取代丈量土地后，这个形容词便用来描述任何轮廓取自教科书的图形之物。"},{"no":"03","title":"Multiplying by a fixed factor","titleCN":"按几何级数增长的：倍数递增","definition":"increasing or decreasing by a constant ratio at each step, as in a geometrical progression","definitionCN":"每一步按固定比例增减，如等比数列","example":"Bacteria in a flask grow in a geometrical progression, doubling every twenty minutes.","exampleCN":"瓶中的细菌按几何级数增长，每二十分钟翻一番。","why":"Ancient mathematicians compared arithmetic growth, which adds a constant, with geometrical growth, which multiplies by a constant; the metaphor survives in the adjective.","whyCN":"古代数学把每次加常数的算术增长与每次乘常数的几何增长相对照，这一比喻留存于该形容词中。"},{"no":"04","title":"Regular and precisely ordered","titleCN":"规整对称的：精确而有秩序","definition":"having a regular, balanced and precisely ordered arrangement","definitionCN":"具有规则、均衡且精确有序的排布","example":"The garden's geometrical layout is best seen from the air.","exampleCN":"这座园林的规整布局从空中看最清楚。","why":"Figures drawn with compass and rule look exact, so the adjective transfers from the drawing to anything that shares its regularity.","whyCN":"用圆规与直尺画出的图形看上去精确，因此这个形容词从图纸转移到任何具有同样规则性的事物。"},{"no":"05","title":"Proved by construction","titleCN":"几何证明的：靠作图与推理","definition":"in mathematics, handled by construction and logical deduction from axioms rather than by algebra","definitionCN":"数学中指通过作图与由公理出发的逻辑演绎来处理，而非用代数","example":"The ancients solved the problem by a geometrical construction with compass and rule.","exampleCN":"古代人用圆规与直尺的几何作图解决了这个问题。","why":"Classical geometry allowed only compass and straightedge; the adjective marks that restricted, constructive style of proof.","whyCN":"古典几何只允许圆规与直尺；这个形容词标记的正是这种受限的作图式证明风格。"},{"no":"06","title":"Of spatial relations","titleCN":"空间关系的：位置与角度","definition":"relating to the spatial relations of position, distance and angle","definitionCN":"关于位置、距离与角度等空间关系的","example":"The software checks the geometrical fit of every joint before cutting.","exampleCN":"软件在下料前检查每个接头的几何配合。","why":"Geometry is the mathematics of space, so the adjective names spatial fit even when no textbook figure is drawn.","whyCN":"几何学是关于空间的数学，因此即使没有画出教科书图形，这个形容词也可指空间上的配合。"},{"no":"07","title":"Reduced to basic shapes in art","titleCN":"几何抽象的：艺术中简化为基本形","definition":"in art, describing work built from basic shapes rather than from observed forms","definitionCN":"艺术中指以基本形而非观察所得形态来构建作品","example":"The movement preferred geometrical abstraction to any trace of landscape.","exampleCN":"这一流派偏爱几何抽象，而不是任何风景痕迹。","why":"Modern painters removed representational detail until only squares and circles remained, and critics named the result with this adjective.","whyCN":"现代画家删去再现性细节，直到只剩方块与圆圈，评论者便用这个形容词命名结果。"},{"no":"08","title":"Of land survey","titleCN":"土地测量的：历史上的丈量术","definition":"in historical use, relating to the measuring and dividing of land","definitionCN":"历史用法中指对土地进行丈量与划分","example":"The old geometrical method divided the field into equal strips.","exampleCN":"旧的测量方法把这块田划分成等宽的条带。","why":"The original geōmetria was literally field measurement, and the adjective preserves that earliest practical meaning.","whyCN":"最初的 geōmetria 字面就是田地丈量，这个形容词保留了那一最早的实用含义。"}],"etymology":{"intro":{"en":"Geometrical comes from Greek geōmetria 'land measurement', gē 'earth' plus metron 'measure', with the adjective ending -ical. Dates are approximate.","cn":"geometrical 出自希腊 geōmetria“土地测量”，由 gē“大地”加 metron“测量”构成，再加形容词词尾 -ical。年代为约数。"},"items":[{"era":"GREEK COMPOUND","en":"geōmetria joined gē 'earth' with metron 'measure'. The practice came first: Egyptian and Greek surveyors re-divided farmland after the Nile floods each year.","cn":"geōmetria 把 gē“大地”与 metron“测量”结合。实践在先：埃及与希腊的测量员每年尼罗河泛滥后重新划分农田。"},{"era":"LATIN AND FRENCH","en":"Latin borrowed the word as geometria, and Old French formed geometrie. English geometry appears in the 14th century.","cn":"拉丁语借作 geometria，古法语构成 geometrie。英语 geometry 于 14 世纪出现。"},{"era":"FROM LAND TO PROOF","en":"Between the 6th century BC and Euclid's Elements (around 300 BC), measurement became deductive proof, and the subject's name stayed even after the fields were left behind.","cn":"从公元前 6 世纪到欧几里得《几何原本》（约公元前 300 年），丈量变成演绎证明，而学科名称在离开田地之后仍然保留。"},{"era":"ADJECTIVE FORM","en":"-ical comes from Latin -icalis, from Greek -ikos. English already had geometric from Latin geometricus; geometrical arose as the longer variant.","cn":"-ical 来自拉丁 -icalis，后者出自希腊 -ikos。英语已有来自拉丁 geometricus 的 geometric，geometrical 是较长的变体。"},{"era":"MODERN EXTENSIONS","en":"Geometrical progression kept the multiplier sense, geometrical optics and geometrical abstraction extended the shape sense into physics and art.","cn":"geometrical progression 保留了“倍数”义，geometrical optics 与 geometrical abstraction 则把“形状”义延伸到物理与艺术。"},{"era":"UNCERTAIN DETAILS","en":"The date when geōmetria first shifted from surveying to proof is inferred from fragmentary sources, and the deeper origin of metron is reconstructed rather than recorded.","cn":"geōmetria 从丈量转为证明的确切时间只能从零散材料推断；metron 的更深来源属重构而非有记录。"}]},"similar":{"note":{"en":"The first group contains shortened forms and word relatives that are often confused; the second contains adjectives for related mathematical or spatial ideas.","cn":"第一组易混的是截短形式与同族词；第二组是相关数学或空间概念的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"geometric","ipa":"/ˌdʒiːəˈmetrɪk/","tag":"same meaning, shorter","definition":"The shorter adjective, overwhelmingly preferred in technical terms such as geometric mean and geometric series. The difference is convention, not sense.","definitionCN":"较短形容词，在 geometric mean、geometric series 等术语中占绝对优势；差别在惯例而非词义。"},{"word":"geometry","ipa":"/dʒiˈɒmətri/","tag":"the noun","definition":"The discipline or the shape and arrangement of a space. It cannot modify a noun as the adjective does.","definitionCN":"指学科，或某空间中的形状与布置；不能像形容词那样修饰名词。"},{"word":"geometrically","ipa":"/ˌdʒiːəˈmetrɪkli/","tag":"adverb","definition":"The adverb meaning 'in geometric terms' or 'by geometric growth'. It modifies verbs and adjectives.","definitionCN":"副词，意为“从几何上”或“按几何方式增长”，修饰动词与形容词。"},{"word":"geographer","ipa":"/dʒiˈɒɡrəfə/","tag":"places, not shapes","definition":"A specialist in places and distribution. It shares geo- but its second element means 'write', not 'measure'.","definitionCN":"研究地点与分布的专家；共用 geo-，但第二构件意为“书写”而非“测量”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"symmetrical","ipa":"/sɪˈmetrɪkl/","tag":"balanced halves","definition":"Having matched parts on opposite sides; it shares metron but stresses balance rather than measurable shape.","definitionCN":"两侧部件相互对应；同含 metron，但强调均衡而非可测量的形状。"},{"word":"spatial","ipa":"/ˈspeɪʃl/","tag":"space in general","definition":"Relating to space and position without implying measurement or proof.","definitionCN":"关于空间与位置，但不含测量或证明之意。"},{"word":"angular","ipa":"/ˈæŋɡjələ/","tag":"corners, not figures","definition":"Having angles or sharp corners; more specific than geometrical, which covers all regular figures.","definitionCN":"有角或尖角的；比覆盖一切规则图形的 geometrical 更具体。"},{"word":"proportional","ipa":"/prəˈpɔːʃənl/","tag":"matching ratios","definition":"Increasing together at a constant ratio; it names the relationship, while geometrical progression names the pattern of steps.","definitionCN":"按固定比例一同增减；它命名关系，而几何级数命名的是逐级模式。"},{"word":"regular","ipa":"/ˈreɡjələ/","tag":"even and ordered","definition":"Evenly arranged or shaped; it describes the impression of order that a geometrical figure produces.","definitionCN":"排布或形状均匀；描述几何图形给人的秩序感。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词。"},"normal":[{"en":"geo- 'earth' + metron 'measure' + -ical: measurement of the earth, then the mathematics of shape.","cn":"geo-“大地”+ metron“测量”+ -ical：丈量土地，后指关于形状的数学。"},{"en":"geometrical progression is the fixed-ratio sense; geometrical pattern is the shape sense.","cn":"geometrical progression 是固定比例义；geometrical pattern 是形状义。"},{"en":"The family is geometry, geometer, geometric, geometrical, geometrically, geometrician.","cn":"同族词是 geometry、geometer、geometric、geometrical、geometrically、geometrician。"},{"en":"Compass and straightedge are the classical tools, which is why sense 5 means proof by construction.","cn":"圆规与直尺是古典工具，这正是第 5 个义项意为“作图证明”的原因。"},{"en":"geology reads layers, geometry measures shapes: -logy versus metron.","cn":"geology 读岩层，geometry 量形状：-logy 对 metron。"}],"abstract":[{"en":"Picture a tiled floor where every hexagon touches six others exactly.","cn":"想象一片地砖，每个六边形恰好与六个相邻者相接。"},{"en":"Picture one bacterium becoming two, two becoming four, the count doubling faster than the eye can follow.","cn":"想象一个细菌变两个、两个变四个，数目翻倍快到眼睛跟不上。"},{"en":"Picture an artist erasing a landscape until only a square and a circle remain.","cn":"想象一位画家不断擦去风景，直到只剩一个方块和一个圆。"}]},"examples":[{"en":"The hall's ceiling is a geometrical arrangement of intersecting vaults.","cn":"大厅的天花板是由交叉拱顶构成的几何排布。"},{"en":"In a geometrical progression, each term is the previous one multiplied by the same number.","cn":"在几何级数中，每一项都是前一项乘同一个数。"},{"en":"The artist turned to geometrical abstraction after abandoning portraits.","cn":"这位艺术家在放弃肖像之后转向几何抽象。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“地（geo）上有米（metr）尺”——量地用的尺，量出形状 → geometrical 几何的、规整的","word":"geometrical"},"root":"希腊 gē“大地”+ metron“测量”→ geōmetria“土地丈量”；拉丁 geometria + 英语 -ical（关系形容词）。","sensesIntro":{"en":"Eight senses start from measuring land, pass through the drawn figure, and end in ratios, order, proof, spatial fit, abstract art and survey.","cn":"八个义项从丈量土地开始，经过画出的图形，最终落在比例、秩序、证明、空间配合、抽象艺术与测量。"},"semanticMap":{"core":{"en":"CORE IMAGE: compass and rule pressed onto a floor of touching hexagons.","cn":"核心意象：圆规与直尺压在一片彼此相接的六边形地面上。"},"chain":["MEASURE THE LAND","DRAW THE FIGURE","MULTIPLY BY A RATIO","ORDER AND SYMMETRY","PROVE BY CONSTRUCTION","FIT IN SPACE"],"branches":[{"senses":"01 · 08","en":"MEASUREMENT: the science and its oldest field practice are the same root seen in classroom and field.","cn":"测量：这门学科与它最古老的田间实践，是同一词根在课堂与田野的两种样子。"},{"senses":"02 · 04 · 07","en":"THE DRAWN SHAPE: regular figures, visible order and abstract art all rest on the primacy of the outline.","cn":"画出的形：规则图形、可见秩序与抽象艺术都以轮廓为先。"},{"senses":"03","en":"RATIO: multiplying by a fixed factor is the numerical twin of drawing to scale.","cn":"比例：按固定倍数增长，是按比例作图的数值孪生。"},{"senses":"05","en":"PROOF: compass and straightedge turn measurement into deduction.","cn":"证明：圆规与直尺把测量变成演绎。"},{"senses":"06","en":"SPATIAL FIT: geometry governs whether parts meet, clear or collide.","cn":"空间配合：几何决定部件是相接、让开还是相撞。"}]},"affixes":{"intro":{"en":"Geometrical splits into geo- 'earth', metr- 'measure' and -ical 'relating to'. The middle element also builds meter, symmetry and parameter.","cn":"geometrical 可拆为 geo-“大地”、metr-“测量”与 -ical“与……有关”。中间构件也构成 meter、symmetry、parameter。"},"latinIntro":{"en":"Greek metron reached English through Latin in a wide family: metre, meter, symmetry, asymmetry, parameter, diameter and perimeter.","cn":"希腊 metron 经拉丁语进入英语，形成宽泛词族：metre、meter、symmetry、asymmetry、parameter、diameter、perimeter。"},"items":[{"word":"geometrical","structure":"geo- + metr- + -ical","meaning":"relating to shape, measurement or fixed ratios","meaningCN":"与形状、度量或固定比例有关的","example":"The mosaic follows a strict geometrical plan.","exampleCN":"这幅镶嵌画遵循严格的几何方案。"},{"word":"geometry","structure":"geo- + metron + -y (noun)","meaning":"the mathematics of shape and space","meaningCN":"研究形状与空间的数学","example":"Geometry tells you that the three angles sum to two right angles.","exampleCN":"几何学告诉你，这三个角之和等于两个直角。"},{"word":"geometric","structure":"geo- + metr- + -ic","meaning":"the shorter adjective form","meaningCN":"较短的形容词形式","example":"The geometric mean of 4 and 9 is 6.","exampleCN":"4 与 9 的几何平均数是 6。"},{"word":"geometrically","structure":"geometrical + -ly","meaning":"in geometric terms","meaningCN":"从几何上","example":"The two curves are geometrically similar.","exampleCN":"这两条曲线在几何上相似。"},{"word":"geometer","structure":"geo- + metr- + -er (person)","meaning":"a geometry specialist; formerly a surveyor","meaningCN":"几何学家；古义为测量员","example":"The ancient geometer measured the pyramid by its shadow.","exampleCN":"古代测量者用影子测量金字塔。"},{"word":"symmetry","structure":"syn- (together) + metron (measure) + -y","meaning":"balanced measurement of parts","meaningCN":"各部分均衡的度量关系","example":"The flower's symmetry is obvious from above.","exampleCN":"从上方看，这朵花的对称很明显。"},{"word":"parameter","structure":"para- (beside) + metron (measure)","meaning":"a measured value that defines a system","meaningCN":"界定系统的测量值；参数","example":"Each model has three adjustable parameters.","exampleCN":"每个模型有三个可调参数。"},{"word":"diameter","structure":"dia- (across) + metron (measure)","meaning":"the measure across a circle","meaningCN":"穿过圆的度量；直径","example":"The pipe's diameter is forty centimetres.","exampleCN":"这根管子的直径是四十厘米。"}],"latinEntries":[{"word":"geōmetria","structure":"gē (earth) + metron (measure) + -ia","meaning":"land measurement, surveying","meaningCN":"土地丈量；测量术"},{"word":"geometria","structure":"Latin borrowing of Greek geōmetria","meaning":"geometry, the measurement of figures","meaningCN":"几何；对图形的度量"},{"word":"metron","structure":"Greek metron (measure)","meaning":"a measure, a due proportion","meaningCN":"尺度；合宜的比例"}]}},{"word":"gradual","ipa_uk":"/ˈɡrædʒuəl/","ipa_us":"/ˈɡrædʒuəl/","definition_zh":"逐渐的；渐进的；平缓的；分阶段的","definition_en":"happening or changing slowly in small steps over time, rather than suddenly or all at once","core_image":"一段被切成许多矮台阶的斜坡，每一级只抬高一点点","scene":"The recovery has been gradual, with small gains in each quarter.","sceneCN":"这里 gradual 是「逐渐的」（第 1 个义项：在时间上分小步推进）；句意：复苏一直是渐进的，每个季度都有一点小增长。图中可辨识物件：阶梯状折线、季度刻度、上升小箭头、日历、斜坡剖面。","pos":[{"tag":"adj.","zh":"逐渐的；渐进的；平缓的；分阶段的（多作定语，也可作表语）"},{"tag":"n.","zh":"（宗教）升阶经（弥撒中读经之间唱的圣咏；少见用法）"}],"collocations":[{"phrase":"gradual change","zh":"逐渐的变化"},{"phrase":"gradual increase","zh":"逐步增长"},{"phrase":"gradual decline","zh":"缓慢下降；渐次衰退"},{"phrase":"gradual process","zh":"渐进过程"},{"phrase":"a gradual slope","zh":"平缓的坡"},{"phrase":"gradual recovery","zh":"缓慢复苏"}],"forms":[{"label":"比较级（更渐进的）","form":"more gradual"},{"label":"最高级（最渐进的）","form":"most gradual"},{"label":"副词形式","form":"gradually（逐渐地）"},{"label":"名词形式","form":"gradualness（渐进性）"}],"derivatives":[{"word":"gradually","pos":"adv.","zh":"逐渐地；一步步地"},{"word":"gradualness","pos":"n.","zh":"渐进性；缓慢程度"},{"word":"grade","pos":"n. / v.","zh":"等级；坡度；分级（同出拉丁 gradus）"},{"word":"gradient","pos":"n.","zh":"梯度；坡度（同出 gradus）"},{"word":"graduate","pos":"v. / n.","zh":"毕业；毕业生（同出 gradus“步、级”）"}],"senses":[{"no":"01","title":"Changing by small steps","titleCN":"逐渐的：小步推进而不骤然改变","definition":"happening slowly through a series of small steps rather than in one sudden movement","definitionCN":"通过一系列小步骤缓慢发生，而非一次骤然完成","example":"The lake's level has shown a gradual fall since the dam was built.","exampleCN":"自水坝建成以来，湖面一直逐渐下降。","why":"gradual comes from Latin gradus 'step' plus -alis; the word pictures change as a staircase of single steps.","whyCN":"gradual 出自拉丁 gradus“步”加 -alis；这个词把变化想象成由一个个单步组成的台阶。"},{"no":"02","title":"Not sudden","titleCN":"不突然的：没有突变的那一刻","definition":"lacking any sharp break or abrupt event","definitionCN":"不存在任何突兀的断裂或突发事件","example":"The transition from summer to autumn here is gradual and almost unnoticed.","exampleCN":"这里从夏到秋的过渡很平缓，几乎无人察觉。","why":"A process made of many steps has no single dramatic moment, so the adjective often simply denies suddenness.","whyCN":"由许多小步构成的过程没有某个戏剧性瞬间，因此这个形容词常只是否认“突然”。"},{"no":"03","title":"Carried out in stages","titleCN":"分阶段的：按预定步骤分批实施","definition":"planned and applied in successive stages rather than all at once","definitionCN":"按连续阶段规划与实施，而非一次全部推行","example":"The council approved a gradual withdrawal of the subsidy over five years.","exampleCN":"议会批准在五年内分阶段取消这项补贴。","why":"Policy borrows the staircase image: each stage is a step, and the adjective marks that deliberate pacing.","whyCN":"政策借用了阶梯意象：每个阶段就是一级台阶，这个形容词标记的正是那种有意安排的节奏。"},{"no":"04","title":"Gently sloping","titleCN":"平缓的：坡度不大的","definition":"of a slope or curve, rising or falling without steepness","definitionCN":"指坡面或曲线升降不急、不陡","example":"A gradual slope leads from the road up to the terrace.","exampleCN":"一道平缓的坡从公路通向平台。","why":"A gentle slope rises a little with each step, exactly like slow change; the same word covers ground and time.","whyCN":"缓坡每走一步只升高一点，正像缓慢变化；同一个词因此同时覆盖地面与时间。"},{"no":"05","title":"Of step-by-step reform","titleCN":"渐进改革的：不做一次性大改","definition":"describing reform that proceeds by measured increments instead of a single sweeping change","definitionCN":"形容按有节制的增量推进、而非一次大改的改革","example":"The gradual reform avoided shock but left old problems half-solved.","exampleCN":"渐进改革避免了震荡，却让旧问题只解决了一半。","why":"Politics contrasts gradual with radical; both words measure how many steps are taken at once.","whyCN":"政治语境把 gradual 与 radical 相对照；两者衡量的都是一次迈出多少步。"},{"no":"06","title":"Mild in force","titleCN":"和缓的：力度不猛","definition":"applied with mild force, so that effects accumulate rather than strike at once","definitionCN":"以温和力度施加，使效果累积而非一次冲击","example":"A gradual warming of the solution prevents the crystals from cracking.","exampleCN":"让溶液缓慢升温，可以防止晶体开裂。","why":"In the laboratory the staircase is thermal: raising temperature by degrees avoids a thermal shock.","whyCN":"在实验室里，阶梯是温度的：逐度升温可避免热冲击。"},{"no":"07","title":"Rising by grades","titleCN":"逐级递进的：按等级一层层上升","definition":"arranged as a series of ranks or levels, each reached from the one below","definitionCN":"按一系列等级或层次排列，每一级都由下一级升上来","example":"The guild set gradual ranks from apprentice to master.","exampleCN":"行会设定了从学徒到师傅的逐级等级。","why":"Latin gradus also meant a rank or degree; the adjective can describe a ladder of status, not only of time.","whyCN":"拉丁 gradus 也指等级或品级；这个形容词可以描述身份的阶梯，而不只是时间的阶梯。"},{"no":"08","title":"The chant of the steps","titleCN":"升阶经：教堂台阶上唱的圣咏","definition":"as a noun, a liturgical chant sung between the readings of the Mass","definitionCN":"作名词时指弥撒读经之间咏唱的礼仪圣咏","example":"The choir sang the gradual before the Gospel reading.","exampleCN":"唱诗班在福音诵读之前唱了升阶经。","why":"Graduale was the Latin name for this chant, probably from the steps (gradus) of the ambo where it was sung; the musical sense is a separate branch from the adjective.","whyCN":"graduale 是这首圣咏的拉丁名称，可能来自咏唱所在读经台的台阶（gradus）；这一音乐义项与形容词义是两个分支。"}],"etymology":{"intro":{"en":"Gradual is Latin gradus 'step' plus the adjective suffix -alis. The musical noun gradual came by a separate route from the same root. Dates are approximate.","cn":"gradual 是拉丁 gradus“步”加形容词后缀 -alis。音乐义的名词 gradual 则从同一词根经另一条路径而来。年代为约数。"},"items":[{"era":"LATIN NOUN","en":"gradus meant 'step, pace, degree, rank'. It came from the verb gradi 'to walk, go', whose deeper origin is usually reconstructed as a Indo-European root meaning 'to walk'. That deeper form is a reconstruction.","cn":"gradus 意为“步、步伐、等级、品级”，出自动词 gradi“行走、前进”，其更深来源通常被重构为某个意为“行走”的印欧词根。该更深形式属重构。"},{"era":"LATIN ADJECTIVE","en":"gradalis or gradualis meant 'of a step or grade'. Medieval Latin graduale also named the chant sung on the steps of the ambo.","cn":"gradalis 或 gradualis 意为“与步、级有关的”。中世纪拉丁 graduale 也指在读经台台阶上咏唱的圣咏。"},{"era":"ENGLISH ADJECTIVE","en":"English gradual appears in the 15th century meaning 'step by step, by degrees'. The sense 'gentle in slope' follows from the same image.","cn":"英语 gradual 于 15 世纪出现，意为“一步一步地、逐级地”。“坡度平缓”义也由同一意象衍生。"},{"era":"RELIGIOUS NOUN","en":"The noun gradual, for the chant between readings, entered English through the Latin liturgical book called the graduale.","cn":"指读经之间圣咏的名词 gradual，经名为 graduale 的拉丁礼仪书进入英语。"},{"era":"MODERN POLITICAL USE","en":"From the 19th century gradual became a standard label for step-by-step reform, opposed to radical or sudden change.","cn":"自 19 世纪起，gradual 成为“分步改革”的标准标签，与激进或骤然变化相对。"},{"era":"UNCERTAIN DETAILS","en":"Whether the chant was named for the ambo steps or for the gradus sung in the melody is disputed, and the Indo-European root behind gradi is reconstructed rather than attested.","cn":"该圣咏是因读经台台阶得名，还是因曲调中的“阶级”得名，存在争议；gradi 背后的印欧词根属重构而非有据。"}]},"similar":{"note":{"en":"The first group contains words from the same grad- stem; the second contains near-synonyms that stress pace or mildness.","cn":"第一组同出 grad- 词干；第二组是强调速度或温和程度的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"gradually","ipa":"/ˈɡrædʒuəli/","tag":"adverb, not adjective","definition":"The adverb meaning 'step by step'. It modifies a verb; gradual modifies a noun or follows a linking verb.","definitionCN":"副词，意为“一步一步地”，修饰动词；gradual 修饰名词或跟在系动词后。"},{"word":"graduate","ipa":"/ˈɡrædʒuət/","tag":"same root, different path","definition":"A person who has completed a degree, or the verb 'to complete study'. It shares gradus but names a rank reached, not a pace of change.","definitionCN":"指完成学位的人，或“毕业”这一动词；同出 gradus，但命名的是达到的等级，而非变化的速度。"},{"word":"grade","ipa":"/ɡreɪd/","tag":"level or slope","definition":"A rank, a mark, or the steepness of a slope. It is the bare noun behind gradual, without the 'step-by-step' adjective sense.","definitionCN":"等级、分数或坡度；是 gradual 背后的名词本体，但不含“逐步”这一形容词义。"},{"word":"gradient","ipa":"/ˈɡreɪdiənt/","tag":"rate of change","definition":"The rate at which a quantity changes over distance; technical and measurable, unlike gradual's general pacing.","definitionCN":"某量随距离变化的比率；属技术可测量概念，不同于 gradual 的一般节奏描述。"}]},{"heading":"NEAR MEANING","entries":[{"word":"progressive","ipa":"/prəˈɡresɪv/","tag":"advancing in stages","definition":"Moving forward stage by stage; it adds direction and often approval, while gradual is neutral about where things go.","definitionCN":"逐阶段向前推进；带有方向感，常含褒义，而 gradual 对去向保持中性。"},{"word":"incremental","ipa":"/ɪnˈkreməntl/","tag":"small additions","definition":"Growing by small added amounts; it stresses quantity added, while gradual stresses time and pace.","definitionCN":"以小额增量累积；强调增加的量，而 gradual 强调时间与节奏。"},{"word":"slow","ipa":"/sləʊ/","tag":"low speed","definition":"At low speed; it says nothing about steps or stages, only about rate.","definitionCN":"速度低；不涉及步骤或阶段，只说速率。"},{"word":"gentle","ipa":"/ˈdʒentl/","tag":"mild in effect","definition":"Mild and not forceful; closer to sense 6 than to the general 'step by step' meaning.","definitionCN":"温和而不猛烈；更接近第 6 个义项，而非一般的“逐步”义。"},{"word":"steady","ipa":"/ˈstedi/","tag":"even and regular","definition":"Regular and unchanging in rate; it can be fast, provided the pace does not vary.","definitionCN":"速率稳定不变；只要节奏不变，也可以是快的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词。"},"normal":[{"en":"grad- 'step' + -ual: made of steps.","cn":"grad-“步”+ -ual：由一级级台阶构成的。"},{"en":"gradual change, gradual increase and gradual decline are the three commonest collocations.","cn":"gradual change、gradual increase、gradual decline 是最常见的三个搭配。"},{"en":"The family runs grade, gradient, gradual, gradually, gradualness and graduate.","cn":"同族词有 grade、gradient、gradual、gradually、gradualness、graduate。"},{"en":"gradual is the adjective, gradually the adverb; 'change gradual' is wrong, 'change gradually' is right.","cn":"gradual 是形容词，gradually 是副词；说 change gradual 是错的，change gradually 才对。"},{"en":"A gradual slope is a slope you can walk up without climbing.","cn":"缓坡就是不用攀爬就能走上去的坡。"}],"abstract":[{"en":"Picture a long staircase whose every step is only a centimetre high.","cn":"想象一段长楼梯，每级只有一厘米高。"},{"en":"Picture a line on a graph that never jumps, only bends a little.","cn":"想象图上一条从不跳跃、只微微弯折的线。"},{"en":"Picture a choir singing on the stone steps of a reading stand.","cn":"想象唱诗班站在读经台的石阶上咏唱。"}]},"examples":[{"en":"The shift from hand tools to machines was gradual, not a single invention.","cn":"从手工工具到机器的转变是渐进的，并非某一项发明一蹴而就。"},{"en":"Doctors recommended a gradual return to exercise after the injury.","cn":"医生建议受伤后逐步恢复运动。"},{"en":"The path rises in a gradual curve towards the ridge.","cn":"小路以平缓的弧度升向山脊。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“格（gra）外（dual）慢一点”——一格一格地走 → gradual 逐渐的、平缓的","word":"gradual"},"root":"拉丁 gradus“步、级”+ -alis（形容词后缀）；gradus 出自 gradi“行走”，更深词根为重构形式。","sensesIntro":{"en":"Eight senses share one picture: change as a staircase. The steps can measure time, policy, slope, force, rank, or the stone steps of a church.","cn":"八个义项共享一个意象：变化如阶梯。这些台阶可以量时间、量政策、量坡度、量力度、量等级，也可以是教堂里的石阶。"},"semanticMap":{"core":{"en":"CORE IMAGE: a slope cut into many low steps, each raising the ground a little.","cn":"核心意象：一段被切成许多矮台阶的坡，每一级只把地面抬高一点。"},"chain":["ONE STEP","MANY SMALL STEPS","NO SUDDEN BREAK","PLANNED STAGES","GENTLE SLOPE","ORDERED RANKS"],"branches":[{"senses":"01 · 02","en":"TIME: slow change and the absence of a sudden moment are the same staircase seen from two angles.","cn":"时间：缓慢变化与没有突变瞬间，是同一条阶梯的两个视角。"},{"senses":"03 · 05","en":"POLICY: staged withdrawal and step-by-step reform make the staircase deliberate.","cn":"政策：分阶段取消与逐步改革，使这条阶梯成为有意设计。"},{"senses":"04","en":"GROUND: a gentle slope is the staircase transferred from time to terrain.","cn":"地面：缓坡就是阶梯从时间转移到地形。"},{"senses":"06","en":"FORCE: mild heating raises the value by degrees so nothing cracks.","cn":"力度：温和加热逐度提升，使物体不致开裂。"},{"senses":"07 · 08","en":"RANKS AND STEPS: status levels and the chant of the ambo both come from gradus as a physical or social step.","cn":"等级与台阶：身份层级与读经台圣咏，都来自作为实体或社会台阶的 gradus。"}]},"affixes":{"intro":{"en":"Gradual is a Latin adjective: the root grad- 'step' plus -alis. English also keeps the bare root in grade, gradient and graduate.","cn":"gradual 是拉丁形容词：词根 grad-“步”加 -alis。英语也在 grade、gradient、graduate 中保留了这个裸词根。"},"latinIntro":{"en":"Latin gradus and the verb gradi produced a family in English and the Romance languages: grade, gradation, gradient, gradual, graduate, degrade and upgrade.","cn":"拉丁 gradus 与动词 gradi 在英语及罗曼语族中衍生出词族：grade、gradation、gradient、gradual、graduate、degrade、upgrade。"},"items":[{"word":"gradual","structure":"grad- (step) + -ual (-alis)","meaning":"proceeding step by step","meaningCN":"一步一步进行的","example":"The patient made a gradual return to work.","exampleCN":"这位病人逐步恢复了工作。"},{"word":"gradually","structure":"gradual + -ly","meaning":"step by step, little by little","meaningCN":"一步一步地；逐渐地","example":"The sky gradually turned from grey to gold.","exampleCN":"天空渐渐由灰转金。"},{"word":"gradualness","structure":"gradual + -ness (abstract noun)","meaning":"the quality of being step-by-step","meaningCN":"渐进性","example":"The gradualness of the change made it hard to date.","exampleCN":"变化的渐进性使它难以确定年代。"},{"word":"grade","structure":"Latin gradus (step, rank)","meaning":"a level, a mark, or a slope","meaningCN":"等级；分数；坡度","example":"The road climbs a steep grade for two kilometres.","exampleCN":"这段路以陡坡爬升两公里。"},{"word":"gradient","structure":"grad- + -ient (that which)","meaning":"the rate of rise or change","meaningCN":"梯度；变化率","example":"The temperature gradient across the plate drives the current.","exampleCN":"板上的温度梯度驱动了这股流动。"},{"word":"graduate","structure":"gradus + -ate (to take a degree)","meaning":"to complete a course of study","meaningCN":"完成学业；毕业","example":"She graduated from the programme in four years.","exampleCN":"她用四年读完了这个项目。"},{"word":"degrade","structure":"de- (down) + gradus (step)","meaning":"to lower in rank or quality","meaningCN":"降级；使退化","example":"Heat and light degrade the polymer over time.","exampleCN":"热与光会随时间使这种聚合物退化。"},{"word":"upgrade","structure":"up- + gradus (step)","meaning":"to raise to a higher grade","meaningCN":"升级；提升等级","example":"The airline upgraded her seat at no cost.","exampleCN":"航空公司免费为她升了舱位。"}],"latinEntries":[{"word":"gradus","structure":"gradus, -ūs (n., fourth declension)","meaning":"step, pace, degree, rank","meaningCN":"步；步伐；等级；品级"},{"word":"gradi","structure":"gradi (deponent verb)","meaning":"to walk, to go step by step","meaningCN":"行走；一步步前进"},{"word":"graduale","structure":"Medieval Latin graduale (of the steps)","meaning":"the chant sung at the steps of the ambo","meaningCN":"在读经台台阶处咏唱的圣咏"}]}},{"word":"gradually","ipa_uk":"/ˈɡrædʒuəli/","ipa_us":"/ˈɡrædʒuəli/","definition_zh":"逐渐地；逐步地；缓慢地；不知不觉地","definition_en":"in small steps over a period of time, rather than suddenly or all at once","core_image":"一条折线每走一小格才抬高一丝，从不直冲向上","scene":"The water gradually cleared as the sediment settled to the bottom.","sceneCN":"这里 gradually 是「逐渐地」（第 1 个义项：随时间分小步变化）；句意：随着泥沙沉到水底，水逐渐变清了。图中可辨识物件：沉降的泥沙、由浑到清的水柱、时间轴、取样瓶、缓慢下降的箭头。","pos":[{"tag":"adv.","zh":"逐渐地；逐步地；缓慢地；不知不觉地（修饰动词、形容词或整句，位置较灵活）"}],"collocations":[{"phrase":"gradually increase","zh":"逐渐增加"},{"phrase":"gradually decline","zh":"逐渐下降"},{"phrase":"gradually become","zh":"逐渐变得……"},{"phrase":"gradually replaced by","zh":"逐渐被……取代"},{"phrase":"gradually build up","zh":"逐步积累"},{"phrase":"gradually come to realize","zh":"渐渐意识到"}],"forms":[{"label":"比较级（更逐渐地）","form":"more gradually"},{"label":"最高级（最逐渐地）","form":"most gradually"},{"label":"形容词形式","form":"gradual（逐渐的；平缓的）"},{"label":"名词形式","form":"gradualness（渐进性）"}],"derivatives":[{"word":"gradual","pos":"adj.","zh":"逐渐的；平缓的"},{"word":"gradualness","pos":"n.","zh":"渐进性"},{"word":"grade","pos":"n. / v.","zh":"等级；坡度（同出 gradus）"},{"word":"gradient","pos":"n.","zh":"梯度；坡度"},{"word":"graduate","pos":"v. / n.","zh":"毕业；毕业生"}],"senses":[{"no":"01","title":"Little by little","titleCN":"逐渐地：一点一点地发生","definition":"in small amounts over time, so that the change is felt only after a while","definitionCN":"随时间以小量发生，要过一段时间才被察觉","example":"The cough gradually disappeared over three weeks.","exampleCN":"咳嗽在三周内逐渐消失了。","why":"gradually is the adverb of gradual, from Latin gradus 'step'; each moment adds one small step.","whyCN":"gradually 是 gradual 的副词，出自拉丁 gradus“步”；每一刻只加一小步。"},{"no":"02","title":"Stage by stage","titleCN":"逐步地：按阶段依次推进","definition":"stage by stage, following a planned sequence","definitionCN":"按计划好的次序逐阶段进行","example":"The old equipment was gradually replaced over four years.","exampleCN":"旧设备在四年间被逐步更换。","why":"The adverb can mark deliberate phasing as well as natural drift; the staircase is the same, only the builder differs.","whyCN":"这个副词既可标记自然漂移，也可标记有意分批；阶梯相同，只是建造者不同。"},{"no":"03","title":"Without being noticed","titleCN":"不知不觉地：变化小到没人留意","definition":"so slowly that those involved do not notice the change as it happens","definitionCN":"缓慢到当事者在变化发生时都未察觉","example":"The town gradually lost its young people without anyone planning it.","exampleCN":"这座小镇在无人规划的情况下不知不觉失去了年轻人。","why":"Small steps fall below attention; the adverb often carries this 'we only saw it afterwards' flavour.","whyCN":"小步小到落在注意力之下；这个副词常带“事后才发现”的意味。"},{"no":"04","title":"At a slow rate","titleCN":"缓慢地：速度很低","definition":"at a low speed, with intervals between the changes","definitionCN":"以很低的速度，变化之间有明显间隔","example":"The glacier moves gradually, a few centimetres a day.","exampleCN":"冰川缓慢移动，一天只有几厘米。","why":"Gradual change need not be deliberate; the adverb also simply reports a low rate of movement.","whyCN":"渐进变化未必是有意的；这个副词也可以只报告很低的运动速率。"},{"no":"05","title":"By measured reform","titleCN":"渐进式地：改革上一小步一小步走","definition":"by measured, incremental reform rather than by a single decisive change","definitionCN":"以有节制、增量的改革方式，而非一次决定性变革","example":"The rules were gradually relaxed rather than abolished.","exampleCN":"这些规定是被逐步放宽的，而不是被废除的。","why":"Policy adverbs signal pace; gradually here contrasts with overnight repeal.","whyCN":"政策类副词标示节奏；此处的 gradually 与“一夜废除”相对。"},{"no":"06","title":"Accumulating in effect","titleCN":"一点点累积地：效果叠加起来","definition":"in a way whose effects add up until they become large","definitionCN":"以下述方式：效果不断叠加，直到变得显著","example":"Years of sediment gradually raised the river bed.","exampleCN":"多年泥沙一点点抬高了河床。","why":"Many tiny increments can total a great change, which is why gradual processes surprise people with their final scale.","whyCN":"许多微小增量可以累成巨大变化，这正是渐进过程常以其最终规模令人吃惊的原因。"},{"no":"07","title":"Easing off in slope","titleCN":"平缓地：坡度一点点变化","definition":"of terrain or a curve, changing height with a gentle gradient","definitionCN":"指地形或曲线以平缓的梯度改变高度","example":"The ridge gradually falls away towards the sea.","exampleCN":"山脊朝大海方向平缓地降下去。","why":"The same staircase image applies to ground: each metre drops only a little.","whyCN":"同一阶梯意象也适用于地面：每走一米只下降一点点。"},{"no":"08","title":"Turning into something else","titleCN":"渐渐转为：状态慢慢过渡","definition":"used before verbs of becoming to show a slow transition from one state to another","definitionCN":"用于“变得”类动词前，表示从一种状态缓慢过渡到另一种","example":"The debate gradually became a quarrel.","exampleCN":"这场辩论渐渐变成了一场争吵。","why":"Transitions are where gradual is most useful: the adverb marks that no single moment separates the two states.","whyCN":"过渡正是 gradual 最有用之处：这个副词标记没有任何单一时刻把两种状态分开。"}],"etymology":{"intro":{"en":"Gradually is the English adjective gradual plus the adverb ending -ly, from Old English -līce. The root is Latin gradus 'step'. Dates are approximate.","cn":"gradually 是英语形容词 gradual 加副词词尾 -ly（源自古英语 -līce）。词根为拉丁 gradus“步”。年代为约数。"},"items":[{"era":"LATIN ROOT","en":"gradus 'step, rank' came from gradi 'to walk'. The family reached English through French and directly from Latin at different periods.","cn":"gradus“步、等级”出自 gradi“行走”。这一词族在不同时期经法语以及直接从拉丁语进入英语。"},{"era":"ENGLISH ADJECTIVE","en":"gradual is recorded in the 15th century with the sense 'step by step'. Its -al ending marks a Latin-derived adjective.","cn":"gradual 于 15 世纪有记录，意为“一步一步地”。其 -al 词尾标记拉丁来源形容词。"},{"era":"ADVERB ENDING","en":"-ly goes back to Old English -līce, originally a separate word meaning 'body, form'. It became the standard adverb ending and attached to Latin-derived adjectives without difficulty.","cn":"-ly 可追溯到古英语 -līce，原为意为“身体、形态”的独立词，后成为标准副词词尾，并毫无困难地附着在拉丁来源形容词上。"},{"era":"MODERN USAGE","en":"Gradually became the usual adverb of slow change in ordinary prose, while the adjective remained more formal and often attributive.","cn":"gradually 成为普通书面语中表示缓慢变化的常用副词，而形容词 gradual 更正式，且多作定语。"},{"era":"UNCERTAIN DETAILS","en":"The exact first record of gradually is uncertain, and the deeper Indo-European root behind gradi is reconstructed, not attested.","cn":"gradually 的确切首见记录存疑；gradi 背后的更深印欧词根属重构，并无实际记录。"}]},"similar":{"note":{"en":"The first group contains words easily mistaken for this adverb; the second contains adverbs of slow or staged change.","cn":"第一组是易被误认作本副词的词；第二组是表示缓慢或分阶段变化的副词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"gradual","ipa":"/ˈɡrædʒuəl/","tag":"adjective","definition":"The adjective. Use it after a linking verb or before a noun; use gradually to modify an action verb.","definitionCN":"形容词；跟在系动词后或置于名词前；修饰动作动词时应使用 gradually。"},{"word":"graducally","ipa":"/ɡrəˈdjuːkəli/","tag":"non-word trap","definition":"Not an English word; it is a common misspelling produced by blending gradual and gradually.","definitionCN":"并非英语词，是把 gradual 与 gradually 混写而成的常见错拼。"},{"word":"gradually","ipa":"/ˈɡrædʒuəli/","tag":"this entry","definition":"The correct adverb, with four syllables and no -cal element.","definitionCN":"正确的副词形式，四个音节，不含 -cal 成分。"},{"word":"gravely","ipa":"/ˈɡreɪvli/","tag":"different root","definition":"From grave 'serious', meaning 'seriously'. It sounds close but comes from a different Latin word.","definitionCN":"出自 grave“严重的”，意为“严重地”；读音接近，但来源是另一个拉丁词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"slowly","ipa":"/ˈsləʊli/","tag":"low speed only","definition":"At a low speed; it says nothing about small steps or stages.","definitionCN":"以低速度；不涉及小步或阶段。"},{"word":"progressively","ipa":"/prəˈɡresɪvli/","tag":"forward in stages","definition":"Stage by stage and usually with a direction of advance; often slightly approving.","definitionCN":"逐阶段推进，通常带前进方向，常略含褒义。"},{"word":"incrementally","ipa":"/ɪnˈkreməntəli/","tag":"by small additions","definition":"By small added amounts; technical and neutral about time.","definitionCN":"以小额增量；偏技术，对时间中性。"},{"word":"steadily","ipa":"/ˈstedɪli/","tag":"even pace","definition":"At a constant rate; the pace may be fast as long as it does not vary.","definitionCN":"以恒定速率；只要节奏不变，速度可以很快。"},{"word":"imperceptibly","ipa":"/ˌɪmpəˈseptəbli/","tag":"below notice","definition":"So slightly that it cannot be perceived; it sharpens sense 3 but implies even smaller steps.","definitionCN":"轻微到无法察觉；强化第 3 个义项，但暗示步子更小。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词。"},"normal":[{"en":"gradual + -ly: the adverb form of 'step by step'.","cn":"gradual + -ly：“一步一步”的副词形式。"},{"en":"gradually increase, gradually decline and gradually become are the standard frames.","cn":"gradually increase、gradually decline、gradually become 是标准框架。"},{"en":"Four syllables: gra-DU-al-ly, with no 'cal' sound in it.","cn":"四个音节：gra-DU-al-ly，其中没有“cal”的音。"},{"en":"Use gradually with action verbs and gradual with nouns: the price rose gradually; a gradual rise.","cn":"动作动词配 gradually，名词配 gradual：价格逐渐上涨；一次逐渐的上涨。"},{"en":"The family is gradual, gradually, gradualness, grade, gradient and graduate.","cn":"同族词是 gradual、gradually、gradualness、grade、gradient、graduate。"}],"abstract":[{"en":"Picture a thermometer rising one notch at a time, never jumping.","cn":"想象温度计一格一格上升，从不跳跃。"},{"en":"Picture a photograph taken once a year for fifty years, each frame almost the same as the last.","cn":"想象五十年里每年拍一张照片，每一帧都与上一帧几乎相同。"},{"en":"Picture a stone stair worn down by feet, one shallow dip added each century.","cn":"想象一级石阶被脚步磨低，每个世纪只多出一道浅坑。"}]},"examples":[{"en":"The noise gradually faded as the train moved away.","cn":"随着火车远去，噪音逐渐消失了。"},{"en":"Scientists gradually came to accept that the climate had shifted.","cn":"科学家们渐渐接受了气候已经改变这一事实。"},{"en":"The path climbs gradually for the first kilometre, then turns steep.","cn":"小路在第一公里平缓上升，然后变陡。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“格（gra）拉（dual）一下，慢慢走”——一格一格地前进 → gradually 逐渐地","word":"gradually"},"root":"拉丁 gradus“步”+ -alis → 英语 gradual + -ly（古英语 -līce 副词词尾）。","sensesIntro":{"en":"Eight senses are one adverb doing one job: marking change that arrives in small steps, whether in time, in policy, in slope or in a state of mind.","cn":"八个义项是同一个副词在做一件事：标记以小步到来的变化，无论这变化在时间、政策、坡度还是心境上。"},"semanticMap":{"core":{"en":"CORE IMAGE: a line that rises by tiny increments and never jumps.","cn":"核心意象：一条以小增量上升、从不跳跃的线。"},"chain":["SMALL STEP","OVER TIME","UNNOTICED","SLOW RATE","MEASURED PACE","SLOW TRANSITION"],"branches":[{"senses":"01 · 06","en":"ACCUMULATION: tiny steps add up, and the adverb covers both the adding and the final size.","cn":"累积：微小步子叠加起来，这个副词既覆盖叠加过程，也覆盖最终规模。"},{"senses":"02 · 05","en":"DESIGNED PACE: staged replacement and stepwise reform give the staircase a planner.","cn":"设计节奏：分批更换与逐步改革为这条阶梯安排了设计者。"},{"senses":"03","en":"BELOW ATTENTION: steps small enough to escape notice are the adverb's most characteristic effect.","cn":"低于注意力：小到不被察觉的步子，是这个副词最典型的效应。"},{"senses":"04 · 07","en":"RATE AND GROUND: low speed and gentle gradient are the same measure applied to motion and terrain.","cn":"速率与地面：低速与缓坡是同一尺度分别用于运动与地形。"},{"senses":"08","en":"TRANSITION: before verbs of becoming, the adverb marks a slow crossing between two states.","cn":"过渡：在“变得”类动词前，这个副词标记两种状态之间的缓慢跨越。"}]},"affixes":{"intro":{"en":"Gradually is gradual plus -ly, the standard English adverb ending. The Latin root grad- carries the 'step' image.","cn":"gradually 是 gradual 加 -ly，即标准英语副词词尾。拉丁词根 grad- 承载“步”的意象。"},"latinIntro":{"en":"The grad- family spreads across English verbs and nouns: grade, gradient, gradual, graduate, degrade, upgrade and retrograde.","cn":"grad- 词族遍布英语动词与名词：grade、gradient、gradual、graduate、degrade、upgrade、retrograde。"},"items":[{"word":"gradually","structure":"gradual + -ly (adverb)","meaning":"in small steps over time","meaningCN":"随时间以小步进行","example":"The fog gradually lifted from the valley.","exampleCN":"雾渐渐从谷中散去。"},{"word":"gradual","structure":"grad- + -ual","meaning":"happening step by step","meaningCN":"逐步发生的","example":"A gradual change is easy to miss.","exampleCN":"渐进的变化容易被忽略。"},{"word":"gradualness","structure":"gradual + -ness","meaning":"the quality of being gradual","meaningCN":"渐进性","example":"The gradualness of the rise surprised the engineers.","exampleCN":"上升之缓慢让工程师们吃惊。"},{"word":"grade","structure":"Latin gradus (step)","meaning":"a level or a slope","meaningCN":"等级或坡度","example":"The train slowed on the long grade.","exampleCN":"列车在长坡上减速。"},{"word":"gradient","structure":"grad- + -ient","meaning":"rate of change across distance","meaningCN":"随距离变化的比率","example":"The pressure gradient pushes air inland.","exampleCN":"气压梯度把空气推向内陆。"},{"word":"graduate","structure":"gradus + -ate","meaning":"to move up through the degrees of study","meaningCN":"逐级完成学业；毕业","example":"He graduated with a degree in geology.","exampleCN":"他毕业并取得地质学学位。"},{"word":"degrade","structure":"de- (down) + gradus","meaning":"to step down in rank or quality","meaningCN":"降级；退化","example":"Ultraviolet light degrades the coating.","exampleCN":"紫外线使涂层退化。"},{"word":"upgrade","structure":"up- + gradus","meaning":"to step up to a higher grade","meaningCN":"升级；提升等级","example":"The lab upgraded its microscope last year.","exampleCN":"实验室去年升级了显微镜。"}],"latinEntries":[{"word":"gradus","structure":"gradus, -ūs (n.)","meaning":"step, degree, rank","meaningCN":"步；等级；品级"},{"word":"gradi","structure":"gradi (deponent verb)","meaning":"to walk, to proceed step by step","meaningCN":"行走；逐步前进"},{"word":"-alis","structure":"Latin adjective suffix","meaning":"relating to, of the nature of","meaningCN":"与……有关的、具有……性质的"}]}},{"word":"graphical","ipa_uk":"/ˈɡræfɪkl/","ipa_us":"/ˈɡræfɪkl/","definition_zh":"图表的；图形的；图形界面的；生动细致的","definition_en":"shown by means of diagrams or pictures rather than words and numbers alone, or relating to drawing and visual display","core_image":"一张坐标纸上，数据点被连成折线并加了阴影","scene":"The report presents the results in graphical form, with one chart for each site.","sceneCN":"这里 graphical 是「图表的」（第 1 个义项：用图形呈现数据）；句意：报告以图表形式呈现结果，每个地点配一张图。图中可辨识物件：柱状图、折线、坐标轴、图例、数据标签。","pos":[{"tag":"adj.","zh":"图表的；图形的；图形界面的；生动细致的（多作定语）"}],"collocations":[{"phrase":"graphical representation","zh":"图形表示；图示"},{"phrase":"graphical user interface","zh":"图形用户界面"},{"phrase":"graphical display","zh":"图形显示"},{"phrase":"graphical method","zh":"图解法"},{"phrase":"graphical abstract","zh":"图文摘要（论文的图示概要）"},{"phrase":"graphical model","zh":"图模型（概率与机器学习术语）"}],"forms":[{"label":"比较级（更图形的）","form":"more graphical"},{"label":"最高级（最图形的）","form":"most graphical"},{"label":"副词形式","form":"graphically（以图形方式；生动地）"},{"label":"较短变体","form":"graphic（更常用，兼指“生动的”）"}],"derivatives":[{"word":"graphic","pos":"adj. / n.","zh":"图形的；生动的；图像（更常用变体）"},{"word":"graphics","pos":"n.","zh":"图形学；图像；制图"},{"word":"graph","pos":"n. / v.","zh":"图表；图线；绘成图"},{"word":"graphically","pos":"adv.","zh":"以图形方式；生动地"},{"word":"graphology","pos":"n.","zh":"笔迹学（共用 graph- 词根）"}],"senses":[{"no":"01","title":"Shown as a chart","titleCN":"图表的：用图形呈现数据","definition":"presented through charts, plots or diagrams instead of prose and tables alone","definitionCN":"通过图表、曲线或示意图呈现，而非仅用文字与表格","example":"A graphical summary makes the seasonal pattern obvious at a glance.","exampleCN":"一份图表式摘要让人一眼看出季节规律。","why":"Greek graphein means 'to write or draw', and graphikos meant 'of drawing'; the adjective keeps that drawing sense alive.","whyCN":"希腊 graphein 意为“书写、描绘”，graphikos 意为“与描绘有关的”；这个形容词保留了这一“画”的含义。"},{"no":"02","title":"Of a visual computer interface","titleCN":"图形界面的：用图标与窗口操作","definition":"relating to a computer interface operated through windows, icons and pointers rather than typed commands","definitionCN":"关于通过窗口、图标与指针而非键入命令来操作的计算界面的","example":"The graphical interface lets new users drag files instead of typing paths.","exampleCN":"图形界面让新用户拖放文件，而不必键入路径。","why":"Computing borrowed the word when screens began to draw rather than print, so 'graphical' marks the drawn layer of the machine.","whyCN":"当屏幕开始“绘制”而非“打印”时，计算领域借用了这个词，因此“图形的”标记的是机器中那个被画出来的层面。"},{"no":"03","title":"Of drawing and printmaking","titleCN":"图形艺术的：绘画与版画的","definition":"relating to drawing, printmaking and the visual arts that produce images on a surface","definitionCN":"关于在表面上生成图像的绘画、版画与视觉艺术","example":"The collection covers graphical arts from woodcut to lithography.","exampleCN":"这批藏品涵盖从木刻到石版的图形艺术。","why":"In art history the 'graphic arts' are the arts of the mark made on a plate or block, which is graphein in its oldest sense.","whyCN":"在艺术史中，“图形艺术”指在版或块上留下印记的技艺，正是 graphein 最古老的含义。"},{"no":"04","title":"Vividly detailed","titleCN":"生动细致的：描写如在眼前","definition":"described so vividly that the scene seems drawn before the eyes","definitionCN":"描写得极其鲜活，仿佛画面被画在眼前","example":"His graphical account of the battle left nothing to the imagination.","exampleCN":"他对那场战役的细致描写让人无需再想象。","why":"The shorter form graphic carries this sense most often, but graphical is also used for writing that 'draws' a scene.","whyCN":"较短形式 graphic 最常承载这一义项，但 graphical 也用于形容“把场景画出来”的文字。"},{"no":"05","title":"Of printing and prepress","titleCN":"印刷制版的：印前工艺的","definition":"relating to the production of printing plates and the printing industry","definitionCN":"关于印版制作与印刷行业的","example":"The graphical department checks colour separations before the run.","exampleCN":"制版部门在开印前检查分色。","why":"Printing reproduces drawn or photographed images, so the trade adopted the adjective for its image-making stage.","whyCN":"印刷复制绘制或拍摄的图像，因此这一行业用该形容词指称其制像环节。"},{"no":"06","title":"Of symbols on a surface","titleCN":"图形符号的：以符号代替文字","definition":"relating to symbols and signs used in place of written words","definitionCN":"关于用来替代书面文字的符号与标记的","example":"A graphical sign warned drivers without using any language.","exampleCN":"一个图形标志不用任何语言就警示了司机。","why":"A symbol is a small drawing; wherever meaning is carried by shape rather than letters, the adjective applies.","whyCN":"符号就是一个小小的图画；只要意义由形状而非字母承载，就适用这个形容词。"},{"no":"07","title":"Of computer graphics work","titleCN":"图形处理的：计算机生成图像","definition":"relating to the generation and manipulation of images by computer","definitionCN":"关于用计算机生成与处理图像的","example":"The team wrote a graphical engine for simulating smoke.","exampleCN":"这个团队编写了一个用于模拟烟雾的图形引擎。","why":"Rendering is drawing by calculation, so the computing branch keeps the same root but changes the hand into an algorithm.","whyCN":"渲染是用计算来作画，因此这一计算分支保留同一词根，只把手换成了算法。"},{"no":"08","title":"Turning numbers into pictures","titleCN":"图形化的：把抽象信息画成图","definition":"describing the act of converting abstract data into a visual form that can be read at a glance","definitionCN":"指把抽象数据转化为可一眼读懂的视觉形式","example":"Graphical presentation cut the meeting time by half.","exampleCN":"图形化呈现把会议时间缩短了一半。","why":"Data do not draw themselves; the adjective also names the translation from numbers to marks, which is its most active modern sense.","whyCN":"数据不会自己作图；这个形容词还命名从数字到标记的转换，这正是它最活跃的现代义项。"}],"etymology":{"intro":{"en":"Graphical joins Greek graphikos 'of drawing or writing' with the adjective ending -ical. The shorter graphic came through Latin graphicus. Dates are approximate.","cn":"graphical 由希腊 graphikos“与描绘或书写有关的”加形容词词尾 -ical 构成。较短的 graphic 经拉丁 graphicus 而来。年代为约数。"},"items":[{"era":"GREEK VERB","en":"graphein meant 'to scratch, draw, write'. Its root is often linked to a word for scratching or cutting, but that deeper connection is a reconstruction.","cn":"graphein 意为“刻划、描绘、书写”。其词根常被联系到某个表示“刻、削”的词，但这一更深关联属重构。"},{"era":"GREEK ADJECTIVE","en":"graphikos meant 'skilled in drawing or writing, of pictorial representation'. The noun graphē meant a drawing or a written work.","cn":"graphikos 意为“擅长描绘或书写的、与图像再现有关的”。名词 graphē 指图画或书面作品。"},{"era":"LATIN AND FRENCH","en":"Latin borrowed graphicus, and French produced graphique. English graphic appears in the 17th century with both the 'drawn' and the 'vividly described' senses.","cn":"拉丁语借入 graphicus，法语构成 graphique。英语 graphic 于 17 世纪出现，兼具“图绘的”与“描写生动的”两义。"},{"era":"LONGER VARIANT","en":"graphical arose on the model of other -ical adjectives and became standard in technical phrases such as graphical representation and, later, graphical user interface.","cn":"graphical 按其他 -ical 形容词的模式产生，并在 graphical representation 等技术短语中成为标准，后来又用于 graphical user interface。"},{"era":"COMPUTING","en":"From the 1960s the adjective was attached to displays, terminals and interfaces, giving the modern computing senses.","cn":"自 20 世纪 60 年代起，这个形容词被用于显示器、终端与界面，形成现代计算义项。"},{"era":"UNCERTAIN DETAILS","en":"The deeper origin of graphein is disputed, and the exact first use of graphical rather than graphic in English is uncertain.","cn":"graphein 的更深来源有争议；英语中 graphical 相对 graphic 的确切首用年代存疑。"}]},"similar":{"note":{"en":"The first group holds forms of the same word; the second holds adjectives about visual or vivid presentation.","cn":"第一组是同一词的不同形式；第二组是关于视觉或生动呈现的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"graphic","ipa":"/ˈɡræfɪk/","tag":"shorter and broader","definition":"The shorter form, far more common overall. It covers both 'drawn' and 'vividly explicit', and as a noun means an image.","definitionCN":"较短形式，总体更常用；兼指“图绘的”与“直白生动的”，作名词时指图像。"},{"word":"graphics","ipa":"/ˈɡræfɪks/","tag":"plural noun","definition":"The noun for images, designs or the computing field that produces them. It cannot modify a noun as the adjective does.","definitionCN":"名词，指图像、设计或生成它们的计算领域；不能像形容词那样修饰名词。"},{"word":"graph","ipa":"/ɡræf/","tag":"the object, not the style","definition":"A chart or a network of points and lines. A graph is the thing; graphical describes how something is presented.","definitionCN":"指图表或点线网络；graph 是事物本身，graphical 描述呈现方式。"},{"word":"geographical","ipa":"/ˌdʒiːəˈɡræfɪkl/","tag":"earth, not images","definition":"Relating to places; it shares the -graph- stem but its prefix is geo-, so it describes the earth rather than drawing.","definitionCN":"关于地点的；共用 -graph- 词干，但前缀是 geo-，故描述的是大地而非绘图。"}]},{"heading":"NEAR MEANING","entries":[{"word":"visual","ipa":"/ˈvɪzjuəl/","tag":"of sight","definition":"Relating to seeing in general, including photographs, film and live scenes; graphical is narrower and implies drawn or plotted marks.","definitionCN":"泛指与视觉有关，包括照片、影片与实景；graphical 更窄，暗示绘制或标绘的痕迹。"},{"word":"pictorial","ipa":"/pɪkˈtɔːriəl/","tag":"picture-like","definition":"Presented as pictures or illustrations; more about images than about data plotted on axes.","definitionCN":"以图画或插图形式呈现；更偏图像，而非画在坐标上的数据。"},{"word":"diagrammatic","ipa":"/ˌdaɪəˈɡræmətɪk/","tag":"schematic","definition":"Shown as a simplified schematic drawing of parts and relations; closer to sense 1 but stresses structure over data.","definitionCN":"以简化的部件与关系示意图呈现；接近第 1 个义项，但强调结构而非数据。"},{"word":"vivid","ipa":"/ˈvɪvɪd/","tag":"strong impression","definition":"Producing a strong mental image; it targets the effect on the reader, while graphical targets the means of presentation.","definitionCN":"产生强烈心理画面；着眼于对读者的效果，而 graphical 着眼于呈现手段。"},{"word":"illustrative","ipa":"/ɪˈlʌstrətɪv/","tag":"serving as example","definition":"Serving to explain or exemplify, often with pictures; it adds the purpose of clarifying, which graphical lacks.","definitionCN":"用于解释或举例，常配图；它增加了“说明”的目的，而 graphical 没有。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词。"},"normal":[{"en":"graph- 'write, draw' + -ical: belonging to drawing.","cn":"graph-“书写、描绘”+ -ical：属于图绘的。"},{"en":"graphical user interface, graphical representation and graphical abstract are fixed technical phrases.","cn":"图形用户界面、图形表示、图文摘要是固定技术短语。"},{"en":"The family is graph, graphic, graphics, graphical, graphically and graphology.","cn":"同族词是 graph、graphic、graphics、graphical、graphically、graphology。"},{"en":"graphical is the longer adjective, graphic the shorter and more common one.","cn":"graphical 是较长形容词，graphic 是较短且更常用的形式。"},{"en":"graphical belongs with pictures; geographical belongs with places. Prefix decides.","cn":"graphical 与图有关，geographical 与地点有关；前缀决定词义。"}],"abstract":[{"en":"Picture a column of numbers being folded into a single bar you can see at once.","cn":"想象一列数字被折成一根一眼可见的柱子。"},{"en":"Picture a desktop made of small pictures you can drag instead of typing commands.","cn":"想象一个由小图标组成的桌面，可以拖动而不必键入命令。"},{"en":"Picture a printed plate where the image is cut into the metal before ink touches paper.","cn":"想象一块印版，图像先在金属上刻出，油墨才接触纸张。"}]},"examples":[{"en":"The manual explains each step with a graphical diagram rather than a paragraph.","cn":"这份手册用图形示意而非段落来解释每个步骤。"},{"en":"Modern graphical interfaces made computing accessible to people without training.","cn":"现代图形界面使未经训练的人也能使用计算机。"},{"en":"The paper's graphical abstract summarizes the experiment in one image.","cn":"论文的图文摘要用一幅图概括了整个实验。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“哥（gra）画个图（phical）”——把数字画成图 → graphical 图表的、图形的","word":"graphical"},"root":"希腊 graphein“刻划、描绘、书写”→ graphikos“与描绘有关的”；拉丁 graphicus + 英语 -ical。","sensesIntro":{"en":"Eight senses all turn on one act: making a mark so that something can be seen. Charts, screens, prints, symbols and vivid prose all use that act.","cn":"八个义项都围绕同一个动作：留下痕迹，使某物可见。图表、屏幕、印版、符号与生动文字都使用这一动作。"},"semanticMap":{"core":{"en":"CORE IMAGE: numbers plotted on graph paper and joined into a visible line.","cn":"核心意象：数字被标在坐标纸上，并连成一条看得见的线。"},"chain":["MAKE A MARK","DRAW THE DATA","DRAW ON SCREEN","PRINT THE IMAGE","STAND FOR WITH SIGNS","DESCRIBE VIVIDLY"],"branches":[{"senses":"01 · 08","en":"DATA INTO PICTURE: charting and the deliberate conversion of abstract numbers share one purpose.","cn":"数据成图：作图表与有意把抽象数字转换，共享同一个目的。"},{"senses":"02 · 07","en":"THE DRAWN MACHINE: interfaces and rendering engines both replace the hand with code.","cn":"被绘出的机器：界面与渲染引擎都用代码取代了手。"},{"senses":"03 · 05","en":"THE PRINTED MARK: art prints and commercial prepress both transfer an image to a surface.","cn":"印出的痕迹：艺术版画与商业制版都把图像转移到表面。"},{"senses":"06","en":"SIGN FOR WORD: a symbol is a drawing that carries meaning without letters.","cn":"以形代字：符号就是一幅不用字母也能承载意义的图画。"},{"senses":"04","en":"WORD AS PICTURE: vivid description makes language itself draw.","cn":"文字如画：生动描写让语言本身开始作画。"}]},"affixes":{"intro":{"en":"Graphical is graph- plus -ical. The root appears in dozens of English compounds, usually as -graphy, -graph or -gram.","cn":"graphical 是 graph- 加 -ical。该词根出现在大量英语复合词中，常作 -graphy、-graph 或 -gram。"},"latinIntro":{"en":"Greek graphein reached English through Latin and French in words such as geography, photograph, biography, paragraph, diagram and telegraph.","cn":"希腊 graphein 经拉丁语与法语进入英语，见于 geography、photograph、biography、paragraph、diagram、telegraph 等词。"},"items":[{"word":"graphical","structure":"graph- (draw, write) + -ical","meaning":"shown by drawing or charting","meaningCN":"以绘制或图表方式呈现的","example":"A graphical scale is easier to read than a table.","exampleCN":"图形比例尺比表格更易读。"},{"word":"graphic","structure":"graph- + -ic","meaning":"drawn, or vividly explicit","meaningCN":"图绘的；直白生动的","example":"The article contains graphic images of the eruption.","exampleCN":"这篇文章配有喷发的图像。"},{"word":"graphics","structure":"graphic + -s (noun plural)","meaning":"images and the art of producing them","meaningCN":"图像及制作图像的技术","example":"The game's graphics improved with each release.","exampleCN":"这款游戏的画面每次发布都有改进。"},{"word":"graph","structure":"graph- (drawn mark)","meaning":"a chart or a network of points","meaningCN":"图表；点线网络","example":"The graph plots yield against rainfall.","exampleCN":"这张图绘出产量与降雨的关系。"},{"word":"graphically","structure":"graphical + -ly","meaning":"by drawing; vividly","meaningCN":"以图形方式；生动地","example":"The trend is shown graphically in figure 2.","exampleCN":"该趋势在图 2 中以图形显示。"},{"word":"photograph","structure":"photo- (light) + graph- (draw)","meaning":"a picture drawn by light","meaningCN":"由光绘出的图像；照片","example":"The photograph captured the ash cloud at noon.","exampleCN":"这张照片拍下了正午的火山灰云。"},{"word":"paragraph","structure":"para- (beside) + graph- (written mark)","meaning":"a written section marked off","meaningCN":"标出的书面段落","example":"The second paragraph states the hypothesis.","exampleCN":"第二段陈述了假设。"},{"word":"diagram","structure":"dia- (through) + gram- (drawn thing)","meaning":"a drawn plan showing structure","meaningCN":"显示结构的绘制示意图","example":"The diagram shows where the two faults meet.","exampleCN":"示意图显示两条断层交汇之处。"}],"latinEntries":[{"word":"graphein","structure":"Greek graphein (to scratch, draw, write)","meaning":"to make a mark, to write","meaningCN":"留下痕迹；书写"},{"word":"graphikos","structure":"graphē (drawing, writing) + -ikos","meaning":"skilled in drawing or writing","meaningCN":"擅长描绘或书写的"},{"word":"graphicus","structure":"Latin borrowing of Greek graphikos","meaning":"of drawing or pictorial representation","meaningCN":"与描绘或图像再现有关的"}]}},{"word":"gravitational","ipa_uk":"/ˌɡrævɪˈteɪʃənl/","ipa_us":"/ˌɡrævɪˈteɪʃənl/","definition_zh":"引力的；重力的；万有引力的；由引力造成的","definition_en":"relating to the force by which masses attract one another, or produced by that force","core_image":"一颗小球沿弯曲的网格面滚向中央的大球","scene":"The satellite stays in orbit because gravitational attraction balances its speed.","sceneCN":"这里 gravitational 是「引力的」（第 1 个义项：与质量相互吸引的力有关）；句意：卫星之所以留在轨道上，是因为引力吸引与它的速度相平衡。图中可辨识物件：弯曲的网格面、中央大球、环绕小卫星、轨道线、速度箭头。","pos":[{"tag":"adj.","zh":"引力的；重力的；万有引力的（多作定语）"}],"collocations":[{"phrase":"gravitational force","zh":"引力"},{"phrase":"gravitational field","zh":"引力场"},{"phrase":"gravitational wave","zh":"引力波"},{"phrase":"gravitational pull","zh":"引力牵引；吸引力"},{"phrase":"gravitational lensing","zh":"引力透镜效应"},{"phrase":"gravitational potential energy","zh":"重力势能"}],"forms":[{"label":"比较级（引力更强的）","form":"more gravitational"},{"label":"最高级（引力最强的）","form":"most gravitational"},{"label":"名词形式","form":"gravitation（引力作用；万有引力）"},{"label":"副词形式","form":"gravitationally（在引力上）"}],"derivatives":[{"word":"gravitation","pos":"n.","zh":"引力作用；万有引力"},{"word":"gravity","pos":"n.","zh":"重力；万有引力；严重性"},{"word":"gravitate","pos":"v.","zh":"受引力作用；倾向于"},{"word":"gravitationally","pos":"adv.","zh":"在引力方面"},{"word":"graviton","pos":"n.","zh":"引力子（假设的引力传播粒子）"}],"senses":[{"no":"01","title":"Of the force between masses","titleCN":"引力的：质量之间相互吸引的","definition":"relating to the attraction that any two bodies with mass exert on each other","definitionCN":"关于任何两个有质量的物体相互施加的吸引","example":"The two stars are locked in a gravitational embrace.","exampleCN":"这两颗恒星被引力的拥抱锁定在一起。","why":"gravitation comes from Latin gravitas 'heaviness'; -al makes the adjective, so gravitational marks whatever belongs to that heaviness-driven attraction.","whyCN":"gravitation 出自拉丁 gravitas“沉重”；-al 构成形容词，因此 gravitational 标记属于这种由“重”驱动的吸引的事物。"},{"no":"02","title":"Of Newton's universal law","titleCN":"万有引力定律的：平方反比的那条规律","definition":"relating to the law stating that attraction grows with mass and falls with the square of distance","definitionCN":"关于“引力随质量增大、随距离平方减小”这一定律的","example":"The spacecraft's path was computed with the gravitational law alone.","exampleCN":"这艘飞船的轨迹仅用万有引力定律就算了出来。","why":"Newton's law turned everyday falling into a single rule for all bodies, so the adjective acquired this precise law-based sense.","whyCN":"牛顿定律把日常下落变成适用于一切物体的单一规律，这个形容词于是获得这一精确的“定律”义。"},{"no":"03","title":"Caused by attraction","titleCN":"由引力造成的：潮汐与落体","definition":"produced by gravitational attraction, as in tides or a falling stone","definitionCN":"由引力吸引造成的，如潮汐或落石","example":"Tidal motion is a gravitational effect of the moon on the ocean.","exampleCN":"潮汐运动是月球对海洋产生的引力效应。","why":"Once the force is named, its visible results can be labelled with the adjective: the tide is water answering the moon's pull.","whyCN":"一旦这种力被命名，其可见结果就可用该形容词标记：潮汐就是海水对月球牵引的回应。"},{"no":"04","title":"Of ripples in spacetime","titleCN":"引力波的：时空的涟漪","definition":"relating to waves in spacetime produced by accelerating massive bodies","definitionCN":"关于加速运动的大质量天体在时空中产生的波","example":"The detector recorded a gravitational wave from two merging black holes.","exampleCN":"探测器记录到来自两个并合黑洞的引力波。","why":"General relativity recast gravity as curvature, and a changing curvature travels as a wave; the adjective simply follows that new object.","whyCN":"广义相对论把引力重述为时空弯曲，而变化的弯曲会以波的形式传播；这个形容词便随之指向这一新对象。"},{"no":"05","title":"Of the field around a mass","titleCN":"引力场的：质量周围的作用区域","definition":"relating to the region in which a mass exerts attraction on other bodies","definitionCN":"关于某质量对其他物体施加吸引的作用区域","example":"Inside the gravitational field of the planet, every path bends.","exampleCN":"在这颗行星的引力场中，每条路径都会弯曲。","why":"Physicists describe action at a distance as a field filling space, so the adjective attaches to that region rather than to the force itself.","whyCN":"物理学家把超距作用描述为充满空间的场，因此这个形容词附着于那一区域，而非力的本身。"},{"no":"06","title":"Of bent light","titleCN":"引力透镜的：光被质量折弯","definition":"relating to the bending of light by a massive object, which can magnify images behind it","definitionCN":"关于大质量天体使光弯折、从而放大其后方图像的","example":"A gravitational lens made the distant galaxy appear as a ring.","exampleCN":"一个引力透镜使那个遥远星系呈现为环状。","why":"If mass curves space, light crossing that curve is bent like a ray through glass; astronomers borrowed the lens metaphor.","whyCN":"若质量使空间弯曲，穿过该弯曲的光就像经过玻璃的光线一样被折弯；天文学家借用了透镜的比喻。"},{"no":"07","title":"Irresistibly attractive","titleCN":"比喻：具有强大吸引力的","definition":"used figuratively of a strong pull that draws people, money or attention","definitionCN":"比喻用法，指把人、资金或注意力吸过去的强大牵引","example":"The city has a gravitational pull for graduates from the whole region.","exampleCN":"这座城市对整个地区的毕业生都有一种引力般的吸引力。","why":"The literal force pulls matter without contact; economics and sociology borrow it for any centre that draws things in.","whyCN":"这一字面之力不接触就把物质拉过去；经济学与社会学便借它指任何把事物吸向自己的中心。"},{"no":"08","title":"Of weight and stored energy","titleCN":"重力作用的：重量与势能","definition":"relating to the effect of weight, as in potential energy or the load on a structure","definitionCN":"关于重量效应的，如势能或结构所受的荷载","example":"The dam converts gravitational potential energy into electricity.","exampleCN":"水坝把重力势能转化为电能。","why":"In engineering the same force appears as a load or a store of energy, and the adjective names that practical face.","whyCN":"在工程中，同一股力表现为荷载或能量储存，这个形容词命名的正是它的实用面。"}],"etymology":{"intro":{"en":"Gravitational is gravitation plus -al, built on Latin gravitas 'heaviness' from gravis 'heavy'. The physics sense dates from the Newtonian period. Dates are approximate.","cn":"gravitational 是 gravitation 加 -al，词基为拉丁 gravitas“沉重”，出自 gravis“重的”。物理义形成于牛顿时代。年代为约数。"},"items":[{"era":"LATIN ADJECTIVE","en":"gravis meant 'heavy, weighty, serious'. Its noun gravitas covered physical weight and personal dignity at once, a pairing that still survives in English gravity.","cn":"gravis 意为“重的、有分量的、严肃的”。其名词 gravitas 同时覆盖物理重量与个人威严，这一配对在英语 gravity 中仍然保留。"},{"era":"LATIN NOUN OF ACTION","en":"Late Latin formed gravitatio 'a weighing down', from the verb gravitare. The modern physical sense was read into this pattern much later.","cn":"晚期拉丁由动词 gravitare 构成 gravitatio“压下去、加重”。现代物理义是后来才被读入这一构词模式的。"},{"era":"SEVENTEENTH-CENTURY PHYSICS","en":"English gravitation is recorded in the 17th century, and Newton's Principia of 1687 gave the word its lasting meaning: mutual attraction between all masses.","cn":"英语 gravitation 于 17 世纪有记录；1687 年牛顿的《原理》赋予该词持久含义：一切质量之间的相互吸引。"},{"era":"ADJECTIVE FORM","en":"gravitational is the relational adjective, formed with -al from the noun. It appears later than gravitation and spreads with technical writing.","cn":"gravitational 是由名词加 -al 构成的关系形容词，出现晚于 gravitation，并随技术写作而传播。"},{"era":"MODERN RELATIVITY","en":"After 1915 general relativity added gravitational waves, gravitational lensing and gravitational fields to the adjective's range.","cn":"1915 年之后，广义相对论为这个形容词增添了引力波、引力透镜与引力场等用法。"},{"era":"UNCERTAIN DETAILS","en":"The exact date of the first English use of gravitational is uncertain, and the deeper Indo-European source of gravis is reconstructed rather than attested.","cn":"gravitational 在英语中的确切首用年代存疑；gravis 的更深印欧来源属重构而非有据。"}]},"similar":{"note":{"en":"The first group contains forms from the same root that are easily confused; the second contains related physical and figurative adjectives.","cn":"第一组是同根易混形式；第二组是相关的物理与比喻形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"gravitation","ipa":"/ˌɡrævɪˈteɪʃn/","tag":"the noun","definition":"The process or force of attraction itself. It names the phenomenon; gravitational describes something belonging to it.","definitionCN":"指吸引过程或力本身，命名的是现象；gravitational 描述属于该现象的事物。"},{"word":"gravity","ipa":"/ˈɡrævəti/","tag":"force and seriousness","definition":"The force, especially near a planet, and also seriousness of manner or situation. It is broader than the adjective.","definitionCN":"指力，尤指行星附近的力，也指举止或情势的严肃；比该形容词更宽。"},{"word":"gravitate","ipa":"/ˈɡrævɪteɪt/","tag":"the verb","definition":"To move under gravity, or to be drawn towards something. It is the action form, not the attribute.","definitionCN":"在重力下移动，或被某物吸引；是动作形式，而非属性。"},{"word":"grave","ipa":"/ɡreɪv/","tag":"same Latin root, different noun","definition":"As an adjective, 'serious'; as a noun, 'a burial place' from a different Old English word. Only the adjective shares gravis.","definitionCN":"作形容词意为“严重的”，作名词指“坟墓”且出自另一古英语词；只有形容词与 gravis 同源。"}]},{"heading":"NEAR MEANING","entries":[{"word":"magnetic","ipa":"/mæɡˈnetɪk/","tag":"different force","definition":"Relating to magnetism, which attracts only certain materials and can repel; gravity attracts all mass and never repels.","definitionCN":"关于磁力，只吸引某些材料且可排斥；引力吸引一切质量且从不排斥。"},{"word":"centripetal","ipa":"/ˌsentrɪˈpiːtl/","tag":"inward motion","definition":"Directed towards a centre, describing the motion of a body in a curved path; gravity often supplies it.","definitionCN":"指向中心，描述物体沿曲线路径的运动；常由引力提供。"},{"word":"orbital","ipa":"/ˈɔːbɪtl/","tag":"path, not force","definition":"Relating to an orbit, the path itself rather than the attraction that shapes it.","definitionCN":"关于轨道的，指路径本身，而非塑造路径的吸引。"},{"word":"tidal","ipa":"/ˈtaɪdl/","tag":"one effect","definition":"Relating to tides, one visible gravitational effect rather than the force in general.","definitionCN":"关于潮汐的，指一种可见的引力效应，而非力本身。"},{"word":"weighty","ipa":"/ˈweɪti/","tag":"heavy or serious","definition":"Heavy in weight or serious in importance; it shares the figurative 'heaviness' of gravity but is not a physics term.","definitionCN":"指重量大或重要性高；与 gravity 共享比喻性的“重”，但不是物理术语。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词。"},"normal":[{"en":"grav- 'heavy' + -itation + -al: belonging to heaviness-driven attraction.","cn":"grav-“重”+ -itation + -al：属于由“重”驱动的吸引。"},{"en":"gravitational force, gravitational field and gravitational wave are the core phrases.","cn":"引力、引力场、引力波是核心短语。"},{"en":"The family is gravitation, gravitational, gravity, gravitate, graviton.","cn":"同族词是 gravitation、gravitational、gravity、gravitate、graviton。"},{"en":"gravitational is the adjective; gravitation is the noun; do not use the noun before another noun in careful writing.","cn":"gravitational 是形容词，gravitation 是名词；严谨写作中不要用名词去修饰名词。"},{"en":"The word keeps Latin gravis 'heavy' inside it, which links it to grave and gravity.","cn":"这个词内部保留着拉丁 gravis“重”，因此与 grave、gravity 相连。"}],"abstract":[{"en":"Picture a heavy ball sinking into a stretched sheet while small marbles curve around it.","cn":"想象一颗重球压陷一张绷紧的膜，小弹珠绕着它弯曲滚动。"},{"en":"Picture light from a distant galaxy bending around a cluster and arriving as a ring.","cn":"想象来自遥远星系的光绕过星系团弯折，最终以环状抵达。"},{"en":"Picture a city drawing graduates inward as if it had its own weight.","cn":"想象一座城市像自带重量一样把毕业生吸向中心。"}]},"examples":[{"en":"The probe measured gravitational variations that revealed a buried crater.","cn":"探测器测得的引力变化揭示了一个被埋藏的陨石坑。"},{"en":"Two neutron stars spiralled inward, radiating gravitational waves.","cn":"两颗中子星盘旋靠近，辐射出引力波。"},{"en":"The region's gravitational pull on young workers worries smaller towns.","cn":"该地区对年轻劳动者的吸引力令小城镇担忧。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“哥（gra）拉（vi）太重了”——重的东西把人吸过去 → gravitational 引力的、重力的","word":"gravitational"},"root":"拉丁 gravis“重的”→ gravitas“沉重”→ gravitatio“压重”；英语 gravitation + -al。","sensesIntro":{"en":"Eight senses follow one physical image, a mass bending the space around it, and then extend that pull into waves, fields, bent light and even economics.","cn":"八个义项沿着同一个物理意象展开：一个质量使周围空间弯曲；随后这股牵引被延伸到波、场、被折弯的光，乃至经济。"},"semanticMap":{"core":{"en":"CORE IMAGE: a small ball rolling down a curved grid towards a heavy centre.","cn":"核心意象：一颗小球沿弯曲的网格滚向沉重的中心。"},"chain":["HEAVINESS","MUTUAL ATTRACTION","FALLING AND TIDES","FIELD IN SPACE","RIPPLES IN SPACETIME","BENT LIGHT"],"branches":[{"senses":"01 · 02","en":"THE FORCE AND ITS LAW: the general attraction and Newton's precise rule are one idea at two levels of exactness.","cn":"力与定律：一般吸引与牛顿的精确规律是同一想法在两个精确程度上。"},{"senses":"03 · 08","en":"VISIBLE EFFECTS: tides, falling stones and stored potential energy are the force made observable.","cn":"可见效应：潮汐、落石与储存的势能，是这股力变得可观察。"},{"senses":"04 · 05","en":"RELATIVITY: waves and fields recast attraction as geometry that fills and ripples through space.","cn":"相对论：波与场把吸引重述为充满空间并产生涟漪的几何。"},{"senses":"06","en":"BENT LIGHT: if space curves, light must curve, and a mass becomes a lens.","cn":"弯折的光：若空间弯曲，光必然弯曲，于是质量成了透镜。"},{"senses":"07","en":"FIGURATIVE PULL: any centre that draws people or money borrows the physics.","cn":"比喻性的牵引：任何吸走人或资金的中心都借用了这套物理。"}]},"affixes":{"intro":{"en":"Gravitational is built from the Latin root grav- 'heavy', the noun-forming -itatio and the adjective ending -al.","cn":"gravitational 由拉丁词根 grav-“重”、名词构成成分 -itatio 与形容词词尾 -al 组成。"},"latinIntro":{"en":"Latin gravis and gravitas produced a small English family: gravity, grave, gravitate, gravitation, gravitational and the modern coined graviton.","cn":"拉丁 gravis 与 gravitas 产出一个小型英语词族：gravity、grave、gravitate、gravitation、gravitational，以及现代新造的 graviton。"},"items":[{"word":"gravitational","structure":"gravitation + -al","meaning":"relating to the attraction of masses","meaningCN":"与质量吸引有关的","example":"The gravitational field is strongest near the surface.","exampleCN":"引力场在地表附近最强。"},{"word":"gravitation","structure":"gravitare (to weigh down) + -ation","meaning":"the process of attraction between masses","meaningCN":"质量之间相互吸引的过程","example":"Gravitation holds the planets to their orbits.","exampleCN":"引力把行星维系在轨道上。"},{"word":"gravity","structure":"Latin gravitas (weight, dignity)","meaning":"the force, or seriousness","meaningCN":"重力；也指严肃、严重","example":"Gravity accelerates a falling stone at nine point eight metres per second squared.","exampleCN":"重力使落石以每秒九点八米平方加速。"},{"word":"gravitate","structure":"gravitas + -ate (verb)","meaning":"to move under gravity; to be drawn towards","meaningCN":"在重力下移动；倾向于被吸引","example":"Students gravitate to programmes with clear job prospects.","exampleCN":"学生倾向于流向就业前景明确的专业。"},{"word":"gravitationally","structure":"gravitational + -ly","meaning":"by or in terms of gravitational action","meaningCN":"以引力方式；从引力角度","example":"The pair is gravitationally bound.","exampleCN":"这一对天体在引力上被束缚在一起。"},{"word":"graviton","structure":"grav- + -on (particle suffix)","meaning":"the hypothetical quantum of gravity","meaningCN":"假设的引力量子","example":"No graviton has ever been detected.","exampleCN":"迄今没有任何引力子被探测到。"},{"word":"grave","structure":"Latin gravis (heavy, serious)","meaning":"serious; solemn","meaningCN":"严重的；严肃的","example":"The report raises grave concerns about the dam.","exampleCN":"该报告对大坝提出了严重关切。"},{"word":"aggravate","structure":"ad- (to) + grav- (heavy) + -ate","meaning":"to make heavier or worse","meaningCN":"加重；使恶化","example":"Dry air aggravates the skin condition.","exampleCN":"干燥空气使这种皮肤病加重。"}],"latinEntries":[{"word":"gravis","structure":"gravis, -e (adjective)","meaning":"heavy, weighty, serious","meaningCN":"重的；有分量的；严肃的"},{"word":"gravitas","structure":"gravis + -itas (abstract noun)","meaning":"weight, heaviness, dignity","meaningCN":"重量；沉重；威严"},{"word":"gravitatio","structure":"gravitare + -tio (Late Latin)","meaning":"a weighing down, heaviness","meaningCN":"压重；沉重"}]}},{"word":"gravity","ipa_uk":"/ˈɡrævəti/","ipa_us":"/ˈɡrævəti/","definition_zh":"重力；万有引力；严重性；庄重；重要性","definition_en":"the force that pulls masses towards one another, especially the earth's pull, or the seriousness and weight of a situation or manner","core_image":"一枚苹果直直落向地面，果柄还指着天空","scene":"The apple fell because gravity pulls every mass towards the earth.","sceneCN":"这里 gravity 是「重力」（第 1 个义项：地球对物体的吸引）；句意：苹果之所以落下，是因为重力把每个物体都拉向地球。图中可辨识物件：落下的苹果、地面、重力箭头、树枝、测力计。","pos":[{"tag":"n.","zh":"重力；万有引力；严重性；庄重；重要性（多不可数，指具体重力值时偶作可数）"}],"collocations":[{"phrase":"the force of gravity","zh":"重力；引力"},{"phrase":"gravity of the situation","zh":"形势的严重性"},{"phrase":"centre of gravity","zh":"重心"},{"phrase":"gravity feed","zh":"重力供给（靠自重流动）"},{"phrase":"zero gravity","zh":"零重力；失重"},{"phrase":"with gravity","zh":"庄重地；严肃地"}],"forms":[{"label":"复数（指不同的引力条件或重力值）","form":"gravities（少见，多用于对比不同天体或不同重力场）"},{"label":"形容词","form":"gravitational（引力的）"},{"label":"动词","form":"gravitate（受吸引；倾向）"},{"label":"名词（作用过程）","form":"gravitation（引力作用）"}],"derivatives":[{"word":"gravitational","pos":"adj.","zh":"引力的；重力的"},{"word":"gravitation","pos":"n.","zh":"引力作用；万有引力"},{"word":"gravitate","pos":"v.","zh":"受重力作用；倾向于"},{"word":"grave","pos":"adj.","zh":"严重的；严肃的（同出 gravis）"},{"word":"aggravate","pos":"v.","zh":"加重；使恶化（同出 gravis）"}],"senses":[{"no":"01","title":"The earth's pull","titleCN":"重力：地球把物体往下拉","definition":"the force by which the earth attracts objects towards its centre","definitionCN":"地球把物体吸向其中心的力","example":"Gravity makes a stone accelerate at about ten metres per second squared.","exampleCN":"重力使石块以每秒约十米平方的加速度下落。","why":"Latin gravitas meant 'heaviness', and the physical sense keeps that image: things are heavy because a force pulls them down.","whyCN":"拉丁 gravitas 意为“沉重”，物理义保留了这一意象：物体之所以重，是因为有股力把它们往下拉。"},{"no":"02","title":"Universal attraction","titleCN":"万有引力：一切质量之间的普遍吸引","definition":"the general attraction between all bodies with mass, at any distance","definitionCN":"一切有质量的物体之间在任何距离上的普遍吸引","example":"Gravity between the sun and the earth keeps the year at three hundred and sixty-five days.","exampleCN":"太阳与地球之间的万有引力使一年保持为三百六十五天。","why":"Newton generalized falling to the whole universe, so the same noun that names a dropped stone also names the binding of galaxies.","whyCN":"牛顿把下落推广到整个宇宙，因此同一个名词既命名落下的石头，也命名星系的束缚。"},{"no":"03","title":"Seriousness of a situation","titleCN":"严重性：事态的沉重程度","definition":"the seriousness or severity of a situation, mistake or problem","definitionCN":"情势、错误或问题的严肃与严重程度","example":"Few understood the gravity of the water shortage at the time.","exampleCN":"当时很少有人理解缺水问题的严重性。","why":"gravitas also meant dignity and weight of character; a heavy matter is one that presses on people, so the noun covers seriousness.","whyCN":"gravitas 也指威仪与品格的分量；沉重的事会压在人身上，因此这个名词也覆盖“严重性”。"},{"no":"04","title":"Dignified manner","titleCN":"庄重：举止有分量而不轻浮","definition":"a solemn, dignified manner of behaving or speaking","definitionCN":"举止或言谈严肃、有威仪而不轻浮","example":"She accepted the award with quiet gravity.","exampleCN":"她以平静庄重的态度接受了奖项。","why":"Roman gravitas was a virtue of weighty bearing; English kept that personal sense alongside the physical one.","whyCN":"罗马人的 gravitas 是一种有分量的仪态美德；英语在物理义之外保留了这一人的义项。"},{"no":"05","title":"Importance and weight","titleCN":"重要性：说话或事件的分量","definition":"the importance or influence that gives a statement or event weight","definitionCN":"使言论或事件显得有分量的重要性或影响力","example":"The findings lend gravity to calls for stricter controls.","exampleCN":"这些发现为要求更严格监管的呼声增添了分量。","why":"What has weight presses on decisions; importance is heaviness transferred from the scale to the argument.","whyCN":"有重量之物会压向决策；重要性就是“重”从秤上转移到论证上。"},{"no":"06","title":"Attraction between bodies","titleCN":"天体引力作用：行星与恒星间的牵制","definition":"the mutual attraction that governs orbits, tides and the shape of bodies","definitionCN":"支配轨道、潮汐与天体形状的相互吸引","example":"The moons of Jupiter move under the gravity of the planet.","exampleCN":"木星的卫星在该行星的引力作用下运行。","why":"Astronomy treats the same force as the architect of orbits, so the noun names both the force and its structural work.","whyCN":"天文学把同一股力视为轨道的建筑师，因此这个名词既指力，也指它塑造结构的工作。"},{"no":"07","title":"Measured pull of the ground","titleCN":"重力测量值：某地的重力强度","definition":"in geophysics, the local strength of gravity measured to reveal underground density","definitionCN":"地球物理中测得的局部重力强度，用于揭示地下密度","example":"A gravity survey found a light salt dome under the marsh.","exampleCN":"一次重力测量在沼泽下发现了一个较轻的盐丘。","why":"Because dense rock pulls harder, measuring gravity becomes a way of seeing underground, and 'a gravity' can name a survey reading.","whyCN":"由于致密岩石引力更强，测量重力便成了看穿地下的方法，于是“重力”也可指一次测量读数。"},{"no":"08","title":"A sense of weight","titleCN":"沉重感：心头或手上的压迫","definition":"a felt heaviness, either physical or emotional","definitionCN":"身心所感到的沉重压迫","example":"The gravity in his voice told us the news was bad before he spoke.","exampleCN":"他声音里的沉重感在他开口前就告诉我们消息不好。","why":"The oldest layer of the word is simply 'heaviness', and the felt sense survives in descriptions of mood and bearing.","whyCN":"这个词最古老的一层就是“沉重”，而体感义仍存活于对情绪与仪态的描述中。"}],"etymology":{"intro":{"en":"Gravity comes from Latin gravitas 'weight, dignity', from gravis 'heavy'. English first used it for seriousness, then for the physical force. Dates are approximate.","cn":"gravity 出自拉丁 gravitas“重量、威严”，源自 gravis“重的”。英语先用它表示严肃，后用于物理之力。年代为约数。"},"items":[{"era":"LATIN NOUN","en":"gravitas was formed from gravis 'heavy' with -itas, the suffix that makes abstract nouns. It covered physical weight, moral seriousness and social dignity in one word.","cn":"gravitas 由 gravis“重的”加抽象名词后缀 -itas 构成，一个词同时覆盖物理重量、道德严肃与社会威严。"},{"era":"ENGLISH PERSONAL SENSE","en":"English gravity appears in the 15th century meaning 'seriousness, solemnity'. This remains the everyday non-physical sense.","cn":"英语 gravity 于 15 世纪出现，意为“严肃、庄重”。这一非物理义至今仍是日常用法。"},{"era":"PHYSICAL SENSE","en":"In the 17th century, with Galileo's and Newton's work, the word took on the force that pulls bodies down. Newton's Principia of 1687 fixed its modern use.","cn":"17 世纪，随着伽利略与牛顿的工作，该词获得“把物体往下拉的力”这一含义。1687 年牛顿的《原理》固定了其现代用法。"},{"era":"DERIVED FAMILY","en":"gravitation, gravitational, gravitate and the coined graviton all branch from the same noun in later technical English.","cn":"gravitation、gravitational、gravitate 与新造的 graviton 在后世技术英语中都由同一名词分枝而出。"},{"era":"GEOPHYSICAL USE","en":"The 20th century added gravity survey and gravity anomaly, where the noun names a measured value rather than the force itself.","cn":"20 世纪新增重力测量与重力异常，其中该名词指测得的数值，而非力本身。"},{"era":"UNCERTAIN DETAILS","en":"The deeper Indo-European source of gravis is a reconstruction, and the exact first English use in the physical sense is uncertain.","cn":"gravis 的更深印欧来源属重构；该词在英语中首次用于物理义的确切年代存疑。"}]},"similar":{"note":{"en":"The first group contains words from the same root; the second contains near-synonyms for weight or seriousness.","cn":"第一组是同根词；第二组是表示重量或严肃的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"gravitation","ipa":"/ˌɡrævɪˈteɪʃn/","tag":"the process","definition":"The action or process of attracting, especially in physics. Gravity names the force or the seriousness; gravitation names the working of the force.","definitionCN":"尤指物理中的吸引作用或过程；gravity 指力或严肃性，gravitation 指这股力的运作。"},{"word":"gravitational","ipa":"/ˌɡrævɪˈteɪʃənl/","tag":"adjective","definition":"Relating to gravity, as in gravitational wave. It cannot stand alone as a noun in ordinary use.","definitionCN":"形容词，如引力波；普通用法中不能独立作名词。"},{"word":"gravel","ipa":"/ˈɡrævl/","tag":"different origin","definition":"Small stones; it looks and sounds like gravity but comes from a different word, probably a diminutive of a word for coarse sand.","definitionCN":"小石子；形音近似 gravity，但来源不同，可能出自某个表示粗砂的词的小称形式。"},{"word":"grave","ipa":"/ɡreɪv/","tag":"serious sense only","definition":"The adjective 'serious' shares Latin gravis; the noun 'burial place' does not. Context tells which one is meant.","definitionCN":"形容词“严重的”与拉丁 gravis 同源；名词“坟墓”则不同源。需靠语境区分。"}]},{"heading":"NEAR MEANING","entries":[{"word":"weight","ipa":"/weɪt/","tag":"measurable heaviness","definition":"The force a body exerts on a support, or the importance of something; it covers the same figurative heaviness with less scientific precision.","definitionCN":"物体对支撑物施加的力，或某事物的重要性；它以较低的科学精确度覆盖同样的比喻性“重”。"},{"word":"seriousness","ipa":"/ˈsɪəriəsnəs/","tag":"not a matter of play","definition":"The quality of being earnest or important; it replaces gravity in sense 3 without any physical image.","definitionCN":"认真或重要的性质；可在第 3 个义项上替代 gravity，且不含物理意象。"},{"word":"severity","ipa":"/səˈverəti/","tag":"harsh degree","definition":"The harshness or intensity of something bad; it stresses how bad, while gravity stresses how much it matters.","definitionCN":"坏事之严酷或剧烈；强调“多糟”，而 gravity 强调“多要紧”。"},{"word":"solemnity","ipa":"/səˈlemnəti/","tag":"ceremonial dignity","definition":"The dignity of a formal occasion; it formalizes sense 4 and usually implies ritual.","definitionCN":"正式场合的庄严；是第 4 个义项的正式化，通常暗示仪式。"},{"word":"pull","ipa":"/pʊl/","tag":"everyday attraction","definition":"A force drawing something towards a source; colloquial where gravity is technical.","definitionCN":"把某物拉向来源的力；口语用词，gravity 则是技术用词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词。"},"normal":[{"en":"Latin gravis 'heavy' + -itas: heaviness itself.","cn":"拉丁 gravis“重的”+ -itas：沉重本身。"},{"en":"the force of gravity, centre of gravity and zero gravity are the core physical phrases.","cn":"重力、重心、失重是核心物理搭配。"},{"en":"the gravity of the situation is the standard way to use the seriousness sense.","cn":"the gravity of the situation 是“严重性”义的标准说法。"},{"en":"The family is gravity, gravitation, gravitational, gravitate, graviton.","cn":"同族词是 gravity、gravitation、gravitational、gravitate、graviton。"},{"en":"Do not confuse gravity with gravel: one is a force, the other small stones.","cn":"别把 gravity 与 gravel 混淆：一个是力，一个是小石子。"}],"abstract":[{"en":"Picture an apple hanging, then falling in a straight line towards the centre of the earth.","cn":"想象一只苹果先悬着，随后沿直线落向地球中心。"},{"en":"Picture a brass weight on a scale: the pointer moves because the thing presses down.","cn":"想象秤上的一枚铜砝码：指针动，是因为它向下压。"},{"en":"Picture a room where everyone stops joking when the news is read aloud.","cn":"想象一个房间，当消息被朗读出来时所有人都停止玩笑了。"}]},"examples":[{"en":"Gravity is weaker on the moon, so the same astronaut can jump much higher.","cn":"月球上的重力更弱，所以同一位宇航员能跳得高得多。"},{"en":"No one underestimated the gravity of the drought until the wells ran dry.","cn":"直到水井干涸，人们才意识到这场干旱的严重性。"},{"en":"The architect moved the centre of gravity lower to keep the tower stable.","cn":"建筑师把重心降低，以保证塔身稳定。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“哥（gra）喂（vi）提（ty）不动”——太重提不起来 → gravity 重力、严重性","word":"gravity"},"root":"拉丁 gravis“重的”→ gravitas“重量、威严”+ 英语 -ity；物理义于 17 世纪确立。","sensesIntro":{"en":"Eight senses keep one core, heaviness: what pulls a stone down, what binds a planet, what makes a matter serious, and what a dignified person carries.","cn":"八个义项守住同一个核心——“重”：把石头拉下去的重、束缚行星的重、使事情显得严重的重，以及庄重之人身上承载的重。"},"semanticMap":{"core":{"en":"CORE IMAGE: an apple falling straight down while its stem still points at the sky.","cn":"核心意象：苹果直直落下，果柄仍指向上方天空。"},"chain":["HEAVINESS","EARTH'S PULL","UNIVERSAL ATTRACTION","SERIOUSNESS","DIGNITY","IMPORTANCE"],"branches":[{"senses":"02 · 06","en":"THE FORCE: universal attraction and orbital mechanics are one force at two scales.","cn":"这股力：万有引力与轨道力学，是同一股力在两个尺度上的表现。"},{"senses":"05","en":"MORAL WEIGHT: weighty arguments press on people the way heavy things do.","cn":"道义分量：有分量的论证像重物一样压在人心上。"},{"senses":"04 · 08","en":"BEARING: dignified manner and a felt heaviness in voice are the body's version of gravitas.","cn":"仪态：庄重的举止与声音里的沉重，是 gravitas 在身体上的版本。"},{"senses":"07","en":"MEASUREMENT: dense rock pulls harder, so a gravity reading is a picture of what lies below.","cn":"测量：致密岩石引力更强，因此一次重力读数就是一幅地下图景。"},{"senses":"01 · 03","en":"EVERYDAY BRIDGE: the same word covers a dropped object and a grave matter, which is why it feels natural to say a situation has weight.","cn":"日常桥梁：同一个词既指落下的物体，也指严重的事，因此说某情势“有分量”才显得自然。"}]},"affixes":{"intro":{"en":"Gravity is Latin gravitas, an abstract noun from gravis 'heavy'. English keeps the root in grave, gravitate and aggravate.","cn":"gravity 是拉丁 gravitas，由 gravis“重的”构成的抽象名词。英语在 grave、gravitate、aggravate 中保留该词根。"},"latinIntro":{"en":"The grav- root runs through gravity, gravitation, gravitational, gravitate, grave and aggravate, all sharing the idea of weight pressing down.","cn":"grav- 词根贯穿 gravity、gravitation、gravitational、gravitate、grave、aggravate，都共享“重物下压”的观念。"},"items":[{"word":"gravity","structure":"Latin gravitas (weight, dignity)","meaning":"the force of attraction; seriousness","meaningCN":"吸引之力；严重性","example":"Gravity keeps the satellite from flying off.","exampleCN":"重力使卫星不致飞离。"},{"word":"gravitation","structure":"gravitare + -ation","meaning":"the process of mutual attraction","meaningCN":"相互吸引的过程","example":"Gravitation acts along the line joining the two centres.","exampleCN":"引力沿连接两中心的直线作用。"},{"word":"gravitational","structure":"gravitation + -al","meaning":"relating to gravity","meaningCN":"与重力有关的","example":"The gravitational constant fixes the scale of the force.","exampleCN":"引力常数确定了这股力的尺度。"},{"word":"gravitate","structure":"gravitas + -ate","meaning":"to move towards, as if pulled","meaningCN":"如被吸引般趋向","example":"Investment gravitates to stable currencies.","exampleCN":"投资倾向于流向稳定的货币。"},{"word":"grave","structure":"Latin gravis (heavy, serious)","meaning":"serious, solemn","meaningCN":"严重的；庄严的","example":"The minister spoke in grave tones.","exampleCN":"部长以严肃的语气讲话。"},{"word":"aggravate","structure":"ad- (to) + grav- (heavy) + -ate","meaning":"to make heavier, to worsen","meaningCN":"加重；使恶化","example":"Smoke aggravates the inflammation.","exampleCN":"烟雾使炎症加重。"},{"word":"graviton","structure":"grav- + -on (particle)","meaning":"the hypothetical carrier of gravity","meaningCN":"假设的引力载体粒子","example":"A graviton would have no mass and spin two.","exampleCN":"引力子应当无质量且自旋为二。"},{"word":"centre of gravity","structure":"centre + of + gravity (fixed phrase)","meaning":"the point where weight balances","meaningCN":"重量平衡的点；重心","example":"Lowering the centre of gravity makes the car harder to roll.","exampleCN":"降低重心使这辆车更难翻滚。"}],"latinEntries":[{"word":"gravis","structure":"gravis, -e","meaning":"heavy, weighty, serious","meaningCN":"重的；有分量的；严肃的"},{"word":"gravitas","structure":"gravis + -itas","meaning":"weight, heaviness, dignity","meaningCN":"重量；沉重；威严"},{"word":"gravitare","structure":"gravitas + -are (verb)","meaning":"to weigh down, to be heavy","meaningCN":"压重；沉重"}]}},{"word":"greenhouse","ipa_uk":"/ˈɡriːnhaʊs/","ipa_us":"/ˈɡriːnhaʊs/","definition_zh":"温室；暖房；（作定语）温室的；温室效应的","definition_en":"a glass or plastic building in which plants are grown under controlled warmth, and, as a modifier, the warming effect such a structure illustrates in the atmosphere","core_image":"一间玻璃房里，番茄藤沿绳向上爬，玻璃上凝着水珠","scene":"The seedlings are started in a greenhouse and transplanted to the field in May.","sceneCN":"这里 greenhouse 是「温室」的本义（第 1 个义项：用于育苗的玻璃房）；句意：幼苗先在温室里培育，五月再移栽到田里。图中可辨识物件：玻璃房、番茄苗、浇水壶、温度计、天窗。","pos":[{"tag":"n.","zh":"温室；暖房；玻璃或塑料覆盖的栽培建筑（可数名词，复数形式规则变化）"},{"tag":"adj.","zh":"温室的；温室效应的（多作定语，修饰气体、效应等名词）"}],"collocations":[{"phrase":"greenhouse effect","zh":"温室效应"},{"phrase":"greenhouse gas","zh":"温室气体"},{"phrase":"greenhouse warming","zh":"温室效应导致的升温"},{"phrase":"greenhouse cultivation","zh":"温室栽培"},{"phrase":"greenhouse tomato","zh":"温室番茄"},{"phrase":"global greenhouse","zh":"（比喻）全球温室（指地球大气）"}],"forms":[{"label":"复数","form":"greenhouses"},{"label":"定语用法","form":"greenhouse gas / greenhouse effect（作前置修饰语）"},{"label":"近义复合词","form":"glasshouse / hothouse（玻璃温室；暖房）"},{"label":"相关名词","form":"greenery（绿植；绿意，同出 green）"}],"derivatives":[{"word":"green","pos":"adj. / n.","zh":"绿色的；绿色；草木（本词的第一个构件）"},{"word":"house","pos":"n. / v.","zh":"房屋；容纳（本词的第二个构件）"},{"word":"glasshouse","pos":"n.","zh":"玻璃温室（同义复合词）"},{"word":"hothouse","pos":"n.","zh":"暖房；人工加温的栽培房"},{"word":"greenhouse effect","pos":"n.","zh":"温室效应"}],"senses":[{"no":"01","title":"A glass house for plants","titleCN":"温室：给植物保温的玻璃房","definition":"a building with glass or clear plastic walls in which plants are grown in controlled warmth","definitionCN":"用玻璃或透明塑料围成、在受控温度下栽培植物的建筑","example":"The nursery keeps its orchids in a heated greenhouse all winter.","exampleCN":"苗圃整个冬天都把兰花养在有供暖的温室里。","why":"The word is a plain English compound: a green (plant-filled) house. No Latin element is involved.","whyCN":"这个词是朴素的英语复合词：一间充满绿色植物的房子，其中不含拉丁成分。"},{"no":"02","title":"The greenhouse effect","titleCN":"温室效应：大气像玻璃一样留住热","definition":"the trapping of heat in the atmosphere by gases that let sunlight in but hold back outgoing infrared radiation","definitionCN":"大气中某些气体让阳光进入、却拦截向外散出的红外辐射，从而把热量留住","example":"The greenhouse effect keeps the earth about thirty degrees warmer than it would otherwise be.","exampleCN":"温室效应使地球比没有它时暖约三十度。","why":"A real greenhouse stays warm because glass passes sunlight but slows the escape of heat, and meteorology borrowed the image for the atmosphere.","whyCN":"真实温室之所以保暖，是因为玻璃让阳光进入、却减缓热量逸出；气象学借这一意象描述大气。"},{"no":"03","title":"Greenhouse gases","titleCN":"温室气体：促成该效应的气体","definition":"gases such as carbon dioxide and methane that absorb and re-emit infrared radiation","definitionCN":"二氧化碳、甲烷等吸收并再辐射红外线的气体","example":"Methane is a far stronger greenhouse gas than carbon dioxide per molecule.","exampleCN":"就单个分子而言，甲烷是比二氧化碳强得多的温室气体。","why":"If the effect is named after glass, the gases that produce it inherit the same modifier, becoming greenhouse gases.","whyCN":"既然该效应以玻璃房命名，产生该效应的气体便继承同一修饰语，成为“温室气体”。"},{"no":"04","title":"Grown under cover","titleCN":"温室栽培的：作定语表示来源","definition":"as a modifier, grown or produced inside such a building rather than in open fields","definitionCN":"作修饰语时指在这种建筑内而非露地栽培或生产的","example":"Greenhouse tomatoes ripen earlier but cost more to produce.","exampleCN":"温室番茄成熟更早，但生产成本更高。","why":"A place name easily becomes an adjective: the building that shelters the crop labels the crop.","whyCN":"地点名很容易转为定语：为作物遮护的那座建筑，成了作物的标签。"},{"no":"05","title":"A plastic growing tunnel","titleCN":"塑料大棚：低成本的暖棚","definition":"a low structure covered with plastic film, used on farms as a cheaper form of greenhouse","definitionCN":"覆以塑料薄膜的低矮结构，作为温室的廉价形式用于农场","example":"The farm replaced three greenhouses with long plastic tunnels.","exampleCN":"这家农场用长条塑料大棚取代了三座温室。","why":"The defining feature is enclosure that traps warmth, not the material, so plastic tunnels are still called greenhouses in ordinary speech.","whyCN":"其决定性特征是困住热量的围护，而非材料，因此塑料大棚在日常说法中仍被称作温室。"},{"no":"06","title":"A display house in a garden","titleCN":"展览温室：植物园里的观赏玻璃房","definition":"a large ornamental glasshouse in a botanical garden, built for display and education","definitionCN":"植物园中为展示与教育而建的大型观赏玻璃房","example":"The Victorian greenhouse holds the tropical collection.","exampleCN":"这座维多利亚式温室收藏着热带植物。","why":"Once glasshouses became public architecture, the same word named buildings meant to be visited rather than worked.","whyCN":"当玻璃房成为公共建筑后，同一个词也开始指供人参观而非劳作之用的建筑。"},{"no":"07","title":"A sheltered hothouse environment","titleCN":"比喻：温暖封闭的温室环境","definition":"figuratively, an enclosed setting that protects those inside from harsh outside conditions","definitionCN":"比喻义，指把内部人隔绝于外界严酷条件的封闭环境","example":"Critics say the elite school is a greenhouse that shelters students from real competition.","exampleCN":"批评者说这所精英学校是一座温室，把学生隔绝于真实竞争之外。","why":"Protection from cold becomes protection from difficulty, and the building becomes a metaphor for sheltered upbringing.","whyCN":"挡寒的保护变成挡困难的保护，于是这座建筑成了“被庇护成长”的比喻。"},{"no":"08","title":"The protected-crop industry","titleCN":"温室农业：受控环境下的生产体系","definition":"the sector of agriculture that grows crops under glass or plastic cover","definitionCN":"在玻璃或塑料覆盖下栽培作物的农业部门","example":"Greenhouse production now supplies most winter vegetables in the region.","exampleCN":"温室生产如今供应了该地区大部分冬季蔬菜。","why":"An industry can be named after its characteristic building, so the word also names a whole mode of farming.","whyCN":"一个产业可以用其标志性建筑命名，因此这个词也指整套农业模式。"}],"etymology":{"intro":{"en":"Greenhouse is a native English compound: green plus house. It has no Latin ancestry, so the Latin entries below are empty. Dates are approximate.","cn":"greenhouse 是英语本族复合词：green 加 house，没有拉丁来源，因此下方拉丁条目为空。年代为约数。"},"items":[{"era":"OLD ENGLISH PARTS","en":"grēne 'green, growing' and hūs 'dwelling, shelter' are both Old English words. Neither is borrowed from Latin or Greek.","cn":"grēne“绿色的、生长的”与 hūs“住所、遮蔽物”都是古英语词，二者均非借自拉丁或希腊语。"},{"era":"SEVENTEENTH-CENTURY COMPOUND","en":"The compound greenhouse is recorded in the 17th century for buildings used to overwinter tender plants, at first often called a conservatory or glasshouse.","cn":"复合词 greenhouse 于 17 世纪有记录，指用于让娇嫩植物越冬的建筑，最初常被称为 conservatory 或 glasshouse。"},{"era":"VICTORIAN GLASS","en":"In the 19th century cheap sheet glass and iron frames made large greenhouses common in gardens and botanical institutions.","cn":"19 世纪，廉价的平板玻璃与铁框使大型温室在园林与植物机构中普及。"},{"era":"THE ATMOSPHERIC METAPHOR","en":"Late 19th-century scientists compared the atmosphere to a glass house. The term greenhouse effect became standard in the 20th century; the exact coiner is uncertain.","cn":"19 世纪后期的科学家把大气比作玻璃房。“温室效应”这一术语在 20 世纪成为标准，确切创制者存疑。"},{"era":"CLIMATE POLICY","en":"From the 1980s greenhouse gas and greenhouse warming entered international climate policy, and the modifier spread far beyond horticulture.","cn":"自 1980 年代起，温室气体与温室升温进入国际气候政策，这一修饰语远远超出园艺范围。"},{"era":"UNCERTAIN DETAILS","en":"The first use of greenhouse for a plant house is dated approximately, and the person who first applied the term to the atmosphere is not certainly known.","cn":"greenhouse 指植物栽培房的首见年代只能约略估计；首次将该词用于大气的人并无确证。"}]},"similar":{"note":{"en":"The first group contains words for similar buildings; the second contains related climate terms and metaphors.","cn":"第一组是同类建筑名称；第二组是相关气候术语与比喻用法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"glasshouse","ipa":"/ˈɡlɑːshaʊs/","tag":"same building, different focus","definition":"A glass building for plants; it names the material rather than the greenery. In British slang it can also mean a military prison.","definitionCN":"栽培植物的玻璃建筑；它命名材料而非绿植。英式俚语中也可指军事监狱。"},{"word":"hothouse","ipa":"/ˈhɒthaʊs/","tag":"heated, not glazed","definition":"A heated growing house, often small; it stresses artificial heat and is the commoner metaphor for an overprotected environment.","definitionCN":"常指小型加温栽培房；强调人工加热，也是“过度保护环境”更常见的比喻词。"},{"word":"conservatory","ipa":"/kənˈsɜːvətəri/","tag":"ornamental glass room","definition":"A glass room attached to a house for display plants or leisure; it is architectural rather than agricultural.","definitionCN":"附属于住宅、用于陈列植物或休闲的玻璃房；偏建筑而非农业用途。"},{"word":"greengrocer","ipa":"/ˈɡriːnɡrəʊsə/","tag":"same first element","definition":"A shopkeeper selling vegetables; it shares green but has nothing to do with protected growing.","definitionCN":"卖蔬菜的店主；共用 green，但与保护地栽培无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"greenhouse effect","ipa":"/ˈɡriːnhaʊs ɪˈfekt/","tag":"the atmospheric process","definition":"The warming process itself, not the building; it is the phrase from which the modifier sense of greenhouse derives.","definitionCN":"指升温过程本身，而非建筑；greenhouse 的定语义正是从这一短语衍生。"},{"word":"global warming","ipa":"/ˈɡləʊbl ˈwɔːmɪŋ/","tag":"observed outcome","definition":"The measured rise in planetary temperature; it is the result, while the greenhouse effect is the mechanism.","definitionCN":"实测的行星温度上升；它是结果，而温室效应是机制。"},{"word":"cold frame","ipa":"/kəʊld freɪm/","tag":"unheated shelter","definition":"A low unheated box with a glass lid for protecting seedlings; smaller and simpler than a greenhouse.","definitionCN":"带玻璃盖、不加温的低矮苗箱；比温室更小更简单。"},{"word":"polytunnel","ipa":"/ˈpɒlitʌnl/","tag":"plastic version","definition":"A tunnel of plastic film over hoops; it is the modern cheap equivalent covered by sense 5.","definitionCN":"拱架上覆塑料膜的隧道式大棚；是第 5 个义项所涵盖的现代廉价等价物。"},{"word":"nursery","ipa":"/ˈnɜːsəri/","tag":"plant business","definition":"A place where young plants are raised for sale; it may use greenhouses but names the business, not the building.","definitionCN":"培育幼苗出售的场所；可能使用温室，但命名的是生意而非建筑。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词。"},"normal":[{"en":"green + house: literally a house full of growing green things.","cn":"green + house：字面就是一间充满生长绿意的房子。"},{"en":"greenhouse effect and greenhouse gas are the fixed climate phrases.","cn":"温室效应与温室气体是固定的气候短语。"},{"en":"The plural is greenhouses; the compound takes -es like other -house words.","cn":"复数是 greenhouses；这类 -house 复合词一律加 -es。"},{"en":"Related buildings: glasshouse, hothouse, conservatory, polytunnel, cold frame.","cn":"相关建筑：玻璃温室、暖房、观赏温室、塑料大棚、苗箱。"},{"en":"greenhouse is both a noun and a modifier: a greenhouse, but greenhouse gases.","cn":"greenhouse 既可作名词也可作定语：一座温室，但说温室气体。"}],"abstract":[{"en":"Picture sunlight entering glass and warm air staying behind while the outside stays cold.","cn":"想象阳光穿过玻璃进入，暖空气留在里面，而外面依旧寒冷。"},{"en":"Picture the whole planet wrapped in a thin pane it cannot see.","cn":"想象整个行星被一层它自己看不见的薄玻璃包住。"},{"en":"Picture a student kept so warm and safe indoors that the first cold wind shocks them.","cn":"想象一个学生被养在温暖安全的室内，第一阵冷风便令他震惊。"}]},"examples":[{"en":"The greenhouse is ventilated automatically when the internal temperature passes thirty degrees.","cn":"当内部温度超过三十度时，温室会自动通风。"},{"en":"Carbon dioxide is the greenhouse gas most discussed in climate policy.","cn":"二氧化碳是气候政策中讨论最多的温室气体。"},{"en":"Without the natural greenhouse effect, the planet's average temperature would be well below freezing.","cn":"若没有自然的温室效应，这颗行星的平均温度将远低于冰点。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“绿（green）房子（house）”——绿色植物住的房子 → greenhouse 温室","word":"greenhouse"},"root":"英语本族复合词：green（古英语 grēne“绿的、生长的”）+ house（古英语 hūs“住所、遮蔽物”）；无拉丁词源。","sensesIntro":{"en":"Eight senses all rest on one enclosure: a cover that keeps warmth in. That cover can be glass, plastic, architecture, metaphor, or the whole atmosphere.","cn":"八个义项都立足于同一种围护：一层把热量留在里面的遮蔽。这层遮蔽可以是玻璃、塑料、建筑、比喻，也可以是整个大气。"},"semanticMap":{"core":{"en":"CORE IMAGE: a glass house with condensation on the panes and vines climbing inside.","cn":"核心意象：一间玻璃上凝着水珠、藤蔓在内攀爬的玻璃房。"},"chain":["ENCLOSE","KEEP WARM","GROW PLANTS","COVER THE CROP","TRAP ATMOSPHERIC HEAT","SHELTER FROM HARDSHIP"],"branches":[{"senses":"01 · 06","en":"THE GLASS FORMS: a glass house and a display house share one function, keeping plants warm.","cn":"玻璃形态：栽培温室与展览温室共享同一功能——给植物保温。"},{"senses":"02 · 03","en":"ATMOSPHERE: the glass-house image moves to the sky, and the gases that work it take the same label.","cn":"大气：玻璃房意象移向天空，促成该效应的气体也沿用同一标签。"},{"senses":"04 · 08","en":"PRODUCE AND INDUSTRY: the building names the crop and then the whole sector that grows it.","cn":"产品与产业：这座建筑先命名作物，继而命名整个栽培部门。"},{"senses":"07","en":"METAPHOR: protection from weather becomes protection from difficulty.","cn":"比喻：挡风遮雨的保护变成对困难的隔绝。"},{"senses":"05","en":"THE PLASTIC FORM: a low tunnel of plastic film is the cheap version of the same house.","cn":"塑料形态：覆膜的矮棚是同一座温室的低成本版本。"}]},"affixes":{"intro":{"en":"Greenhouse is a native compound of two Old English words. There is no prefix and no borrowed suffix; the only productive element is the noun house, which also forms glasshouse, hothouse and powerhouse.","cn":"greenhouse 是由两个古英语词构成的本族复合词。它没有前缀，也没有外来后缀；唯一能产的构件是名词 house，它也构成 glasshouse、hothouse、powerhouse。"},"latinIntro":{"en":"No Latin element enters this word. For contrast, the neighbouring climate vocabulary is Latin-derived: atmosphere, radiation, emission and concentration all come through Latin or Greek.","cn":"本词不含任何拉丁成分。作为对照，相邻的气候词汇多为拉丁来源：atmosphere、radiation、emission、concentration 都经拉丁或希腊语而来。"},"items":[{"word":"greenhouse","structure":"green (Old English grēne) + house (Old English hūs)","meaning":"a covered house for growing plants","meaningCN":"用于栽培植物的覆盖建筑","example":"The greenhouse is heated by a small boiler.","exampleCN":"这座温室由一台小锅炉供暖。"},{"word":"greenhouse effect","structure":"greenhouse + effect (noun compound)","meaning":"atmospheric warming by trapped radiation","meaningCN":"被截留的辐射造成的大气升温","example":"The greenhouse effect is natural; its intensification is not.","exampleCN":"温室效应本身是自然的，其加剧则不是。"},{"word":"greenhouse gas","structure":"greenhouse + gas (noun compound)","meaning":"a gas that absorbs infrared radiation","meaningCN":"吸收红外辐射的气体","example":"Water vapour is the most abundant greenhouse gas.","exampleCN":"水汽是最丰富的温室气体。"},{"word":"green","structure":"Old English grēne (growing, green)","meaning":"the colour of growing plants","meaningCN":"生长植物的颜色；绿色","example":"The green leaves shade the soil inside.","exampleCN":"绿叶为内部土壤遮阴。"},{"word":"house","structure":"Old English hūs (dwelling, shelter)","meaning":"a building that shelters","meaningCN":"提供遮蔽的房屋","example":"The old house now serves as a seed store.","exampleCN":"这座老房子如今用作种子库。"},{"word":"glasshouse","structure":"glass + house","meaning":"a glazed growing house","meaningCN":"玻璃覆盖的栽培房","example":"The glasshouse keeps the humidity above eighty per cent.","exampleCN":"玻璃温室把湿度保持在八成以上。"},{"word":"hothouse","structure":"hot + house","meaning":"an artificially heated growing house","meaningCN":"人工加温的栽培房","example":"The hothouse forces lilies into flower in February.","exampleCN":"暖房迫使百合在二月开花。"},{"word":"conservatory","structure":"con- (together) + servare (keep) + -ory","meaning":"a glass room for keeping plants","meaningCN":"保存植物的玻璃房（拉丁来源，作对照）","example":"The conservatory adjoins the main house.","exampleCN":"这座观赏温室与主宅相连。"}],"latinEntries":[]}},{"word":"historically","ipa_uk":"/hɪˈstɒrɪkli/","ipa_us":"/hɪˈstɔːrɪkli/","definition_zh":"历史上；从历史角度；在过去；按历史顺序","definition_en":"in relation to history or the past, or in a way that follows the order of past events","core_image":"一条从左向右延伸的时间轴，轴上每隔一段有一个小旗","scene":"Historically, the river has flooded every spring, though dikes now prevent it.","sceneCN":"这里 historically 是「历史上」（第 1 个义项：在过去的事实中一贯如此）；句意：历史上这条河每年春天都会泛滥，尽管如今堤坝已能阻止它。图中可辨识物件：时间轴、小旗、河流、堤坝、旧照片。","pos":[{"tag":"adv.","zh":"历史上；从历史角度；在过去；按历史顺序（修饰动词、形容词或整句）"}],"collocations":[{"phrase":"historically speaking","zh":"从历史角度说"},{"phrase":"historically low","zh":"处于历史低位的"},{"phrase":"historically high","zh":"处于历史高位的"},{"phrase":"historically important","zh":"具有历史重要性的"},{"phrase":"historically documented","zh":"有历史记载的"},{"phrase":"historically disadvantaged","zh":"历史上处于弱势的"}],"forms":[{"label":"形容词形式","form":"historical（历史的；史学的）"},{"label":"另一形容词","form":"historic（有历史意义的；历史性的）"},{"label":"名词形式","form":"history（历史；历史学）"},{"label":"人物名词","form":"historian（历史学家）"}],"derivatives":[{"word":"historical","pos":"adj.","zh":"历史的；史学的；历史题材的"},{"word":"historic","pos":"adj.","zh":"有历史意义的；历史性的"},{"word":"history","pos":"n.","zh":"历史；历史学；经历"},{"word":"historian","pos":"n.","zh":"历史学家"},{"word":"historicalness","pos":"n.","zh":"历史性（罕用）"}],"senses":[{"no":"01","title":"In the recorded past","titleCN":"历史上：在有记载的过去一直如此","definition":"in the past as recorded, especially as a long-standing pattern","definitionCN":"在有记录的过去，尤指作为一种长期存在的模式","example":"Historically, the valley has produced more apples than grain.","exampleCN":"历史上，这条谷地产的苹果一直多于谷物。","why":"history comes from Greek historia 'inquiry, account'; historically marks what belongs to the recorded account of the past.","whyCN":"history 出自希腊 historia“探究、记述”；historically 标记属于过去之记载的事物。"},{"no":"02","title":"Seen from history's angle","titleCN":"从历史角度看：把长时段作为参照","definition":"when judged over a long span rather than from the present moment alone","definitionCN":"以长时段而非仅以当下为参照来判断","example":"Historically, the two countries have traded more than they have fought.","exampleCN":"从历史角度看，这两国贸易多于交战。","why":"The adverb can frame a judgement rather than state a fact, putting the whole record in view.","whyCN":"这个副词可以框定一次判断而非陈述一个事实，把整部记录纳入视野。"},{"no":"03","title":"In the past, not now","titleCN":"在过去：曾经如此，如今已不同","definition":"formerly, implying that the situation has since changed","definitionCN":"过去曾经，暗含此后情况已经改变","example":"Historically, women were barred from this profession; today they are the majority.","exampleCN":"过去女性被排斥在这一行业之外，如今她们占多数。","why":"When the adverb contrasts with now, it marks a boundary in time; the sentence carries an implicit 'but not anymore'.","whyCN":"当这个副词与“现在”形成对照时，它标记一道时间界线，句子便暗含“如今不再如此”。"},{"no":"04","title":"In order of events","titleCN":"按历史顺序：依时间先后排列","definition":"arranged or narrated in the order in which events occurred","definitionCN":"按事件发生的先后次序排列或叙述","example":"The chapters are organized historically, from settlement to industrialization.","exampleCN":"各章按历史顺序组织，从定居到工业化。","why":"History is also a sequence; the adverb can mark chronology rather than a judgement about the past.","whyCN":"历史同时也是一条序列；这个副词可以标记年代次序，而非对过去的判断。"},{"no":"05","title":"As history is practised","titleCN":"史学上：就史料与考据而言","definition":"in terms of historical method, evidence and scholarship","definitionCN":"就历史学的方法、证据与学术规范而言","example":"Historically, the account rests on two letters and no continuous record.","exampleCN":"就史学而言，这一叙述只建立在两封信上，没有连续记录。","why":"The adverb can point at the discipline's standards rather than at past time itself.","whyCN":"这个副词可以指向学科标准，而非过去的时间本身。"},{"no":"06","title":"By long tradition","titleCN":"传统上：长期沿袭而来","definition":"according to a long-established practice handed down over time","definitionCN":"依照长期沿袭、世代相传的做法","example":"Historically, the land was held in common rather than owned.","exampleCN":"传统上，这片土地是共有的，而非私有的。","why":"Long usage is history in its practical form, so the adverb often means little more than 'as has long been done'.","whyCN":"长期的惯用是历史在实践中的形态，因此这个副词常只表示“按长期以来的做法”。"},{"no":"07","title":"Measured against past levels","titleCN":"按历史标准看：与过去水平相比","definition":"compared with the range of values recorded in earlier periods","definitionCN":"与更早时期记录到的数值范围相比较","example":"Rainfall this year is historically low for the region.","exampleCN":"今年的降雨量对该地区而言处于历史低位。","why":"Statistics needs a baseline, and history supplies it; the adverb marks the comparison that makes 'low' or 'high' meaningful.","whyCN":"统计需要一个基线，而历史提供基线；这个副词标记的正是使“低”或“高”有意义的比较。"},{"no":"08","title":"Within its own period","titleCN":"在历史脉络中：结合时代背景来看","definition":"understood within the conditions and ideas of its own period","definitionCN":"在其所处时代的环境与观念中加以理解","example":"The decision must be read historically, not judged only by today's values.","exampleCN":"这一决定必须放在历史脉络中解读，而不能只用今天的价值标准来评判。","why":"This sense asks the reader to enter a past context, the most methodological use of the adverb.","whyCN":"这一义项要求读者进入过去的语境，是这个副词最具方法论色彩的一种用法。"}],"etymology":{"intro":{"en":"Historically is historical plus -ly. The base is Greek historia 'inquiry, account', through Latin historia and Old French. Dates are approximate.","cn":"historically 是 historical 加 -ly。词基为希腊 historia“探究、记述”，经拉丁 historia 与古法语传入。年代为约数。"},"items":[{"era":"GREEK NOUN","en":"historia meant 'inquiry, investigation, a written account of findings'. It came from histōr 'witness, one who knows', a word of uncertain deeper origin.","cn":"historia 意为“探究、调查、对发现的书面记述”，出自 histōr“见证者、知情者”，该词更深来源不确定。"},{"era":"HERODOTUS","en":"Herodotus used historia in the 5th century BC for his inquiry into the Persian wars, and the word became tied to ordered narration of events.","cn":"公元前 5 世纪，希罗多德用 historia 指他对波斯战争的探究，此词由此与对事件的有序叙述绑定。"},{"era":"LATIN AND FRENCH","en":"Latin historia meant both 'narrative' and 'the knowing of events'. Old French estoire produced English history in the 13th century; story is a doublet from the same source.","cn":"拉丁 historia 兼指“叙述”与“对事件的了解”。古法语 estoire 于 13 世纪产生英语 history；story 是同源的双重借词。"},{"era":"ADJECTIVE AND ADVERB","en":"historical is recorded in the 16th century, and historically follows as its adverb, first in the sense 'according to history'.","cn":"historical 于 16 世纪有记录，historically 作为其副词随后出现，最初意为“依照历史”。"},{"era":"MODERN STATISTICAL USE","en":"In the 20th century historically low and historically high became common in economics and climate writing, where history means the recorded series.","cn":"20 世纪，historically low 与 historically high 在经济与气候写作中普及，其中 history 指记录下来的数据序列。"},{"era":"UNCERTAIN DETAILS","en":"The origin of Greek histōr is disputed, and the exact date of the first English use of historically is uncertain.","cn":"希腊 histōr 的来源有争议；historically 在英语中首次使用的确切年代存疑。"}]},"similar":{"note":{"en":"The first group contains words that are easily swapped with this adverb; the second contains adverbs of time and tradition.","cn":"第一组是易与本副词互换的词；第二组是表示时间与传统的副词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"historical","ipa":"/hɪˈstɒrɪkl/","tag":"adjective","definition":"The adjective. Use it before nouns or after linking verbs; use historically to modify an action or a whole judgement.","definitionCN":"形容词；置于名词前或系动词后；修饰动作或整体判断时应用 historically。"},{"word":"historic","ipa":"/hɪˈstɒrɪk/","tag":"momentous, not 'of history'","definition":"Meaning 'important in history, momentous'. A historic decision is one that will be remembered; a historical decision is merely one made in the past.","definitionCN":"意为“在历史上重要的、有重大意义的”。historic decision 指将被记住的决定；historical decision 只指过去作出的决定。"},{"word":"historically","ipa":"/hɪˈstɒrɪkli/","tag":"this entry","definition":"The adverb of historical, not of historic. For 'in a momentous way' English would normally rephrase.","definitionCN":"是 historical 的副词，而非 historic 的；若要表达“以重大方式”，英语通常改写句子。"},{"word":"histrionically","ipa":"/ˌhɪstriˈɒnɪkli/","tag":"theatrical, different root","definition":"From histrio 'actor', meaning 'in an exaggerated theatrical way'. It sounds close to historically but is unrelated.","definitionCN":"出自 histrio“演员”，意为“以夸张做作的方式”；读音接近 historically，但词源无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"traditionally","ipa":"/trəˈdɪʃənəli/","tag":"handed-down practice","definition":"According to long-established custom; it stresses transmission, while historically stresses the record.","definitionCN":"依照长期形成的习俗；强调传承，而 historically 强调记录。"},{"word":"formerly","ipa":"/ˈfɔːməli/","tag":"previously","definition":"In earlier times, with a clear contrast to now; it lacks the long-record implication of historically.","definitionCN":"在较早时期，与现在形成明确对照；不含 historically 那种“长期记录”的意味。"},{"word":"chronologically","ipa":"/ˌkrɒnəˈlɒdʒɪkli/","tag":"by time order","definition":"In order of dates; it covers sense 4 precisely and says nothing about importance or tradition.","definitionCN":"按日期次序；精确对应第 4 个义项，不涉及重要性或传统。"},{"word":"in the past","ipa":"/ɪn ðə pɑːst/","tag":"plain phrase","definition":"A plain phrase for earlier time; it is vaguer than historically about how far back and how well recorded.","definitionCN":"指较早时间的普通说法；在“多久以前”和“记录多完整”上比 historically 更含糊。"},{"word":"over time","ipa":"/ˈəʊvə taɪm/","tag":"gradual span","definition":"Across a period, without implying records or scholarship; it focuses on gradual development.","definitionCN":"在一段时期内；不暗示记录或学术，而着眼于逐渐发展。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词。"},"normal":[{"en":"historical + -ly: in the manner of history.","cn":"historical + -ly：以历史的方式。"},{"en":"historically low, historically high and historically speaking are the commonest frames.","cn":"historically low、historically high、historically speaking 是最常见的框架。"},{"en":"The family is history, historical, historic, historian, historically.","cn":"同族词是 history、historical、historic、historian、historically。"},{"en":"historically goes with historical, not with historic; keep the pair apart.","cn":"historically 对应的是 historical 而非 historic；这一对要分清。"},{"en":"A sentence with historically usually implies a long record behind the statement.","cn":"含 historically 的句子通常暗示该陈述背后有长期记录。"}],"abstract":[{"en":"Picture a timeline with small flags at every flood, each flag adding to a pattern.","cn":"想象一条时间轴，每次洪水处插一面小旗，旗子累积成一个规律。"},{"en":"Picture a graph line stretching back a century so that today's point can be called low.","cn":"想象一条延伸百年的曲线，今次的点才能被称为低位。"},{"en":"Picture a reader stepping through a doorway into the ideas of another century.","cn":"想象读者穿过一道门，走进另一个世纪的观念之中。"}]},"examples":[{"en":"Historically, the region depended on one crop, and a single bad harvest could empty every store.","cn":"历史上，该地区依赖单一作物，一次歉收就能掏空所有粮仓。"},{"en":"Housing costs are historically high relative to local wages.","cn":"相对于当地工资，住房成本处于历史高位。"},{"en":"The building was listed historically important, though it is only eighty years old.","cn":"这座建筑被列为具有历史重要性，尽管它只有八十年历史。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“history（历史）+ ally（地）”——以历史为伴地看问题 → historically 历史上、从历史角度","word":"historically"},"root":"希腊 historia“探究、记述”← histōr“见证者”；拉丁 historia、古法语 estoire → 英语 history + -ical + -ly。","sensesIntro":{"en":"Eight senses all point backward, but in different ways: as a record, as a long span, as a contrast with now, as a sequence, as a method and as a baseline.","cn":"八个义项都指向后方，但方式各异：作为记录、作为长时段、作为与现在的对照、作为序列、作为方法，以及作为基线。"},"semanticMap":{"core":{"en":"CORE IMAGE: a timeline running left to right, flagged at each past event.","cn":"核心意象：一条自左向右延伸的时间轴，每个过去事件处插着一面旗。"},"chain":["THE RECORDED PAST","LONG SPAN","THEN VERSUS NOW","TIME ORDER","HISTORICAL METHOD","PAST BASELINE"],"branches":[{"senses":"01 · 06","en":"RECORD AND TRADITION: what has been recorded and what has long been done are two forms of the same backward look.","cn":"记录与传统：被记录下来的与长期沿袭的，是同一种回望的两种形态。"},{"senses":"02 · 08","en":"THE LONG VIEW: judging over a span and reading within a past context both widen the frame.","cn":"长视：以长时段作判断、在过去语境中阅读，都是把框架放宽。"},{"senses":"03","en":"THEN AND NOW: the adverb can mark the moment when a former practice ended.","cn":"彼时与此时：这个副词可以标记某一旧做法终止的时刻。"},{"senses":"04 · 05","en":"ORDER AND METHOD: chronology and scholarship are the discipline's two working tools.","cn":"次序与方法：年代排序与学术考据，是这门学科的两件工具。"},{"senses":"07","en":"BASELINE: 'low' or 'high' only means something against the recorded series.","cn":"基线：“低”或“高”只有在与记录序列相比时才有意义。"}]},"affixes":{"intro":{"en":"Historically is history plus -ical plus -ly, all inherited through Latin and French from Greek historia.","cn":"historically 是 history 加 -ical 再加 -ly，整体经拉丁与法语传承自希腊 historia。"},"latinIntro":{"en":"The historia family includes history, story, historical, historic, historian, historiography and the unrelated histrionic, which comes from a different Latin word for actor.","cn":"historia 词族包括 history、story、historical、historic、historian、historiography，以及词源无关的 histrionic（出自另一个表示演员的拉丁词）。"},"items":[{"word":"historically","structure":"historical + -ly","meaning":"in terms of history or the past","meaningCN":"在历史或过去方面","example":"Historically, the two families shared the water.","exampleCN":"历史上，这两家共用这份水源。"},{"word":"historical","structure":"history + -ical","meaning":"relating to history","meaningCN":"与历史有关的","example":"The archive holds the historical records of the port.","exampleCN":"档案馆保存着该港口的历史记录。"},{"word":"historic","structure":"history + -ic","meaning":"momentous, important in history","meaningCN":"有历史意义的；重大的","example":"The treaty was a historic achievement.","exampleCN":"这项条约是一项历史性成就。"},{"word":"history","structure":"Greek historia (inquiry) via Latin","meaning":"the recorded past, or the study of it","meaningCN":"被记录的过去，或对它的研究","example":"History is written from the documents that survive.","exampleCN":"历史是根据留存下来的文献写成的。"},{"word":"historian","structure":"history + -ian (person)","meaning":"a person who studies or writes history","meaningCN":"研究或撰写历史的人","example":"The historian compared tax rolls across three centuries.","exampleCN":"这位历史学家比较了三个世纪的税册。"},{"word":"historiography","structure":"history + -graphy (writing)","meaning":"the writing of history and its methods","meaningCN":"历史编纂及其方法","example":"Historiography examines how records were selected.","exampleCN":"史学史考察记录是如何被筛选的。"},{"word":"story","structure":"Old French estoire < Latin historia","meaning":"a narrative; doublet of history","meaningCN":"叙述；history 的双重借词","example":"The story grew with each retelling.","exampleCN":"这个故事每讲一次就长大一些。"},{"word":"histrionic","structure":"Latin histrio (actor) + -ic","meaning":"theatrical, exaggerated (unrelated root)","meaningCN":"戏剧化的、夸张的（词源无关，作对照）","example":"His histrionic gestures amused the audience.","exampleCN":"他夸张的动作逗乐了观众。"}],"latinEntries":[{"word":"historia","structure":"Greek historia (inquiry, account)","meaning":"an investigation or written account","meaningCN":"探究；书面记述"},{"word":"histōr","structure":"Greek histōr (witness, knowledgeable one)","meaning":"a witness who knows the facts","meaningCN":"见证者；知情者"},{"word":"-icus","structure":"Latin -icus < Greek -ikos","meaning":"relating to","meaningCN":"与……有关的"}]}},{"word":"historical","ipa_uk":"/hɪˈstɒrɪkl/","ipa_us":"/hɪˈstɔːrɪkl/","definition_zh":"历史的；历史学的；历史题材的；历史上真实存在的","definition_en":"relating to history or to the past, based on records of past events, or existing in the past rather than only in imagination","core_image":"一只戴白手套的手翻动发黄的档案，纸边压着一枚旧印章","scene":"The novel is set in a historical period, but its main character never existed.","sceneCN":"这里 historical 是「历史题材的」（第 2 个义项：以某一历史时期为背景）；句意：这部小说以某一历史时期为背景，但主角从未真实存在。图中可辨识物件：旧档案、鹅毛笔、火漆印章、小说封面、年表。","pos":[{"tag":"adj.","zh":"历史的；历史学的；历史题材的；历史上真实存在的（多作定语）"}],"collocations":[{"phrase":"historical context","zh":"历史背景"},{"phrase":"historical record","zh":"历史记录"},{"phrase":"historical novel","zh":"历史小说"},{"phrase":"historical evidence","zh":"史料；历史证据"},{"phrase":"historical linguistics","zh":"历史语言学"},{"phrase":"historical cost","zh":"历史成本（会计术语）"}],"forms":[{"label":"比较级（更具历史性的）","form":"more historical"},{"label":"最高级（最具历史性的）","form":"most historical"},{"label":"副词形式","form":"historically（历史上；从历史角度）"},{"label":"另一形容词","form":"historic（有历史意义的；历史性的）"}],"derivatives":[{"word":"history","pos":"n.","zh":"历史；历史学"},{"word":"historically","pos":"adv.","zh":"历史上；从历史角度"},{"word":"historic","pos":"adj.","zh":"有历史意义的；历史性的"},{"word":"historian","pos":"n.","zh":"历史学家"},{"word":"historiography","pos":"n.","zh":"史学史；历史编纂学"}],"senses":[{"no":"01","title":"Relating to history","titleCN":"历史的：与历史这门学问有关","definition":"relating to history as a field of study or to the study of past events","definitionCN":"与作为研究领域的历史，或与对过去事件的研究有关","example":"The department publishes work on historical method.","exampleCN":"该系发表关于历史方法的成果。","why":"history comes from Greek historia 'inquiry'; historical marks what belongs to that inquiry rather than to the present.","whyCN":"history 出自希腊 historia“探究”；historical 标记属于这一探究、而非当下的事物。"},{"no":"02","title":"Set in a past period","titleCN":"历史题材的：以某一过去时期为背景","definition":"of a novel, film or exhibition, set in an earlier period and built from its details","definitionCN":"指小说、影片或展览以较早时期为背景，并依其细节构建","example":"The museum's historical reconstruction shows a street of nineteen-twenties shops.","exampleCN":"博物馆的历史复原展示了一条二十世纪二十年代的店铺街。","why":"A period setting borrows the record for atmosphere, so the adjective distinguishes it from stories set today.","whyCN":"时期设定借用历史记录来营造氛围，这个形容词因此把它与以当代为背景的故事区分开。"},{"no":"03","title":"Real in the past","titleCN":"历史上真实存在的：确有其人与其事","definition":"existing or happening in the real past rather than being invented","definitionCN":"在真实的过去存在或发生，而非虚构","example":"The character is historical; the love affair is invented.","exampleCN":"这个人物是历史上真实存在的，那段恋情则是虚构的。","why":"When the adjective contrasts with fiction, it certifies that the record, not the imagination, is the source.","whyCN":"当这个形容词与虚构相对时，它确认来源是记录而非想象。"},{"no":"04","title":"Based on records","titleCN":"基于史料的：有据可查的","definition":"supported by documents, evidence and scholarly sources","definitionCN":"有文献、证据与学术来源支持的","example":"The claim is historical in the sense that two ledgers support it.","exampleCN":"这一说法有史料依据，因为有两本账簿支持它。","why":"History is an evidence-based discipline, so the adjective can assert that documentation exists.","whyCN":"历史是一门以证据为基础的学科，因此这个形容词可以断言文献确实存在。"},{"no":"05","title":"Studying change over time","titleCN":"历时演变的：研究时间上的变化","definition":"in linguistics and other fields, studying a subject across its development rather than at one moment","definitionCN":"在语言学等领域，研究某对象随时间的演变，而非某一时刻的状态","example":"Historical linguistics traces how the vowel shifted over four centuries.","exampleCN":"历史语言学追踪这个元音在四百年间如何变化。","why":"The adjective names a method, not just a subject: the historical view compares stages of a single thing.","whyCN":"这个形容词命名的是方法，而不只是对象：历史的视角比较同一事物的各个阶段。"},{"no":"06","title":"Protected for its age","titleCN":"有历史价值的：因年代而受保护","definition":"of a building or site, valued and often legally protected for its age and associations","definitionCN":"指建筑或场所因年代与关联而受重视、常受法律保护","example":"The house is listed as historical and cannot be altered without permission.","exampleCN":"这座房子被列为历史建筑，未经许可不得改动。","why":"Age becomes value when a community decides to keep a place, and the adjective carries that legal weight.","whyCN":"当社区决定保留某地时，年代便成了价值，这个形容词便承载了那份法律分量。"},{"no":"07","title":"Original cost in accounting","titleCN":"历史成本的：按取得时的价格记账","definition":"in accounting, valued at the price originally paid rather than at current market value","definitionCN":"会计中按最初支付的价格而非当前市价计量","example":"The land is carried at historical cost, far below its market value.","exampleCN":"这块土地按历史成本入账，远低于其市价。","why":"Accounting keeps the past in its books: the price at purchase is a fact about then, so the adjective marks that fixed record.","whyCN":"会计把过去留在账上：购入时的价格是关于“当时”的事实，这个形容词标记的正是这一固定记录。"},{"no":"08","title":"Belonging to earlier times","titleCN":"往昔的：属于过去而非现在","definition":"belonging to an earlier time and no longer current","definitionCN":"属于较早时期、如今已不再通行","example":"Historical prices look absurdly low beside today's figures.","exampleCN":"与今天的数字相比，往昔的价格低得离谱。","why":"The simplest reading is just 'of the past'; everything else in the word's range grows from that plain contrast with now.","whyCN":"最简单的读法就是“属于过去的”；该词其余用法都从这一与“现在”的朴素对照生长出来。"}],"etymology":{"intro":{"en":"Historical is history plus -ical, from Greek historia 'inquiry' through Latin and French. It exists beside the shorter historic, with a different sense. Dates are approximate.","cn":"historical 是 history 加 -ical，源自希腊 historia“探究”，经拉丁与法语传入。它与较短的 historic 并存，但含义不同。年代为约数。"},"items":[{"era":"GREEK ROOT","en":"historia meant 'inquiry, investigation, written account', from histōr 'witness'. The deeper origin of histōr is uncertain and often discussed.","cn":"historia 意为“探究、调查、书面记述”，出自 histōr“见证者”。histōr 的更深来源不确定，学界多有讨论。"},{"era":"LATIN AND FRENCH","en":"Latin historia covered both narrative and knowledge of events. Old French estoire gave English history in the 13th century, while story came from the same source by another route.","cn":"拉丁 historia 兼指叙述与对事件的了解。古法语 estoire 于 13 世纪给出英语 history，而 story 经另一路径同源而来。"},{"era":"TWO ADJECTIVES","en":"English formed historic in the 17th century and historical in the 16th. For a long time they were interchangeable.","cn":"英语于 16 世纪构成 historical，17 世纪构成 historic。很长一段时间内二者可互换。"},{"era":"THE MODERN SPLIT","en":"In the 18th and 19th centuries usage settled: historic means 'important in history', historical means 'relating to history or occurring in the past'.","cn":"18 至 19 世纪，用法逐渐固定：historic 意为“在历史上重要的”，historical 意为“与历史有关的或发生在过去的”。"},{"era":"TECHNICAL USES","en":"Historical linguistics, historical cost and historical record fixed the adjective in technical writing during the 19th and 20th centuries.","cn":"历史语言学、历史成本与历史记录在 19 至 20 世纪把该形容词固定于技术写作中。"},{"era":"UNCERTAIN DETAILS","en":"The origin of Greek histōr is disputed, and the exact date when historic and historical stopped being interchangeable varies by source.","cn":"希腊 histōr 的来源有争议；historic 与 historical 不再可互换的确切年代，各家说法不一。"}]},"similar":{"note":{"en":"The first group turns on the historic/historical distinction; the second contains adjectives about the past and about records.","cn":"第一组聚焦 historic 与 historical 的区别；第二组是关于过去与记录的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"historic","ipa":"/hɪˈstɒrɪk/","tag":"momentous","definition":"Meaning 'important enough to be remembered'. A historic speech changes events; a historical speech merely happened in the past.","definitionCN":"意为“重要到值得被记住”。historic speech 改变事态；historical speech 只是发生在过去的演讲。"},{"word":"historical","ipa":"/hɪˈstɒrɪkl/","tag":"this entry","definition":"Meaning 'of history or of the past'. It is the neutral, descriptive member of the pair.","definitionCN":"意为“属于历史或过去的”，是这一对中中性、描述性的成员。"},{"word":"historically","ipa":"/hɪˈstɒrɪkli/","tag":"adverb","definition":"The adverb of historical. It answers 'when' or 'from what standpoint', not 'how important'.","definitionCN":"historical 的副词；回答“何时”或“从什么立场”，而非“多重要”。"},{"word":"historian","ipa":"/hɪˈstɔːriən/","tag":"the person","definition":"A person who studies or writes history. It is a person noun, not a description of a period.","definitionCN":"研究或撰写历史的人；是人物名词，不描述某个时期。"}]},{"heading":"NEAR MEANING","entries":[{"word":"past","ipa":"/pɑːst/","tag":"any earlier time","definition":"Relating to earlier time in general, with no implication of records or scholarship.","definitionCN":"泛指较早时间，不暗示记录或学术。"},{"word":"archival","ipa":"/ɑːˈkaɪvl/","tag":"stored documents","definition":"Relating to archives and stored documents; narrower than historical, which also covers events and methods.","definitionCN":"关于档案馆与所存文献；比 historical 窄，后者还覆盖事件与方法。"},{"word":"documentary","ipa":"/ˌdɒkjuˈmentri/","tag":"based on documents","definition":"Based on or consisting of documents, or a factual film; it stresses the evidence form rather than the past itself.","definitionCN":"以文献为依据或由文献构成，或指纪实影片；强调证据形式而非过去本身。"},{"word":"traditional","ipa":"/trəˈdɪʃənl/","tag":"handed down","definition":"Handed down by custom rather than recovered from records; it describes continuity, not documentation.","definitionCN":"由习俗传承而非从记录中复原；描述的是延续性，而非文献性。"},{"word":"antique","ipa":"/ænˈtiːk/","tag":"old object","definition":"Old and valued as an object; it applies to things, especially furniture, not to periods or methods.","definitionCN":"古老而作为器物受珍视；多用于物品尤其家具，不用于时期或方法。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词。"},"normal":[{"en":"history + -ical: belonging to history.","cn":"history + -ical：属于历史的。"},{"en":"historical context, historical record and historical novel are the standard collocations.","cn":"历史背景、历史记录、历史小说是标准搭配。"},{"en":"The family is history, historical, historic, historically, historian, historiography.","cn":"同族词是 history、historical、historic、historically、historian、historiography。"},{"en":"historical is the neutral adjective; historic claims importance. Test with 'important': if it fits, use historic.","cn":"historical 是中性形容词，historic 声称重要性。可用“重要”来测：若说得通就用 historic。"},{"en":"historical cost is an accounting term; do not read it as 'cost in history'.","cn":"historical cost 是会计术语，不要读成“历史上的成本”。"}],"abstract":[{"en":"Picture a gloved hand turning a page of a ledger that has yellowed for two hundred years.","cn":"想象一只戴手套的手翻动一页泛黄两百年的账簿。"},{"en":"Picture a film set built from photographs, where every chair matches the year in the caption.","cn":"想象一处依据照片搭起的场景，每把椅子都与说明中的年份相符。"},{"en":"Picture the same word written in five centuries on one sheet, each hand changing the vowels.","cn":"想象同一个词在五个世纪里写在同一张纸上，每一笔都改动元音。"}]},"examples":[{"en":"Historical evidence for the treaty is thin: three letters and one seal.","cn":"关于这项条约的史料很单薄：三封信和一枚印章。"},{"en":"The film is historical in its costumes but fictional in its plot.","cn":"这部影片在服装上是历史的，情节却是虚构的。"},{"en":"Historical linguistics explains why the spelling no longer matches the sound.","cn":"历史语言学解释了为什么拼写不再与读音相符。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“history（历史）+ ical（的）”——属于历史的 → historical 历史的、历史题材的","word":"historical"},"root":"希腊 historia“探究、记述”← histōr“见证者”；拉丁 historia、古法语 estoire → history + -ical。","sensesIntro":{"en":"Eight senses cluster around one idea, the recorded past, and then spread into genre, evidence, method, protection, accounting and simply 'then'.","cn":"八个义项围绕一个观念——被记录的过去——展开，随后延伸到体裁、证据、方法、保护、会计，以及朴素的“当时”。"},"semanticMap":{"core":{"en":"CORE IMAGE: a gloved hand turning a yellowed page stamped with an old seal.","cn":"核心意象：一只戴手套的手翻动盖着旧印章的泛黄书页。"},"chain":["THE RECORD","A PAST PERIOD","REAL, NOT INVENTED","EVIDENCE-BASED","CHANGE OVER TIME","WHAT IS PROTECTED"],"branches":[{"senses":"01 · 04","en":"DISCIPLINE AND EVIDENCE: the field and its documentary basis are the same back-and-forth.","cn":"学科与证据：这门学问与其文献基础是同一套往返。"},{"senses":"02 · 03","en":"PERIOD AND TRUTH: a setting in the past and a person who really lived both appeal to the record for authority.","cn":"时期与真实：以过去为背景与确有其人，都向记录借取权威。"},{"senses":"05","en":"METHOD: the historical view compares stages instead of freezing one moment.","cn":"方法：历史的视角比较各阶段，而非冻结某一时刻。"},{"senses":"06 · 07","en":"KEEPING THE PAST: heritage listing and historical cost both fix an earlier value into the present.","cn":"留住过去：遗产登录与历史成本都把较早的价值固定进当下。"},{"senses":"08","en":"PLAIN 'THEN': the simplest sense, from which the specialized ones branch.","cn":"朴素的“当时”：最简单的义项，其余专门义项由此分支。"}]},"affixes":{"intro":{"en":"Historical is history plus -ical. The Greek root historia passed through Latin and French before reaching English.","cn":"historical 是 history 加 -ical。希腊词根 historia 经拉丁与法语才进入英语。"},"latinIntro":{"en":"The historia family in English includes history, story, historical, historic, historian and historiography; the look-alike histrionic belongs to a different Latin word.","cn":"英语中的 historia 词族包括 history、story、historical、historic、historian、historiography；形近的 histrionic 则出自另一个拉丁词。"},"items":[{"word":"historical","structure":"history + -ical","meaning":"relating to history or the past","meaningCN":"与历史或过去有关的","example":"The site has historical value rather than commercial value.","exampleCN":"这处遗址的价值在历史而非商业。"},{"word":"history","structure":"Greek historia via Latin","meaning":"the recorded past or its study","meaningCN":"被记录的过去或其研究","example":"History here means the documents, not the events alone.","exampleCN":"这里的历史指文献，而不只是事件。"},{"word":"historic","structure":"history + -ic","meaning":"momentous, memorable","meaningCN":"重大的；值得记住的","example":"The first landing was a historic moment.","exampleCN":"首次登陆是一个历史性时刻。"},{"word":"historically","structure":"historical + -ly","meaning":"in or by history","meaningCN":"在历史上；按历史","example":"Historically, the port handled all the grain trade.","exampleCN":"历史上，所有谷物贸易都由这个港口处理。"},{"word":"historian","structure":"history + -ian","meaning":"one who studies or writes history","meaningCN":"研究或撰写历史的人","example":"The historian worked from court records.","exampleCN":"这位历史学家依据法庭记录工作。"},{"word":"historiography","structure":"history + -graphy","meaning":"the writing of history","meaningCN":"历史编纂；史学","example":"Historiography asks who was left out of the record.","exampleCN":"史学史追问谁被排除在记录之外。"},{"word":"story","structure":"Old French estoire < historia","meaning":"a narrative; a doublet of history","meaningCN":"叙述；history 的同源双重借词","example":"The story and the history share one ancestor.","exampleCN":"story 与 history 共享同一个祖先。"},{"word":"historicity","structure":"historic + -ity","meaning":"the quality of being historically real","meaningCN":"历史真实性","example":"Scholars debate the historicity of the figure.","exampleCN":"学者们争论这个人物是否真实存在。"}],"latinEntries":[{"word":"historia","structure":"Greek historia (inquiry, account)","meaning":"investigation; a written narrative","meaningCN":"探究；书面叙述"},{"word":"histōr","structure":"Greek histōr (witness)","meaning":"one who knows and can testify","meaningCN":"知情并能作证的人"},{"word":"-icalis","structure":"Latin -icalis < -icus + -alis","meaning":"relating to","meaningCN":"与……有关的"}]}},{"word":"hypothetical","ipa_uk":"/ˌhaɪpəˈθetɪkl/","ipa_us":"/ˌhaɪpəˈθetɪkl/","definition_zh":"假设的；假想的；推测的；（逻辑）假言的","definition_en":"based on a supposition rather than on established fact, or imagined for the purpose of reasoning","core_image":"一张尚属草稿的建筑图，梁柱用虚线画出，旁边标着问号","scene":"The engineers tested a hypothetical failure, in which the eastern wall gives way first.","sceneCN":"这里 hypothetical 是「假想的」（第 2 个义项：现实中未发生、为推理而设想）；句意：工程师测试了一种假想的失效情形，即东墙先垮塌。图中可辨识物件：虚线草图、问号标记、测力箭头、模型楼体、计算纸。","pos":[{"tag":"adj.","zh":"假设的；假想的；推测的；（逻辑）假言的（多作定语，也可作表语）"}],"collocations":[{"phrase":"hypothetical scenario","zh":"假想情景"},{"phrase":"hypothetical question","zh":"假设性问题"},{"phrase":"hypothetical situation","zh":"假设情境"},{"phrase":"hypothetical example","zh":"假设性例子"},{"phrase":"hypothetical model","zh":"假想模型"},{"phrase":"purely hypothetical","zh":"纯属假设"}],"forms":[{"label":"比较级（更假设性的）","form":"more hypothetical"},{"label":"最高级（最假设性的）","form":"most hypothetical"},{"label":"副词形式","form":"hypothetically（假设地；假想地）"},{"label":"名词形式","form":"hypothesis（假设；假说，复数 hypotheses）"}],"derivatives":[{"word":"hypothesis","pos":"n.","zh":"假设；假说（复数 hypotheses）"},{"word":"hypothetically","pos":"adv.","zh":"假设地；假想地"},{"word":"hypothesize","pos":"v.","zh":"假设；提出假说"},{"word":"hypotheses","pos":"n.","zh":"假设的复数形式"},{"word":"hypotheticalness","pos":"n.","zh":"假设性（罕用）"}],"senses":[{"no":"01","title":"Taken as a premise","titleCN":"作为前提的：先假定、后推理","definition":"assumed as a starting point so that consequences can be worked out","definitionCN":"被假定为起点，以便推出后果","example":"The proof begins with a hypothetical population of infinite size.","exampleCN":"这个证明从一个假想的无限大总体开始。","why":"Greek hypothesis was 'a placing under', a base laid beneath an argument; hypothetical marks what serves as that base.","whyCN":"希腊 hypothesis 意为“放在下面”，即铺在论证之下的基础；hypothetical 标记充当这一基础的事物。"},{"no":"02","title":"Imagined, not observed","titleCN":"假想的：现实中没有发生","definition":"existing only in imagination or in a constructed example, not in fact","definitionCN":"仅存在于想象或构造出的例子里，事实中并不存在","example":"Consider a hypothetical town of ten thousand people.","exampleCN":"设想一座有一万人的假想城镇。","why":"A premise must often be invented to test an idea, and the adjective marks that invented status plainly.","whyCN":"为检验一个想法，前提常须被发明出来，这个形容词便直接标记那种“被发明”的状态。"},{"no":"03","title":"Not yet established","titleCN":"推测的：尚未得到证实","definition":"proposed as a possible explanation but not yet confirmed by evidence","definitionCN":"作为可能的解释提出，但尚未获证据确认","example":"The link between the two events remains hypothetical.","exampleCN":"这两个事件之间的联系仍属推测。","why":"A hypothesis sits below proof: it is supported enough to be worth testing, but not enough to be called fact.","whyCN":"假说位于证明之下：它得到足以值得检验的支持，但还不足以被称为事实。"},{"no":"04","title":"If-then in logic","titleCN":"逻辑假言的：如果……那么……","definition":"in logic, describing a conditional statement of the form 'if A then B'","definitionCN":"逻辑中指“如果前一条件成立、则后一结果成立”形式的条件陈述","example":"A hypothetical proposition is true unless its antecedent is true and its consequent false.","exampleCN":"假言命题除在“前件真而后件假”时，均为真。","why":"Logic names conditionals hypothetical because the second clause is placed under the first, exactly as the Greek word suggests.","whyCN":"逻辑学把条件句称为假言，因为后件被置于前件之下，正合希腊词的字面。"},{"no":"05","title":"A question about an unreal case","titleCN":"假设性提问：法律与调查中的虚拟情形","definition":"of a question that asks what would follow in a situation that did not occur","definitionCN":"指询问在未曾发生的情形下会怎样的提问","example":"The lawyer put a hypothetical question to the witness about a later departure.","exampleCN":"律师向证人提出了一个关于更晚出发情形的假设性问题。","why":"Courts and interviews use invented cases to probe reasoning without asserting facts, which is why the label matters legally.","whyCN":"法庭与访谈用虚构情形探查推理而不主张事实，这正是该标签在法律上重要的原因。"},{"no":"06","title":"Idealized for a model","titleCN":"理论模型的：为建模而理想化","definition":"describing an idealized case used in a model, with complicating details deliberately removed","definitionCN":"描述模型中使用的理想化情形，复杂细节被有意去除","example":"The hypothetical frictionless surface lets students isolate the force.","exampleCN":"假想的无摩擦表面让学生得以单独考察这股力。","why":"Modelling needs clean cases; hypothetical marks the deliberate simplification that makes calculation possible.","whyCN":"建模需要干净的情形；hypothetical 标记的正是使计算可行的有意简化。"},{"no":"07","title":"What might have been","titleCN":"反事实的：与现实相反的设想","definition":"describing a counterfactual case in which events went differently from what actually happened","definitionCN":"描述与现实发生情况相反的反事实情形","example":"A hypothetical early warning would have emptied the town before the wave.","exampleCN":"一个假想的早期预警本可在浪到之前疏散全镇。","why":"Reasoning about causes often requires imagining the same situation minus one factor, and that imagined version is hypothetical.","whyCN":"对因果的推理常需想象去掉某一因素的同一情形，而被想象出的那一版就是假想的。"},{"no":"08","title":"Hedged in tone","titleCN":"试探性的：为缓和语气而虚拟","definition":"used to soften a proposal or suggestion by presenting it as merely imagined","definitionCN":"通过把提议说成仅仅是设想来缓和语气","example":"Hypothetically, we could move the deadline to June.","exampleCN":"假设一下，我们可以把截止日期挪到六月。","why":"Saying a plan is hypothetical lowers its force, inviting discussion without commitment.","whyCN":"把计划说成假设性的，会降低其强制力，从而在不作承诺的情况下邀请讨论。"},{"no":"09","title":"In need of testing","titleCN":"待检验的：可被实验推翻","definition":"describing a statement framed so that evidence could in principle refute it","definitionCN":"描述一种在原则上可被证据推翻的陈述","example":"A good hypothetical claim tells you what observation would prove it wrong.","exampleCN":"一个好的假设性论断会告诉你什么观察能证明它错了。","why":"Science values hypotheses that risk failure; the adjective marks claims open to testing rather than settled truths.","whyCN":"科学重视有失败风险的假说；这个形容词标记的是可受检验的论断，而非已定的真理。"}],"etymology":{"intro":{"en":"Hypothetical comes from Greek hypothetikos, built on hypothesis 'a placing under' from hypo- 'under' and thesis 'a placing'. Dates are approximate.","cn":"hypothetical 出自希腊 hypothetikos，词基为 hypothesis“放在下面”，由 hypo-“在下”与 thesis“放置”构成。年代为约数。"},"items":[{"era":"GREEK VERB","en":"tithenai meant 'to place, put'. With the prefix hypo- 'under' it produced hypotithenai 'to place underneath, to assume as a basis'.","cn":"tithenai 意为“放置、摆放”。加前缀 hypo-“在下”，构成 hypotithenai“置于下方、作为基础而假定”。"},{"era":"GREEK NOUN","en":"hypothesis named a base or a supposition laid under an argument. In Aristotle and later writers it also covered a starting premise in geometry and rhetoric.","cn":"hypothesis 指铺在论证之下的基础或假定。在亚里士多德及后世作者那里，它也指几何与修辞中的起始前提。"},{"era":"LATIN AND ENGLISH","en":"Latin borrowed hypothesis, and English took it in the 16th century. The plural hypotheses keeps the Greek -es ending.","cn":"拉丁语借入 hypothesis，英语于 16 世纪引入。复数 hypotheses 保留希腊语 -es 词尾。"},{"era":"ADJECTIVE FORM","en":"Greek hypothetikos 'fit for a supposition' gave Latin hypotheticus and English hypothetical, recorded from the 16th century.","cn":"希腊 hypothetikos“适于作假设的”给出拉丁 hypotheticus 与英语 hypothetical，后者于 16 世纪有记录。"},{"era":"SCIENTIFIC METHOD","en":"From the 17th century the word was tied to experimental science, where a hypothesis is a testable proposal rather than a settled truth.","cn":"自 17 世纪起，该词与实验科学绑定，其中假说是可检验的提议，而非已定的真理。"},{"era":"UNCERTAIN DETAILS","en":"The original technical force of hypothesis in Greek geometry is debated, and the deeper Indo-European root of tithenai is reconstructed rather than attested.","cn":"hypothesis 在希腊几何中的原始术语含义有争议；tithenai 的更深印欧词根属重构而非有据。"}]},"similar":{"note":{"en":"The first group contains forms from the same hypothesis family; the second contains adjectives about possibility, supposition and fiction.","cn":"第一组是同出 hypothesis 词族的词；第二组是关于可能性、假定与虚构的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"hypothesis","ipa":"/haɪˈpɒθəsɪs/","tag":"the noun","definition":"The supposition itself. Its plural is hypotheses, not hypothesises; hypothetical is the adjective built on it.","definitionCN":"指假设本身；复数是 hypotheses，不是 hypothesises；hypothetical 是由它构成的形容词。"},{"word":"hypothetically","ipa":"/ˌhaɪpəˈθetɪkli/","tag":"adverb","definition":"The adverb meaning 'by supposition'. It often opens a sentence that softens a proposal.","definitionCN":"副词，意为“假设地”；常置于句首以缓和提议。"},{"word":"hypothesize","ipa":"/haɪˈpɒθəsaɪz/","tag":"the verb","definition":"To propose a hypothesis. It names the act; hypothetical describes the status of what is proposed.","definitionCN":"提出假说；命名的是动作，hypothetical 描述所提之物的状态。"},{"word":"hypothetic","ipa":"/ˌhaɪpəˈθetɪk/","tag":"rarer variant","definition":"A rare shorter form of hypothetical, mostly found in older technical prose.","definitionCN":"hypothetical 的罕见短形式，多见过时的技术文本。"}]},{"heading":"NEAR MEANING","entries":[{"word":"theoretical","ipa":"/ˌθɪəˈretɪkl/","tag":"model-based","definition":"Based on theory rather than practice; it can describe a well-established framework, while hypothetical stresses that the case is merely supposed.","definitionCN":"基于理论而非实践；可描述成熟框架，而 hypothetical 强调该情形仅为假定。"},{"word":"supposed","ipa":"/səˈpəʊzd/","tag":"believed, maybe wrongly","definition":"Believed to be the case, often with doubt; it records belief rather than a deliberate premise.","definitionCN":"被认为是如此，常含怀疑；记录的是信念，而非有意设定的前提。"},{"word":"imaginary","ipa":"/ɪˈmædʒɪnəri/","tag":"not real at all","definition":"Existing only in imagination, with no claim to possible reality; stronger and often dismissive.","definitionCN":"仅存在于想象，并不声称可能为真；语气更强，常含贬义。"},{"word":"possible","ipa":"/ˈpɒsəbl/","tag":"could happen","definition":"Capable of happening; it asserts a real chance, while hypothetical only asks what would follow if.","definitionCN":"有可能发生；断言存在真实机会，而 hypothetical 只问“若如此会怎样”。"},{"word":"speculative","ipa":"/ˈspekjələtɪv/","tag":"risky guess","definition":"Based on conjecture with little evidence; it judges the quality of the guess, which hypothetical does not.","definitionCN":"基于证据稀少的猜测；它在评判猜测的质量，而 hypothetical 不作此评判。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词。"},"normal":[{"en":"hypo- 'under' + thesis 'placing': a supposition placed under an argument.","cn":"hypo-“在下”+ thesis“放置”：铺在论证之下的假定。"},{"en":"hypothetical scenario, hypothetical question and purely hypothetical are the core frames.","cn":"假想情景、假设性问题、纯属假设是核心框架。"},{"en":"The family is hypothesis, hypotheses, hypothesize, hypothetical, hypothetically.","cn":"同族词是 hypothesis、hypotheses、hypothesize、hypothetical、hypothetically。"},{"en":"Remember the plural: one hypothesis, two hypotheses.","cn":"记住复数：一个 hypothesis，两个 hypotheses。"},{"en":"hypothetical asks 'what if'; theoretical asks 'according to the model'.","cn":"hypothetical 问“若如此会怎样”，theoretical 问“按模型如何”。"}],"abstract":[{"en":"Picture a foundation stone laid under a building that has not yet been designed.","cn":"想象一块奠基石被铺在一座尚未设计完的建筑之下。"},{"en":"Picture a sketch drawn in dashed lines, each beam labelled with a question mark.","cn":"想象一张用虚线画成的草图，每根梁上都标着问号。"},{"en":"Picture two paths splitting at a stone: one taken, one only imagined.","cn":"想象两条路在一块石头处分岔：一条走过，一条只在想象中。"}]},"examples":[{"en":"The class worked through a hypothetical epidemic to see how fast a response would be needed.","cn":"课堂上演练了一场假想疫情，以看清需要多快的应对。"},{"en":"His explanation is still hypothetical; no experiment has confirmed it.","cn":"他的解释仍属假设，尚无实验证实。"},{"en":"In a hypothetical proposition, the 'if' clause supplies the condition.","cn":"在假言命题中，“如果”小句提供条件。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“嗨（hy）破（po）题（thetical）”——先假设一个题目再想答案 → hypothetical 假设的、假想的","word":"hypothetical"},"root":"希腊 hypothesis“置于下方”← hypo-“在下”+ thesis“放置”（tithenai“放”）；希腊 hypothetikos → 拉丁 hypotheticus → 英语 -al。","sensesIntro":{"en":"Nine senses all rest on one gesture: a premise is laid under a question so that consequences can be followed. Logic, law, modelling and polite hedging each use that gesture.","cn":"九个义项都立足于同一个动作：把一个前提铺在问题之下，以便顺出后果。逻辑、法律、建模与礼貌的缓和都使用这一动作。"},"semanticMap":{"core":{"en":"CORE IMAGE: a foundation stone under a building that exists only as a dashed sketch.","cn":"核心意象：一块奠基石，托着一座只用虚线画出的建筑。"},"chain":["PLACE UNDER","ASSUME A PREMISE","IMAGINE THE CASE","AWAIT PROOF","IF-THEN FORM","HEDGE A PROPOSAL"],"branches":[{"senses":"01 · 06","en":"THE BASE: a premise under an argument and an idealization inside a model are both stones laid first.","cn":"基底：论证之下的前提与模型内的理想化，都是先铺下的石头。"},{"senses":"02 · 07","en":"THE UNREAL CASE: an invented town and a counterfactual warning both exist only in the mind.","cn":"非真实情形：虚构的城镇与反事实的预警都只存在于心里。"},{"senses":"03 · 09","en":"BEFORE PROOF: an unconfirmed link and a testable claim are two stages of the same waiting room.","cn":"证明之前：未获确认的联系与可检验的论断，是同一间等候室的两个阶段。"},{"senses":"04","en":"LOGIC: the consequent is placed under the antecedent, so 'if' builds the staircase literally.","cn":"逻辑：后件被置于前件之下，“如果”把阶梯造得字面可见。"},{"senses":"05 · 08","en":"SOCIAL USES: courts probe with invented cases, and speakers use the same device to keep a proposal soft.","cn":"社会用法：法庭用虚构情形探查，说话人用同一装置让提议保持柔和。"}]},"affixes":{"intro":{"en":"Hypothetical is hypo- 'under' plus thesis 'a placing' plus -ical. Greek thesis is also the source of thesis, theme and synthetic.","cn":"hypothetical 是 hypo-“在下”加 thesis“放置”再加 -ical。希腊 thesis 也是 thesis、theme、synthetic 的来源。"},"latinIntro":{"en":"Greek thesis 'a placing' supplied a wide English family through Latin: thesis, hypothesis, synthesis, parenthesis, prosthesis and theme.","cn":"希腊 thesis“放置”经拉丁语衍生出宽泛的英语词族：thesis、hypothesis、synthesis、parenthesis、prosthesis、theme。"},"items":[{"word":"hypothetical","structure":"hypo- + thesis + -ical","meaning":"based on a supposition","meaningCN":"以假定为基础的","example":"The case is hypothetical, but the maths is real.","exampleCN":"这个情形是假想的，但数学是真的。"},{"word":"hypothesis","structure":"hypo- (under) + thesis (placing)","meaning":"a supposition laid under an argument","meaningCN":"铺在论证之下的假定；假说","example":"The hypothesis predicts a rise of two degrees.","exampleCN":"该假说预测升温两度。"},{"word":"hypotheses","structure":"Greek plural of hypothesis","meaning":"more than one supposition","meaningCN":"多个假说","example":"Both hypotheses fit the first year of data.","exampleCN":"两个假说都符合第一年的数据。"},{"word":"hypothesize","structure":"hypothesis + -ize (verb)","meaning":"to propose as a supposition","meaningCN":"提出假设","example":"Researchers hypothesize a hidden fault.","exampleCN":"研究者假设存在一条隐伏断层。"},{"word":"hypothetically","structure":"hypothetical + -ly","meaning":"by way of supposition","meaningCN":"以假设方式","example":"Hypothetically, the cost could double.","exampleCN":"假设而言，成本可能翻倍。"},{"word":"synthesis","structure":"syn- (together) + thesis (placing)","meaning":"a putting together","meaningCN":"把各部分放在一起；综合","example":"The synthesis combines both models.","exampleCN":"这一综合结合了两个模型。"},{"word":"parenthesis","structure":"para- (beside) + en- + thesis","meaning":"a placing beside; a bracketed aside","meaningCN":"放在旁边；插入语","example":"The parenthesis can be removed without harm.","exampleCN":"这个插入语删去也无妨。"},{"word":"theme","structure":"Greek thema < tithenai (to place)","meaning":"something placed down as a subject","meaningCN":"被放下的主题","example":"Loss is the theme of the whole novel.","exampleCN":"失去是整部小说的主题。"}],"latinEntries":[{"word":"hypothesis","structure":"hypo- (under) + thesis (placing)","meaning":"a base or supposition laid under something","meaningCN":"置于下方的基础或假定"},{"word":"tithenai","structure":"Greek tithenai (to place)","meaning":"to put, to set down","meaningCN":"放置；安放"},{"word":"hypothetikos","structure":"hypothesis + -ikos","meaning":"fit for a supposition","meaningCN":"适于作假设的"}]}}]);
